_engine = None

# Token the VPN renderers emit in place of a real PSK: __GATESHIFT_PSK_<hash>__.
# Carries the tunnel identity (vpn_hash) but no secret, so it is safe in the
# generated/previewed/audited config and round-trips through the browser. The
# real PSK is substituted server-side, just before the live push (deploy_push).
_PSK_TOKEN_RE = re.compile(r"__GATESHIFT_PSK_([0-9a-fA-F]+)__")
_VPN_PSK_PLACEHOLDER = "GATESHIFT-PLACEHOLDER-PSK-CHANGE-ME"


def _inject_push_secrets(config: dict, source_id: int, platform: str) -> dict:
    """Resolve __GATESHIFT_PSK_<hash>__ tokens in a freshly-received push config
    to the operator's stored PSKs (decrypted server-side, in memory only). A
    tunnel with no stored PSK - or storage being unconfigured - resolves to the
    placeholder, exactly as before. Single-pass substitution so an injected
    secret is never re-scanned. Returns a NEW dict; the caller's token-config
    (the one that round-tripped the browser / would be audited) is untouched.

    The secret is escaped for the CONFIG FORMAT it lands in so an arbitrary PSK
    (quotes, backslashes, angle brackets) can't corrupt the payload: PA config
    sections are XML, Forti/CP sections are JSON strings (json.loads'd by the
    push). The placeholder is plain ASCII → safe either way."""
    if not isinstance(config, dict) or not config:
        return config
    # Fast-path: nothing to do unless a token is actually present.
    if not any(isinstance(v, str) and "__GATESHIFT_PSK_" in v for v in config.values()):
        return config
    secrets: dict[str, str] = {}
    try:
        with get_engine().connect() as conn:
            rows = conn.execute(text(
                "SELECT LOWER(HEX(vpn_hash)), secret_enc FROM fw_vpn_tunnel_secrets "
                "WHERE device_id = :d"
            ), {"d": source_id}).fetchall()
        for h, enc in rows:
            pt = secrets_util.decrypt(enc)
            if pt is not None:
                secrets[h.lower()] = pt
    except Exception:
        secrets = {}

    def _escape(s: str) -> str:
        if platform == "panw":
            return html_mod.escape(s, quote=False)   # XML element text: & < >
        # Forti/CP: embed inside an existing JSON string literal → escape and
        # strip json.dumps' surrounding quotes.
        return json.dumps(s)[1:-1]

    def _sub(m: "re.Match") -> str:
        pt = secrets.get(m.group(1).lower())
        return _escape(pt) if pt is not None else _VPN_PSK_PLACEHOLDER

    return {
        k: (_PSK_TOKEN_RE.sub(_sub, v) if isinstance(v, str) else v)
        for k, v in config.items()
    }


def _load_push_certs(source_id: int) -> dict:
    """Build the VPN identity-cert map for a push: {vpn_hash_hex: {cert_name,
    cert_pem, key_pem}}, decrypting the stored key server-side (in memory only).
    Empty if storage is unconfigured / nothing uploaded / a key won't decrypt.
    Passed to driver.push() so the cert-import step can provision the gateway
    identity. The key never touches the client, the DB-in-clear, or the audit."""
    out: dict[str, dict] = {}
    try:
        with get_engine().connect() as conn:
            rows = conn.execute(text(
                "SELECT LOWER(HEX(vpn_hash)), cert_name, cert_pem, key_enc "
                "FROM fw_vpn_tunnel_certs WHERE device_id = :d"
            ), {"d": source_id}).fetchall()
    except Exception:
        return out
    for h, name, cert_pem, key_enc in rows:
        key_pem = secrets_util.decrypt(key_enc)
        if key_pem and name and cert_pem:
            out[h.lower()] = {"cert_name": name, "cert_pem": cert_pem, "key_pem": key_pem}
    return out


def get_engine():
    global _engine
    if _engine is None:
        # Prefer the unprivileged application account (DB_USER/DB_PASSWORD,
        # granted only on this schema). Falls back to root for installations
        # that predate the dedicated user, so an upgrade doesn't strand them.
        user = os.getenv("DB_USER") or "root"
        pw   = (os.getenv("DB_PASSWORD")
                if os.getenv("DB_USER")
                else None) or os.getenv("MARIADB_ROOT_PASSWORD", "")
        host = os.getenv("DB_HOST", "mariadb")
        port = os.getenv("DB_PORT", "3306")
        name = os.getenv("DB_NAME", "gateshift")
        _engine = create_engine(
            f"mysql+pymysql://{urllib.parse.quote_plus(user)}:{urllib.parse.quote_plus(pw)}"
            f"@{host}:{port}/{name}",
            pool_pre_ping=True,
        )
    return _engine


@asynccontextmanager
async def lifespan(_app):
    # Enterprise modules (manager-deploy: Panorama / FortiManager) self-register
    # their driver subclasses here IF present + licensed; absent → pure Community
    # Edition. The CE drivers are already registered at import time, so the EE
    # subclasses can extend them. See deploy.manager_backends.
    try:
        import enterprise  # self-registers driver subclasses + config builders
        enterprise.init_app(_app, templates)  # + discover routes + template fragment
        templates.env.globals["app_edition"] = "Enterprise Edition"  # About dialog
    except Exception:
        pass
    _ensure_sequence_column()
    _ensure_source_type_columns()
    _ensure_content_hash_column()
    _ensure_dhcp_column()
    _ensure_iface_properties_column()
    _ensure_iface_enabled_column()
    _ensure_route_metric_column()
    _ensure_route_type_column()
    _backfill_connected_routes()
    _ensure_nat_hash_column()
    _backfill_nat_hash()
    _ensure_nat_rule_overrides_table()
    _ensure_pbf_rules_table()
    _ensure_pbf_overrides_table()
    _ensure_ssl_rules_table()
    _ensure_ssl_overrides_table()
    _ensure_iface_overrides_table()
    _ensure_vpn_tunnels_table()
    _ensure_vpn_overrides_table()
    _ensure_vpn_secrets_table()
    _ensure_vpn_certs_table()
    _ensure_vpn_traffic_selectors_column()
    _ensure_active_routes_table()
    _ensure_negate_columns()
    _ensure_seq_num_columns()
    _ensure_schedule_columns()
    _ensure_schedule_overrides_table()
    _ensure_schedule_intervals_migrated()
    _ensure_identity_columns()
    _ensure_identity_overrides_table()
    _ensure_rule_aggregates_table()
    _backfill_rule_aggregates_if_empty()
    _ensure_nat_evidence_table()
    _ensure_zone_override_multi_width()
    _ensure_zone_is_external_column()
    _backfill_nat_evidence_if_empty()
    _backfill_zone_is_external_once()
    _ensure_tags_tables()
    _rehydrate_tag_catalog_from_overrides()
    _ensure_log_overrides_table()
    _ensure_track_overrides_table()
    _ensure_security_profile_overrides_table()
    _ensure_service_overrides_table()
    _ensure_tp_layer_config_table()
    _ensure_url_category_override_table()
    _ensure_deploy_jobs_table()
    _migrate_overrides_to_rule_hash()
    _migrate_endpoint_pairs_schema()
    _migrate_qf_last_seen_days_to_date()
    # DDL migrations - each may trigger implicit commits in MariaDB, so run first
    with get_engine().begin() as conn:
        _ensure_devices_table(conn)
        _ensure_vendor_capabilities_table(conn)
        _ensure_imported_tables(conn)
        _ensure_raw_objects_table(conn)   # Optimization O-0: raw snapshot + anchor
        _ensure_optimize_pending_table(conn)  # Optimization CP-A1: staged CP delete session
        _ensure_optimize_backups_table(conn)  # Optimization FT-A1: Forti pre-delete backup
        _ensure_scopes_table(conn)            # Panorama-source PS-0a: multi-scope model
        _ensure_interface_tables(conn)
        _ensure_object_tables(conn)
        _ensure_deploy_settings_table(conn)
        _ensure_v2_tables(conn)
        _ensure_target_discover_table(conn)
        _reset_modules_to_off(conn)
    # Data migration - backfill import_zone_name for existing rows.
    # Re-backfill: reset wrong values (where import_zone_name == zone_name but
    # actual traffic-log zone names differ) so the improved backfill can fix them.
    # Then propagate current zone names to traffic_logs / imported_rules.
    try:
        with get_engine().begin() as conn:
            _re_backfill_import_zone_names(conn)
            _backfill_import_zone_names(conn)
            _propagate_zone_renames(conn)
    except Exception:
        pass
    _ensure_iface_deploy_columns()
    yield


