# ── About / version info ──────────────────────────────────────────────
# Single source of truth: webui/VERSION - line 1 = version, optional
# line 2 = the BSL change date. Dev trees carry "<ver>-dev" and no date;
# release-publish-prepare.sh stamps both into the export (same values as
# the LICENSE stamp). Edition flips to Enterprise when the enterprise
# module loads in lifespan.
def _read_version_info() -> tuple[str, str | None]:
    try:
        with open("VERSION") as f:
            lines = [ln.strip() for ln in f.readlines()]
        ver = lines[0] if lines and lines[0] else "dev"
        chg = lines[1] if len(lines) > 1 and lines[1] else None
        return ver, chg
    except Exception:
        return "dev", None


APP_VERSION, _APP_LICENSE_CHANGE_DATE = _read_version_info()
templates.env.globals["app_version"] = APP_VERSION
templates.env.globals["app_license_change_date"] = _APP_LICENSE_CHANGE_DATE
templates.env.globals["app_edition"] = "Community Edition"


def _fmt_rel_time(ts) -> str:
    if not ts:
        return "never"
    now = datetime.datetime.now(ts.tzinfo) if getattr(ts, "tzinfo", None) else datetime.datetime.now()
    delta = now - ts
    secs = int(delta.total_seconds())
    if secs < 60:
        return "just now"
    if secs < 3600:
        m = secs // 60
        return f"{m} min ago"
    if secs < 86400:
        h = secs // 3600
        return f"{h} h ago"
    days = secs // 86400
    return f"{days} {'day' if days == 1 else 'days'} ago"


templates.env.filters["rel_time"] = _fmt_rel_time

# Cache-bust for /static/app.css - the file gets rebuilt by tailwindcss at
# container start, but the browser only knows to refetch when the URL
# changes. Mtime as a query-string makes every rebuild force a refetch
# without weakening conditional-GET on unchanged builds.
def _static_version() -> str:
    # Both stylesheets share the version param - bust on whichever moved last
    # (tokens.css edits used to keep serving stale from browser caches).
    v = 0
    for f in ("static/app.css", "static/tokens.css"):
        try:
            v = max(v, int(os.path.getmtime(f)))
        except OSError:
            pass
    return str(v)
templates.env.globals["static_version"] = _static_version()


def _negate_btn(rhash: str | None, aspect: str, active, manual_source: str | None,
                  target_platform: str | None = None, kind: str = "security") -> str:
    """Jinja-callable wrapper. Returns empty when no rhash (sub-rules in
    accumulated views can be hash-less) or when target doesn't support
    the aspect AND nothing is set (no Drift). When target doesn't support
    but flag is set → Drift-`(!)`-Marker rendered."""
    if not rhash or aspect not in _NEGATE_ASPECTS:
        return ""
    support = _negate_aspects_support(target_platform, kind)
    drift_reason = support.get(aspect)
    return _render_negate_button(
        rhash, aspect, bool(active),
        manual=(manual_source == "manual"),
        drift_reason=drift_reason,
        target_platform=target_platform,
    )


# Registered after _render_negate_button is defined below via direct add
# in the same module - Jinja closures over the global at render time, so
# function-pointer is fine even if defined later.
def _negate_btn_proxy(rhash, aspect, active, manual_source,
                       target_platform=None, kind="security"):
    return _negate_btn(rhash, aspect, active, manual_source,
                        target_platform=target_platform, kind=kind)
templates.env.globals["negate_btn"] = _negate_btn_proxy


def _nat_negate_btn(nat_id, aspect: str, active, manual_source: str | None,
                     target_platform: str | None = None) -> str:
    """Jinja-callable wrapper for NAT-rule negate pills. Returns empty when
    no nat_id or aspect is unsupported AND nothing set."""
    if not nat_id or aspect not in _NEGATE_ASPECTS:
        return ""
    support = _negate_aspects_support(target_platform, "nat")
    drift_reason = support.get(aspect)
    return _render_negate_button(
        str(nat_id), aspect, bool(active),
        manual=(manual_source == "manual"),
        drift_reason=drift_reason,
        endpoint=f"/api/nat-rules/{nat_id}/negate/{aspect}",
        target_platform=target_platform,
    )
templates.env.globals["nat_negate_btn"] = _nat_negate_btn

