def _load_zone_colors(conn, device_id: int | None = None) -> dict[str, str]:
    """Return {zone_name: tone-name} mapping from fw_zones.

    Tone is one of the token .chip.<tone> classes (trust/wan/dmz/pub/any/
    red/amber/teal/pink/purple). Falls back to dmz (blue) when the stored
    color isn't in ZONE_PALETTE. When device_id is given, only that
    device's zones are loaded.
    """
    try:
        if device_id is not None:
            rows = conn.execute(text(
                "SELECT name, color FROM fw_zones WHERE device_id = :did"
            ), {"did": device_id}).fetchall()
        else:
            rows = conn.execute(text("SELECT name, color FROM fw_zones")).fetchall()
        result = {}
        for name, color in rows:
            p = ZONE_PALETTE.get(color, ZONE_PALETTE["blue"])
            result[name] = p["tone"]
        return result
    except Exception:
        return {}


def _load_zones(conn, device_id: int | None = None) -> list[dict]:
    """Return list of zone dicts from fw_zones for a given device.

    Each row's `properties` is decoded to a dict and enriched with derived
    field `members` (list of interface names attached to this zone).

    `properties` is the canonical container for vendor-prefixed zone
    metadata (e.g. `pa_zone_type`, `pa_zone_protection_profile`,
    `forti_intrazone_block`, …). It is populated at source-import time by
    `_write_collect_result` from the collector's zones-list - no read-time
    backfill from `fw_imported_objects` (which would re-mutate state at
    GET-time and conflict with feedback_no_page_render_side_effects).
    """
    try:
        if device_id is not None:
            rows = conn.execute(text(
                "SELECT id, device_id, name, color, properties, import_zone_name, is_external "
                "FROM fw_zones WHERE device_id = :did ORDER BY name"
            ), {"did": device_id}).mappings().all()
        else:
            rows = conn.execute(text(
                "SELECT id, device_id, name, color, properties, import_zone_name, is_external "
                "FROM fw_zones ORDER BY name"
            )).mappings().all()

        zones: list[dict] = []
        for r in rows:
            z = dict(r)
            # Decode JSON properties → dict (or {})
            props = z.get("properties")
            if isinstance(props, str):
                try:
                    props = json.loads(props) if props else {}
                except Exception:
                    props = {}
            z["properties"] = props or {}
            zones.append(z)

        if not zones:
            return zones

        # Derive: members per zone from fw_interfaces
        zone_members: dict[tuple[int, str], list[str]] = {}
        try:
            iface_rows = conn.execute(text(
                "SELECT device_id, zone_name, interface_name FROM fw_interfaces "
                "WHERE zone_name IS NOT NULL AND zone_name != ''"
                + (" AND device_id = :did" if device_id is not None else "")
                + " ORDER BY interface_name"
            ), ({"did": device_id} if device_id is not None else {})).fetchall()
            for did, zname, iname in iface_rows:
                zone_members.setdefault((did, zname), []).append(iname)
        except Exception:
            pass

        for z in zones:
            key = (z["device_id"], z["name"])
            z["members"] = zone_members.get(key, [])

        return zones
    except Exception:
        return []


def _load_nat_rules(conn, device_id: int | None = None) -> list[dict]:
    """Return list of NAT-rule dicts from fw_nat_rules for a device.

    JSON columns (src_zones, dst_zones, orig_src, orig_dst, orig_service,
    properties) are decoded to Python lists/dicts. Order is by `position`.

    negate_{source,destination,service} are COALESCE'd against the matching
    JSON slot in fw_nat_rule_overrides.properties so user-toggled values
    overlay the imported flags. `negate_override_source` carries the
    overlay source marker ('manual' / 'auto' / NULL).
    """
    sql = (
        "SELECT n.id, n.device_id, n.position, n.name, n.nat_type, n.disabled, "
        "LOWER(HEX(n.nat_hash)) AS nat_hash, "
        # Route-derive overlay (Auto-derive button): the stored interface-mode
        # zones (port1) win over the raw imported zones (trust) so the Forti
        # policy-NAT correlation matches the security rules' derived interfaces.
        "COALESCE(novr.src_zones, n.src_zones) AS src_zones, "
        "COALESCE(novr.dst_zones, n.dst_zones) AS dst_zones, "
        "n.interface_name, "
        "n.orig_src, n.orig_dst, n.orig_service, "
        "n.trans_src, n.trans_src_type, n.trans_dst, n.trans_dst_port, "
        "n.description, n.properties, "
        "COALESCE("
        "  CAST(JSON_UNQUOTE(JSON_EXTRACT(novr.properties, '$.negate_source')) AS UNSIGNED),"
        "  n.negate_source) AS negate_source, "
        "COALESCE("
        "  CAST(JSON_UNQUOTE(JSON_EXTRACT(novr.properties, '$.negate_destination')) AS UNSIGNED),"
        "  n.negate_destination) AS negate_destination, "
        "COALESCE("
        "  CAST(JSON_UNQUOTE(JSON_EXTRACT(novr.properties, '$.negate_service')) AS UNSIGNED),"
        "  n.negate_service) AS negate_service, "
        "CASE WHEN JSON_EXTRACT(novr.properties, '$.negate_source') IS NOT NULL "
        "      OR JSON_EXTRACT(novr.properties, '$.negate_destination') IS NOT NULL "
        "      OR JSON_EXTRACT(novr.properties, '$.negate_service') IS NOT NULL "
        "     THEN novr.source ELSE NULL END AS negate_override_source "
        "FROM fw_nat_rules n "
        "LEFT JOIN fw_nat_rule_overrides novr ON novr.nat_hash = n.nat_hash"
    )
    params: dict = {}
    if device_id is not None:
        sql += " WHERE n.device_id = :did"
        params["did"] = device_id
    sql += " ORDER BY n.device_id, n.position, n.id"

    try:
        rows = conn.execute(text(sql), params).mappings().all()
    except Exception:
        return []

    out: list[dict] = []
    for r in rows:
        d = dict(r)
        for col in ("src_zones", "dst_zones", "orig_src", "orig_dst", "orig_service"):
            v = d.get(col)
            if isinstance(v, str):
                try:
                    d[col] = json.loads(v) if v else []
                except Exception:
                    d[col] = []
            elif v is None:
                d[col] = []
        p = d.get("properties")
        if isinstance(p, str):
            try:
                d["properties"] = json.loads(p) if p else {}
            except Exception:
                d["properties"] = {}
        elif p is None:
            d["properties"] = {}
        out.append(d)
    return out


def _load_pbf_rules(conn, device_id: int | None = None,
                    include_deleted: bool = False) -> list[dict]:
    """Return agnostic PBF-rule dicts from fw_pbf_rules for a device
    (Phase 3). JSON columns (ingress, sources, destinations, services,
    raw_extras) decoded; order by position. The enrichment overlay
    (fw_pbf_rule_overrides.enrichment, keyed on pbf_hash) is merged into
    raw_extras - manual edits win over imported vendor-specials.
    Template = _load_nat_rules; own read-path, NOT the consolidation
    pipeline."""
    sql = (
        "SELECT p.id, p.device_id, p.position, p.name, p.disabled, "
        "p.ingress, p.sources, p.destinations, p.services, "
        "p.action, p.egress_interface, p.next_hop, "
        "p.description, p.raw_extras, "
        "LOWER(HEX(p.pbf_hash)) AS pbf_hash, "
        "pov.enrichment AS override_enrichment, "
        "pov.edits AS override_edits, "
        "pov.source AS enrichment_override_source "
        "FROM fw_pbf_rules p "
        "LEFT JOIN fw_pbf_rule_overrides pov ON pov.pbf_hash = p.pbf_hash"
    )
    params: dict = {}
    if device_id is not None:
        sql += " WHERE p.device_id = :did"
        params["did"] = device_id
    sql += " ORDER BY p.device_id, p.position, p.id"

    try:
        rows = conn.execute(text(sql), params).mappings().all()
    except Exception:
        return []

    def _jload(v, default):
        if isinstance(v, str):
            try:
                return json.loads(v) if v else default
            except Exception:
                return default
        return v if v is not None else default

    out: list[dict] = []
    for r in rows:
        d = dict(r)
        for col in ("ingress", "sources", "destinations", "services"):
            d[col] = _jload(d.get(col), [])
        raw = _jload(d.get("raw_extras"), {}) or {}
        # Override enrichment wins over imported vendor-specials.
        ovr = _jload(d.pop("override_enrichment", None), {}) or {}
        if ovr:
            raw = {**raw, **ovr}
        d["raw_extras"] = raw
        # Per-rule field edits (override overlay, keyed on the imported hash so
        # it survives re-import + keeps the hash stable for the L7 override). A
        # 'deleted' edit drops the rule from the agnostic view + the push.
        edits = _jload(d.pop("override_edits", None), {}) or {}
        # Soft-delete: marked (not hard-filtered) so the view can grey it out +
        # offer Restore; the push path keeps include_deleted=False and excludes
        # it. Default False so any forgotten caller stays push-safe.
        d["deleted"] = bool(edits.get("deleted"))
        if d["deleted"] and not include_deleted:
            continue
        edited: list[str] = []
        for f in ("ingress", "egress_interface", "next_hop", "action", "disabled"):
            if f in edits and edits[f] is not None:
                d[f] = edits[f]
                edited.append(f)
        d["_edited_fields"] = edited
        out.append(d)
    return out


def _load_ssl_rules(conn, device_id: int | None = None,
                    include_deleted: bool = False) -> list[dict]:
    """Return agnostic SSL-decryption rule dicts from fw_ssl_rules for a device
    (Phase 5). JSON columns decoded; order by position. The override overlay
    (fw_ssl_rule_overrides, keyed on ssl_hash) merges: `enrichment` into
    profile_props (manual edits win) and `edits` as a per-rule field overlay
    (action/disabled/cert_ref/ssl_type, + soft-delete). Own read-path, NOT the
    consolidation pipeline. Template = _load_pbf_rules."""
    sql = (
        "SELECT s.id, s.device_id, s.position, s.name, s.disabled, "
        "s.src_zones, s.dst_zones, s.sources, s.destinations, s.services, "
        "s.url_categories, s.source_identities, "
        "s.action, s.ssl_type, s.cert_ref, s.profile_props, "
        "s.description, s.raw_extras, "
        "LOWER(HEX(s.ssl_hash)) AS ssl_hash, "
        "sov.enrichment AS override_enrichment, "
        "sov.edits AS override_edits, "
        "sov.source AS override_source "
        "FROM fw_ssl_rules s "
        "LEFT JOIN fw_ssl_rule_overrides sov ON sov.ssl_hash = s.ssl_hash"
    )
    params: dict = {}
    if device_id is not None:
        sql += " WHERE s.device_id = :did"
        params["did"] = device_id
    sql += " ORDER BY s.device_id, s.position, s.id"

    try:
        rows = conn.execute(text(sql), params).mappings().all()
    except Exception:
        return []

    def _jload(v, default):
        if isinstance(v, str):
            try:
                return json.loads(v) if v else default
            except Exception:
                return default
        return v if v is not None else default

    out: list[dict] = []
    for r in rows:
        d = dict(r)
        for col in ("src_zones", "dst_zones", "sources", "destinations",
                    "services", "url_categories", "source_identities"):
            d[col] = _jload(d.get(col), [])
        props = _jload(d.get("profile_props"), {}) or {}
        # Override enrichment wins over imported profile_props.
        ovr = _jload(d.pop("override_enrichment", None), {}) or {}
        if ovr:
            props = {**props, **ovr}
        d["profile_props"] = props
        d["raw_extras"] = _jload(d.get("raw_extras"), {}) or {}
        # Per-rule field edits (keyed on the import-time hash so they survive
        # re-import + keep the hash stable). 'deleted' soft-drops the rule.
        edits = _jload(d.pop("override_edits", None), {}) or {}
        d["deleted"] = bool(edits.get("deleted"))
        if d["deleted"] and not include_deleted:
            continue
        edited: list[str] = []
        for f in ("action", "disabled", "cert_ref", "ssl_type"):
            if f in edits and edits[f] is not None:
                d[f] = edits[f]
                edited.append(f)
        d["_edited_fields"] = edited
        out.append(d)
    return out


def _load_vpn_tunnels(conn, device_id: int | None = None,
                      include_deleted: bool = False) -> list[dict]:
    """Return agnostic IPSec S2S VPN-tunnel dicts from fw_vpn_tunnels for a
    device (IPSec VPN, CE plan P1). One row = one route-based tunnel (the PA
    ike-gateway + ipsec-tunnel collapsed; the Forti phase1+phase2 pair). Own
    read-path, NOT the consolidation pipeline. Template = _load_ssl_rules. The
    override overlay (fw_vpn_tunnel_overrides, keyed on vpn_hash) merges `edits`
    as a per-tunnel field overlay (+ soft-delete). The PSK is NEVER stored - only
    auth_type + (for cert auth) the cert NAME."""
    sql = (
        "SELECT v.id, v.device_id, v.position, v.name, v.disabled, "
        "v.gateway_name, v.peer_address, v.peer_type, "
        "v.local_interface, v.local_address, v.auth_type, v.cert_ref, "
        "v.local_id, v.peer_id, v.ike_version, "
        "v.ike_crypto_profile, v.ipsec_crypto_profile, v.tunnel_interface, "
        "v.traffic_selectors, v.raw_extras, LOWER(HEX(v.vpn_hash)) AS vpn_hash, "
        "vov.enrichment AS override_enrichment, "
        "vov.edits AS override_edits, vov.source AS override_source "
        "FROM fw_vpn_tunnels v "
        "LEFT JOIN fw_vpn_tunnel_overrides vov ON vov.vpn_hash = v.vpn_hash"
    )
    params: dict = {}
    if device_id is not None:
        sql += " WHERE v.device_id = :did"
        params["did"] = device_id
    sql += " ORDER BY v.device_id, v.position, v.id"

    try:
        rows = conn.execute(text(sql), params).mappings().all()
    except Exception:
        return []

    def _jload(v, default):
        if isinstance(v, str):
            try:
                return json.loads(v) if v else default
            except Exception:
                return default
        return v if v is not None else default

    out: list[dict] = []
    for r in rows:
        d = dict(r)
        d["disabled"] = bool(d.get("disabled"))
        d["raw_extras"] = _jload(d.get("raw_extras"), {}) or {}
        d["traffic_selectors"] = _jload(d.get("traffic_selectors"), []) or []
        d.pop("override_enrichment", None)
        edits = _jload(d.pop("override_edits", None), {}) or {}
        d["deleted"] = bool(edits.get("deleted"))
        if d["deleted"] and not include_deleted:
            continue
        edited: list[str] = []
        for f in ("disabled", "peer_address", "local_interface", "tunnel_interface",
                  "ike_crypto_profile", "ipsec_crypto_profile", "cert_ref", "ike_version"):
            if f in edits and edits[f] is not None:
                d[f] = edits[f]
                edited.append(f)
        d["_edited_fields"] = edited
        out.append(d)
    # Surface write-only "PSK set?" / "cert set?" flags per tunnel (never the
    # secret value). Encrypted PSK → fw_vpn_tunnel_secrets; identity cert (+
    # encrypted key) → fw_vpn_tunnel_certs; both keyed (device_id, vpn_hash).
    if out:
        try:
            have = {
                r[0].lower() for r in conn.execute(text(
                    "SELECT LOWER(HEX(vpn_hash)) FROM fw_vpn_tunnel_secrets "
                    "WHERE device_id = :d"
                ), {"d": device_id}).fetchall()
            }
        except Exception:
            have = set()
        cert_names: dict[str, str] = {}
        try:
            for r in conn.execute(text(
                "SELECT LOWER(HEX(vpn_hash)), cert_name FROM fw_vpn_tunnel_certs "
                "WHERE device_id = :d"
            ), {"d": device_id}).fetchall():
                cert_names[r[0].lower()] = r[1]
        except Exception:
            cert_names = {}
        for d in out:
            vh = (d.get("vpn_hash") or "").lower()
            d["psk_set"] = vh in have
            d["cert_set"] = vh in cert_names
            # cert_name is the on-target reference (non-secret); the render uses
            # it for cert-auth gateways. Falls back to the imported cert_ref.
            if vh in cert_names:
                d["cert_name"] = cert_names[vh]
    return out


def _filter_pushable_interfaces(
    interfaces: list[dict],
) -> tuple[list[dict], list[str]]:
    """Drop interfaces that have neither IP nor zone, unless they are a
    bond member or the parent of an interface that survives the filter.

    Network-push wipes + replaces the target's interface tree, so empty
    interfaces would otherwise propagate as inert config. Bond/parent
    protection keeps topology intact when a leaf has IP/zone but the
    trunk does not (e.g. ASA `Ethernet1/13` parent without IPs feeding
    `Ethernet1/13.2030` sub-interfaces that do have IPs).

    Returns (kept_interfaces, skipped_names).
    """
    # User-skipped interfaces (deploy_skip) are excluded up front - the skip is
    # only offered for unreferenced interfaces (delete-guard rule), so a skipped
    # one is never a needed bond-member / VLAN-parent of a kept interface.
    skipped_by_user = [i["interface_name"] for i in interfaces if i.get("deploy_skip")]
    interfaces = [i for i in interfaces if not i.get("deploy_skip")]

    by_name = {iface["interface_name"]: iface for iface in interfaces}

    bond_members: set[str] = set()
    for iface in interfaces:
        for m in (iface.get("member_iface_names") or []):
            bond_members.add(m)

    def _has_own_state(iface: dict) -> bool:
        # DHCP-clients carry intent (`dhcp_enabled=true`) even when ip_addresses
        # and zone_name are empty - the runtime IP isn't known until the
        # server assigns one, but the renderer still has work to do.
        # Admin-disabled (`enabled=False`) is intentional non-up state - the
        # user wants the iface shut on push, so the row must survive the
        # filter even without IP/zone (otherwise no down-marker emits).
        return (bool(iface.get("ip_addresses"))
                or bool(iface.get("zone_name"))
                or bool(iface.get("dhcp_enabled"))
                or not bool(iface.get("enabled", True)))

    keep: set[str] = set()
    for iface in interfaces:
        name = iface["interface_name"]
        # Bond parents with at least one member survive even when they
        # carry no own IP / zone / DHCP - the aggregate-group entry is
        # the bond's reason to exist. Without this, an aggregate created
        # via the UI with no layer3 (typical: layer-2 trunk for VLAN subs
        # added later, or an empty aggregate the user is staging) gets
        # dropped at push time even though it's a valid topology row.
        is_aggregate_with_members = (
            (iface.get("iface_type") or "").lower() == "bond"
            and bool(iface.get("member_iface_names"))
        )
        # A TUNNEL interface typically carries no IP/zone of its own - its
        # reason to exist is the VPN tunnel bound to it, and PAN-OS requires
        # the tunnel unit to exist before an ipsec-tunnel may reference it
        # (QA finding, Forti→PA: the FortiOS tunnel iface was pruned here and
        # the ipsec-tunnel then failed with "tunnel-interface is not a valid
        # reference").
        is_tunnel = (iface.get("iface_type") or "").lower() == "tunnel"
        if (_has_own_state(iface)
                or name in bond_members
                or is_aggregate_with_members
                or is_tunnel):
            keep.add(name)

    # Transitive: parents of kept interfaces must stay too - subs would
    # otherwise dangle. Loop until no new parent is added.
    changed = True
    while changed:
        changed = False
        for name in list(keep):
            parent = (by_name.get(name) or {}).get("parent_iface_name")
            if parent and parent in by_name and parent not in keep:
                keep.add(parent)
                changed = True

    kept = [iface for iface in interfaces if iface["interface_name"] in keep]
    skipped = [iface["interface_name"] for iface in interfaces
               if iface["interface_name"] not in keep]
    return kept, skipped_by_user + skipped


def _validate_deploy_source(
    conn,
    source_id: int,
    strand: str | None = None,
    *,
    target_platform: str | None = None,
) -> list[dict]:
    """Return blocking issues for the source's deploy view.

    Source-of-truth means a missing IP or zone on the source ends up as a
    broken interface entry on the target - so we refuse the push instead of
    silently sending invalid XML. Each issue: {kind, interface, detail}.

    ``strand``:
      - ``"network"`` - interface IP/zone gaps block the Network push (those
        ARE the data being pushed).
      - ``"policy"`` - interface gaps don't block; rules reference zones by
        name, and if Network hasn't been pushed yet that's a soft hint
        ("push Network first"), not a hard refusal.
      - ``None`` (legacy) - full check, kept for callers like the
        deploy_generate preview that surface all issues at once.
    """
    if strand == "policy":
        return []
    # Targets whose driver consumes fw_interfaces.zone_name on push:
    # PA binds zones to interfaces; FTD likewise. Fortinet evaluates
    # srcintf/dstintf on the rule itself (the interface stands in for
    # the zone), so the iface-tier zone field is unused. Check Point
    # has no zone concept at all. The latter two should not block a
    # network push on an unzoned interface.
    _IFACE_TIER_ZONE_PLATFORMS = {"panw", "firepower"}
    _target_uses_iface_zone = (
        (target_platform or "").lower() in _IFACE_TIER_ZONE_PLATFORMS
    )
    _target_is_forti = (target_platform or "").lower() == "fortigate"
    issues: list[dict] = []
    # Composite (SW-C): validate the EFFECTIVE interface set - merge across the source's stack layers
    # (deep-fill zone/ip) exactly as the deploy render does. Without this, an interface whose IP lives
    # in a member template while its zone binds in the stack (e.g. ae2.x) reads as "zoned but no IP"
    # on the stack-own layer and falsely blocks the push, even though the rendered config has the IP.
    _lids = [l[0] for l in _stack_layers(conn, source_id)] or [source_id]
    try:
        # deploy_skip'd interfaces are excluded: the renderer emits nothing
        # for them, so flagging them here is noise at best and a FALSE
        # BLOCKER at worst - the operator can't satisfy a complaint about a
        # row that is deliberately not part of the push (QA finding, same
        # class as the multi-VR guard ignoring deploy_skip).
        rows = _merge_source_rows(conn,
            "SELECT interface_name, zone_name, ip_addresses, dhcp_enabled, enabled "
            "FROM fw_interfaces WHERE device_id = :id AND COALESCE(deploy_skip, 0) = 0 "
            "ORDER BY interface_name",
            _lids, lambda t: t[0], deep_idx=[1, 2])   # deep-fill zone_name + ip_addresses from lower layers
    except Exception:
        rows = []
    if not rows:
        issues.append({
            "kind": "no_interfaces", "interface": None,
            "detail": "Source has no interfaces - add at least one before deploy",
        })
        return issues
    # Pre-pass: collect iface_type and bond-membership so the IP/zone check
    # can spare structural rows that don't carry layer3 themselves.
    #   - Bond parents are layer-2 bundles (layer3 lives on subs).
    #   - Bond members are layer-2 slaves (IP/zone live on the bundle).
    #   - Loopbacks (CP `lo`, system loopbacks generally) usually aren't
    #     zone-bound; require IP only.
    type_lookup: dict[str, str] = {}
    member_set: set[str] = set()
    try:
        for iname_, itype_, members_raw in _merge_source_rows(conn,
                "SELECT interface_name, iface_type, member_iface_names "
                "FROM fw_interfaces WHERE device_id = :id", _lids, lambda t: t[0]):
            type_lookup[iname_] = (itype_ or "").lower()
            members: list = []
            if isinstance(members_raw, str) and members_raw:
                try:
                    members = json.loads(members_raw) or []
                except Exception:
                    members = []
            elif members_raw:
                members = list(members_raw)
            for m in members:
                if m:
                    member_set.add(str(m))
    except Exception:
        pass
    for iname, zname, ips_json, dhcp_flag, enabled_flag in rows:
        ips: list = []
        if isinstance(ips_json, str) and ips_json:
            try:
                ips = json.loads(ips_json) or []
            except Exception:
                ips = []
        elif ips_json:
            ips = list(ips_json)
        # A port with NEITHER an IP NOR a zone is an unused/unconfigured L1
        # interface - the renderer emits nothing meaningful for it, so it must
        # not block the whole network push (previously forced a manual DELETE).
        # DHCP-client interfaces are exempt: they intentionally have no IP
        # in the source-spec; the IP is runtime-assigned by the DHCP server,
        # and the vendor renderer emits the dhcp-client block instead.
        # Admin-disabled interfaces are exempt too: the user is intentionally
        # pushing a down-state row, the renderer's job is just to set the
        # vendor-down marker - IP/zone are irrelevant on a shut port.
        if not ips and not (zname or "").strip() and not dhcp_flag and enabled_flag:
            continue
        itype = type_lookup.get(iname) or ""
        is_bond_parent = itype == "bond"
        is_bond_member = iname in member_set
        is_loopback = itype == "loopback"
        is_tunnel = itype == "tunnel"
        is_dhcp = bool(dhcp_flag)
        is_disabled = not bool(enabled_flag)
        # FortiGate refuses a loopback as a zone member (it's excluded from the
        # system/zone interface datasource → push -3 "entry not found"). A source
        # config that put a loopback in a zone (PA allows it) can't be deployed
        # to Forti as-is - block with an actionable message instead of letting
        # the zone push fail mid-flight after the delete phase already ran.
        if _target_is_forti and is_loopback and (zname or "").strip():
            issues.append({
                "kind": "forti_loopback_in_zone", "interface": iname,
                "detail": (f"FortiGate can't put loopback '{iname}' in a zone "
                           f"('{zname}') - loopbacks are not valid zone members "
                           f"on FortiOS. Remove it from the zone before pushing."),
            })
        # Layer-2 rows (bundle parent or bundle slave) carry no IP/zone by
        # design. Loopbacks may carry IP but are typically zone-less on CP.
        # DHCP-clients waive the IP requirement - the address is dynamic.
        # Admin-disabled ifaces waive both - the push only flips the down bit.
        # Tunnel interfaces waive both: an IPSec tunnel iface is validly
        # unnumbered, and tunnels are out-of-scope as push-managed interfaces
        # anyway (VPN-managed - rendered as communities / phase1+2, see below),
        # so their IP/zone are irrelevant to the interface push.
        waive_ip = (is_bond_parent or is_bond_member or is_dhcp or is_disabled
                    or is_tunnel)
        waive_zone = (is_bond_parent or is_bond_member or is_loopback
                      or is_disabled or is_tunnel)
        if not ips and not waive_ip:
            issues.append({
                "kind": "no_ip", "interface": iname,
                "detail": f"Interface {iname} has no IP address",
            })
        if (not (zname or "").strip() and not waive_zone
                and _target_uses_iface_zone):
            issues.append({
                "kind": "no_zone", "interface": iname,
                "detail": f"Interface {iname} has no zone assigned",
            })

    # Network-Push scope checks. Only network-strand cares; policy already
    # returned early. Tunnels are out-of-scope on every supported target
    # (VPN-managed, not push-managed). The remaining checks are CP-specific:
    # CP's Gaia API is typed (add-vlan-interface needs parent + tag, no
    # auto-synthesis) and bonds are V1.5 (cascade complexity). PA's XML
    # emitter auto-synthesizes parent entries from VLAN names and supports
    # AE bundles natively as of Slice 2 - so those checks would be false
    # positives for PA targets.
    try:
        type_rows = conn.execute(text(
            "SELECT interface_name, iface_type, parent_iface_name, vlan_tag "
            "FROM fw_interfaces WHERE device_id = :id"
        ), {"id": source_id}).fetchall()
        all_names = {r[0] for r in type_rows}
        tplat = (target_platform or "").lower()
        # PA (Slice 2: aggregate-ethernet via Mgmt-API), CP (Slice 3: bond via
        # Gaia REST) and Forti (aggregate iface type) all push bonds.
        bond_supported = tplat in ("panw", "checkpoint", "fortigate")
        cp_strict = tplat == "checkpoint"
        for iname, itype, parent, vtag in type_rows:
            t = (itype or "").lower()
            if t == "bond" and not bond_supported:
                issues.append({
                    "kind": "bond_unsupported", "interface": iname,
                    "detail": f"Interface {iname} is a bond - push is V1.5; "
                              "remove bonds from source or wait for V1.5",
                })
            elif t == "tunnel" and tplat == "firepower":
                # IPSec VPN tunnel-ifaces are first-class for PA/Forti targets (CE
                # plan P2: PA renders the tunnel iface + VR + zone; Forti's is
                # implicit via the phase1-interface), and CP migrates VPN via
                # communities / encryption-domains - there's no route-based VTI to
                # push, so the CP renderer just skips the tunnel iface (drop+warn,
                # checkpoint.py) while the VPN strand handles the community. Only
                # FTD still defers VPN entirely → keep the tunnel-iface block there.
                issues.append({
                    "kind": "tunnel_unsupported", "interface": iname,
                    "detail": f"Interface {iname} is a tunnel IF - VPN is not yet "
                              f"supported for {tplat} targets",
                })
            elif t == "vlan" and tplat in ("checkpoint", "fortigate"):
                # CP's typed Gaia API and FortiOS both need parent + tag to
                # build a VLAN sub-interface (PA encodes the tag in the name, so
                # PA targets are exempt). The orphan-parent check stays CP-only -
                # Forti's parent is resolved through the iface-override to a
                # target interface, so it need not be in the source list.
                if not (parent or "").strip():
                    issues.append({
                        "kind": "vlan_no_parent", "interface": iname,
                        "detail": f"VLAN {iname} has no parent interface",
                    })
                elif cp_strict and parent not in all_names:
                    issues.append({
                        "kind": "vlan_orphan_parent", "interface": iname,
                        "detail": f"VLAN {iname} parent {parent!r} not "
                                  "in this source's interface list",
                    })
                if vtag in (None, ""):
                    issues.append({
                        "kind": "vlan_no_tag", "interface": iname,
                        "detail": f"VLAN {iname} has no vlan_tag",
                    })
    except Exception:
        pass

    # Slice-5f VR-orphan check: refuse push if any iface or route references a
    # vr_name with no fw_vrfs row for this device. _gen_virtual_router would
    # otherwise emit a partial topology (interface in no <virtual-router>) or
    # silently drop the route. Cascade in _save_discovered_* keeps Discover
    # paths clean - this catches direct UI/SQL paths or legacy data.
    try:
        vrf_names = {
            r[0] for r in conn.execute(text(
                "SELECT name FROM fw_vrfs WHERE device_id = :id"
            ), {"id": source_id}).fetchall()
        }
        iface_vrs = conn.execute(text(
            "SELECT DISTINCT vr_name FROM fw_interfaces "
            "WHERE device_id = :id AND vr_name IS NOT NULL AND vr_name <> ''"
        ), {"id": source_id}).fetchall()
        for (vr,) in iface_vrs:
            if vr not in vrf_names:
                issues.append({
                    "kind": "vr_orphan", "interface": None,
                    "detail": f"Interfaces reference VR {vr!r} but no fw_vrfs row exists",
                })
        route_vrs = conn.execute(text(
            "SELECT DISTINCT vr_name FROM fw_routes "
            "WHERE device_id = :id AND vr_name IS NOT NULL AND vr_name <> ''"
        ), {"id": source_id}).fetchall()
        for (vr,) in route_vrs:
            if vr not in vrf_names:
                issues.append({
                    "kind": "vr_orphan", "interface": None,
                    "detail": f"Routes reference VR {vr!r} but no fw_vrfs row exists",
                })
    except Exception:
        pass

    # CP single-table refusal: CP-Network-Push V1 ignores vr_name and emits
    # everything into the gateway's default routing table. A source with
    # multiple VRs would silently collapse on push - distinct default-routes
    # in different VRs collide, prefixes overlap. Refuse upfront so the user
    # sees the migration gap instead of discovering it on the box. Gaia VRF
    # support (R81.20+) and VSX-VS multi-instance migration are V2 work; the
    # check lifts once one of those lands.
    if (target_platform or "").lower() == "checkpoint":
        try:
            # deploy_skip'd interfaces are EXCLUDED - that is what makes the
            # documented workaround ("migrate one VR at a time") executable:
            # the operator skips the other VR's interfaces and the source
            # becomes effectively single-VR for this push. Without this the
            # guard could never be satisfied (QA finding). Routes count only
            # for VRs that still have a non-skipped interface - a route in a
            # VR nobody pushes can't collapse anything.
            distinct_vrs: set[str] = set()
            for (vr,) in conn.execute(text(
                "SELECT DISTINCT vr_name FROM fw_interfaces "
                "WHERE device_id = :id AND vr_name IS NOT NULL AND vr_name <> '' "
                "AND COALESCE(deploy_skip, 0) = 0"
            ), {"id": source_id}).fetchall():
                distinct_vrs.add(vr)
            for (vr,) in conn.execute(text(
                "SELECT DISTINCT r.vr_name FROM fw_routes r "
                "WHERE r.device_id = :id AND r.vr_name IS NOT NULL AND r.vr_name <> '' "
                "AND EXISTS (SELECT 1 FROM fw_interfaces i "
                "            WHERE i.device_id = r.device_id "
                "              AND i.vr_name = r.vr_name "
                "              AND COALESCE(i.deploy_skip, 0) = 0)"
            ), {"id": source_id}).fetchall():
                distinct_vrs.add(vr)
            if len(distinct_vrs) > 1:
                vr_list = ", ".join(sorted(distinct_vrs))
                issues.append({
                    "kind": "cp_multi_vr", "interface": None,
                    "detail": f"Source uses multiple VRs ({vr_list}) - CP-Network-"
                              "Push V1 is single-table only and would silently "
                              "collapse them. Migrate one VR at a time or wait for "
                              "Gaia-VRF / VSX support.",
                })
        except Exception:
            pass
    return issues


def _ip_to_int(ip_str: str) -> int:
    """Convert an IP or CIDR string to an integer (network address) for sorting."""
    if not ip_str or ip_str == "internet_public":
        return _INT_MAX
    try:
        if "/" in ip_str:
            return int(ipaddress.ip_network(ip_str, strict=False).network_address)
        return int(ipaddress.ip_address(ip_str))
    except Exception:
        return _INT_MAX


def _filter_rule_for_zone(rule: dict, src_zone=None, dst_zone=None) -> dict:
    """
    Return a shallow copy of rule with sources/destinations filtered to the given
    zone(s), for display within a zone-based group.  zone=None means "no zone
    assigned" - keeps only IPs that have no zone entry.

    For api_import rules zones are policy-level (not per-IP), so we just set
    the zone context for coloring without filtering individual objects.
    """
    r = dict(rule)

    if rule.get("source_type") in ("api_import", "both"):
        # Zones are rule-level: apply the group's zone to all objects for coloring
        if src_zone is not None:
            r["src_zones"]    = [src_zone]
            r["src_ip_zones"] = {s: src_zone for s in rule["sources"]}
        if dst_zone is not None:
            r["dst_zones"]    = [dst_zone]
            r["dst_ip_zones"] = {d: dst_zone for d in rule["destinations"]}
        return r

    src_ip_zones = rule.get("src_ip_zones") or {}
    dst_ip_zones = rule.get("dst_ip_zones") or {}

    # Filter sources when src_zone is specified OR when there is zone info to filter on
    if src_zone is not None or src_ip_zones:
        kept = [ip for ip in rule["sources"]
                if src_ip_zones.get(ip) == src_zone]
        if kept:
            r["sources"]      = kept
            r["src_ip_zones"] = {ip: z for ip, z in src_ip_zones.items() if ip in kept}
            r["src_zones"]    = [src_zone] if src_zone else ["any"]

    # Filter destinations when dst_zone is specified OR when there is zone info to filter on
    if dst_zone is not None or dst_ip_zones:
        kept_idx = [i for i, ip in enumerate(rule["destinations"])
                    if dst_ip_zones.get(ip) == dst_zone]
        if kept_idx:
            r["destinations"] = [rule["destinations"][i] for i in kept_idx]
            r["dst_nats"]     = [rule["dst_nats"][i] for i in kept_idx] if rule["dst_nats"] else []
            kept_ips          = set(r["destinations"])
            r["dst_ip_zones"] = {ip: z for ip, z in dst_ip_zones.items() if ip in kept_ips}
            r["dst_zones"]    = [dst_zone] if dst_zone else ["any"]

    return r


def _rule_sort_key(rule: dict):
    """Sort key: use sequence (api_import policy order) when available, else cluster by dst/proto/port."""
    seq     = rule.get("sequence")
    dsts    = rule.get("destinations") or []
    min_dst = min((_ip_to_int(d) for d in dsts), default=_INT_MAX)
    proto   = rule.get("proto") or ""
    port    = rule.get("port_from") or 0
    action  = 0 if (rule.get("action") or "").lower() in ("deny", "drop", "reject") else 1
    return (seq if seq is not None else 99999, min_dst, proto, port, action)


