def _ensure_deploy_jobs_table():
    """Create the async deploy-push job tables. Matches
    sql/init/75_fw_deploy_jobs.sql - see there for the lifecycle docs.

    fw_deploy_jobs        - one row per push, status running/done/failed/interrupted
    fw_deploy_job_events  - per-step event log, tailed by the SSE stream
    fw_deploy_target_locks - admission mutex (SELECT ... FOR UPDATE)
    """
    try:
        with get_engine().begin() as conn:
            conn.execute(text("""
                CREATE TABLE IF NOT EXISTS fw_deploy_jobs (
                  job_id         CHAR(32)                                          NOT NULL PRIMARY KEY,
                  source_id      INT                                               NOT NULL,
                  target_id      INT                                               NOT NULL,
                  platform       VARCHAR(32)                                       NULL,
                  strand         ENUM('policy','network')                          NOT NULL DEFAULT 'policy',
                  status         ENUM('running','done','failed','interrupted')     NOT NULL DEFAULT 'running',
                  success        TINYINT(1)                                        NULL,
                  push_id        CHAR(32)                                          NULL,
                  session_handle JSON                                              NULL,
                  needs_commit   TINYINT(1)                                        NOT NULL DEFAULT 0,
                  error_text     TEXT                                              NULL,
                  skip_sections  JSON                                              NULL,
                  created_at     TIMESTAMP                                         NOT NULL DEFAULT CURRENT_TIMESTAMP,
                  updated_at     TIMESTAMP                                         NOT NULL DEFAULT CURRENT_TIMESTAMP
                                                                                     ON UPDATE CURRENT_TIMESTAMP,
                  INDEX idx_target_status (target_id, status),
                  INDEX idx_created (created_at)
                ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE utf8mb4_unicode_ci
            """))
            # Existing-deployment migration: add the skip_sections column
            # on tables created before push-scope-toggles landed. Idempotent
            # via information_schema check.
            try:
                exists = conn.execute(text(
                    "SELECT 1 FROM information_schema.columns "
                    "WHERE table_schema=DATABASE() "
                    "  AND table_name='fw_deploy_jobs' "
                    "  AND column_name='skip_sections'"
                )).fetchone()
                if not exists:
                    conn.execute(text(
                        "ALTER TABLE fw_deploy_jobs "
                        "ADD COLUMN skip_sections JSON NULL AFTER error_text"
                    ))
            except Exception as e:
                print(f"[ensure_deploy_jobs] skip_sections migrate: {e}",
                      flush=True)
            conn.execute(text("""
                CREATE TABLE IF NOT EXISTS fw_deploy_job_events (
                  id          BIGINT AUTO_INCREMENT PRIMARY KEY,
                  job_id      CHAR(32)        NOT NULL,
                  seq         INT             NOT NULL,
                  step        VARCHAR(255)    NOT NULL,
                  success     TINYINT(1)      NOT NULL DEFAULT 1,
                  detail      TEXT            NULL,
                  data_json   JSON            NULL,
                  created_at  TIMESTAMP       NOT NULL DEFAULT CURRENT_TIMESTAMP,
                  INDEX idx_job_seq (job_id, seq)
                ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE utf8mb4_unicode_ci
            """))
            conn.execute(text("""
                CREATE TABLE IF NOT EXISTS fw_deploy_target_locks (
                  target_id  INT        NOT NULL PRIMARY KEY
                ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE utf8mb4_unicode_ci
            """))
            # Zombie-reap: any job still 'running' at startup belongs to a
            # process that no longer exists (this one just booted). Mark it
            # interrupted so it stops blocking the per-target admission guard.
            # ASSUMES a single uvicorn worker - with multiple workers this would
            # clobber a job live on a sibling worker; that case would need a
            # per-job owner/heartbeat token.
            conn.execute(text(
                "UPDATE fw_deploy_jobs SET status='interrupted' "
                "WHERE status='running'"
            ))
    except Exception as e:
        print(f"[ensure_deploy_jobs_table] failed: {e}", flush=True)


