@app.get("/zones/status")
def zones_status():
    with _zone_lock:
        return dict(_zone_state)


@app.get("/zones")
def zones_page():
    """The standalone Zone-Mapping page was folded into Network → Zones
    (subnet→zone mappings now render there, scoped to the selected device).
    Keep the path alive for old bookmarks via a redirect."""
    return RedirectResponse("/devices", status_code=302)


# Targets that consume src_zone/dst_zone tags on rules. CP ignores zones at
# rule level (see project_zones.md), so the Enrichment > Zones sub-tab is
# hidden - or shows a "not used" hint - for CP / no-target. The rules-table
# zone columns themselves are CSS-toggled by the active sub-tab, not by this
# flag (see body.show-zone-col in rules.html).
_ZONE_NATIVE_PLATFORMS = frozenset({"panw", "fortigate", "firepower"})


def _is_target_zone_native(selected_target: dict | None) -> bool:
    return bool(selected_target
                and selected_target.get("platform") in _ZONE_NATIVE_PLATFORMS)


def _zone_catalog_for_render(selected_target: dict | None,
                              source_device_id: int | None = None) -> dict | None:
    """Build the zone/iface picker catalog for /rules server-side embed.

    Reads zones + interfaces from the SOURCE device - same data the
    Enrichment > Zone Mapping > Zones and Interfaces sub-sub-tabs show -
    so a freshly-added or freshly-imported source row immediately becomes
    selectable in the Rules sub-sub-tab's per-rule override dropdowns.
    The target platform still drives the shape of the catalog
    (`interfaces` only populated for Fortinet because only FortiOS rules
    can reference an interface directly).

    Returns None when there is no target, the target is not zone-native
    (CP - no zones in rule semantics), or no source device is selected.
    Read-only - pure SELECT, no DDL / no UPSERT (page-render
    side-effect rule).
    """
    if not _is_target_zone_native(selected_target):
        return None
    if not source_device_id:
        return None
    platform = selected_target.get("platform") or ""
    with get_engine().begin() as conn:
        return _zone_catalog_for_device(conn, int(source_device_id), platform)


def _property_catalogs_from_schema(selected_target: dict | None,
                                    schema: dict) -> dict[str, list[dict]]:
    """Generic helper: discover-catalogs for any ``catalog``-typed schema
    field. Returns ``{catalog_kind: [{"name": …, …}]}`` from
    ``fw_target_discover``. Empty list per kind when not yet discovered
    - UI surfaces persisted values with a warn-badge.
    """
    if not selected_target:
        return {}
    catalog_kinds = {
        f.get("catalog_kind") for f in (schema.get("fields") or [])
        if f.get("type") == "catalog" and f.get("catalog_kind")
    }
    if not catalog_kinds:
        return {}
    out: dict[str, list[dict]] = {k: [] for k in catalog_kinds}
    tid = selected_target.get("id")
    if tid is None:
        return out
    with get_engine().connect() as conn:
        for kind in catalog_kinds:
            try:
                row = conn.execute(text(
                    "SELECT payload FROM fw_target_discover "
                    "WHERE device_id = :did AND kind = :k"
                ), {"did": int(tid), "k": kind}).fetchone()
                if not row or not row[0]:
                    continue
                payload = row[0] if isinstance(row[0], (list, dict)) else json.loads(row[0])
                if isinstance(payload, list):
                    out[kind] = payload
            except Exception:
                pass
    return out


def _zone_property_catalogs(selected_target: dict | None) -> dict[str, list[dict]]:
    """Zone-schema catalogs - wrapper around _property_catalogs_from_schema."""
    if not selected_target:
        return {}
    platform = (selected_target.get("platform") or "").lower()
    return _property_catalogs_from_schema(selected_target, zone_schema_for(platform))


def _nat_property_catalogs(selected_target: dict | None) -> dict[str, list[dict]]:
    """NAT-schema catalogs - Phase F (cross-vendor object mapping)."""
    if not selected_target:
        return {}
    platform = (selected_target.get("platform") or "").lower()
    return _property_catalogs_from_schema(selected_target, nat_schema_for(platform))


def _sync_route_zone_mappings(conn) -> int:
    """Auto-derive fw_zone_mappings (subnet → zone-or-interface) from fw_routes
    + connected interface subnets.

    Wipes the catalog then re-inserts one row per (device, prefix). The mapped
    value is the interface's zone when it has one, else the interface name
    itself (COALESCE(zone_name, interface_name)) - so route→interface→zone
    resolution still produces a usable srcintf/dstintf for interface-based
    targets (e.g. a FortiGate with no zone objects). Run at the start of every
    generate so route / iface-zone-binding edits propagate without explicit
    user action.

    Returns the number of mappings inserted.
    """
    conn.execute(text("DELETE FROM fw_zone_mappings"))
    # ASA stores nameif (= zone_name) in fw_routes.interface_name, not the
    # physical interface name - so the JOIN also accepts a zone_name match.
    # PA/CP/OPNsense write the physical name in both tables, so the
    # interface_name branch keeps matching for them.
    rows = conn.execute(text("""
        SELECT r.device_id, r.prefix, r.prefix_len, r.ip_from, r.ip_to,
               -- Prefer the (editable) zone binding, then the imported zone,
               -- and only fall back to the raw interface name when the
               -- interface genuinely has no zone. Without the import_zone_name
               -- step a NULL editable zone_name leaks the interface name (e.g.
               -- 'port4') into the mapping as if it were a zone.
               COALESCE(NULLIF(i.zone_name, ''), NULLIF(i.import_zone_name, ''),
                        i.interface_name) AS zone_name,
               i.interface_name AS iface_name
          FROM fw_routes r
          JOIN fw_interfaces i
            ON i.device_id = r.device_id
           AND (i.interface_name = r.interface_name
                OR i.zone_name = r.interface_name
                OR i.import_zone_name = r.interface_name)
         WHERE r.ip_from IS NOT NULL
           AND r.ip_to IS NOT NULL
    """)).fetchall()
    inserted = 0
    for did, cidr, plen, ip_from, ip_to, zone, iface in rows:
        try:
            # fw_routes.prefix is the bare network address ('192.0.2.0');
            # store the mapping as a full CIDR string. Without the /len the
            # Python LPM (ipaddress.ip_network) parsed it as a /32 host - every
            # static-routed net was dead for Auto-derive (only connected
            # subnets resolved), and the '0.0.0.0/0' exact-match default-route
            # lookup missed too. Also keeps the (cidr, device_id) unique key
            # actually deduping against the connected-subnet pass below.
            cidr_full = cidr if "/" in str(cidr) else f"{cidr}/{plen}"
            conn.execute(text("""
                INSERT INTO fw_zone_mappings
                    (device_id, cidr, prefix_len, ip_from, ip_to, zone_name, interface_name, description)
                VALUES (:did, :cidr, :pl, :ifr, :ito, :zone, :iface, NULL)
                ON DUPLICATE KEY UPDATE zone_name = :zone, interface_name = :iface,
                    prefix_len = :pl, ip_from = :ifr, ip_to = :ito
            """), {
                "did": did, "cidr": cidr_full, "pl": plen,
                "ifr": ip_from, "ito": ip_to, "zone": zone, "iface": iface,
            })
            inserted += 1
        except Exception:
            pass

    # Connected subnets: derive from fw_interfaces.ip_addresses. ASA omits
    # connected routes from running-config (they're implicit per interface
    # IP), so a pure fw_routes pass misses them. ON DUPLICATE KEY UPDATE
    # lets connected subnets win over an identical-CIDR static entry -
    # connected routes are authoritative on real devices.
    iface_rows = conn.execute(text("""
        SELECT device_id,
               -- Same zone precedence as the routes query: editable zone,
               -- then imported zone, then the bare interface name - so a NULL
               -- editable zone_name doesn't leak the interface name as a zone.
               COALESCE(NULLIF(zone_name, ''), NULLIF(import_zone_name, ''),
                        interface_name) AS zone_name,
               interface_name AS iface_name,
               ip_addresses
          FROM fw_interfaces
         WHERE ip_addresses IS NOT NULL
           AND ip_addresses <> '[]'
           AND ip_addresses <> ''
    """)).fetchall()
    for did, zone, iface, ips_json in iface_rows:
        try:
            ips = json.loads(ips_json) if isinstance(ips_json, str) else (ips_json or [])
        except Exception:
            continue
        for ip_cidr in ips:
            try:
                net = ipaddress.ip_network(ip_cidr, strict=False)
            except (ValueError, TypeError):
                continue
            cidr = str(net)
            plen = net.prefixlen
            ip_from = net.network_address.packed
            ip_to = net.broadcast_address.packed
            try:
                conn.execute(text("""
                    INSERT INTO fw_zone_mappings
                        (device_id, cidr, prefix_len, ip_from, ip_to, zone_name, interface_name, description)
                    VALUES (:did, :cidr, :pl, :ifr, :ito, :zone, :iface, 'connected')
                    ON DUPLICATE KEY UPDATE zone_name = :zone, interface_name = :iface,
                        prefix_len = :pl, ip_from = :ifr, ip_to = :ito, description = 'connected'
                """), {
                    "did": did, "cidr": cidr, "pl": plen,
                    "ifr": ip_from, "ito": ip_to, "zone": zone, "iface": iface,
                })
                inserted += 1
            except Exception:
                pass

    # Static routes that carry only a NEXT-HOP and no egress interface -
    # the normal shape of CP Gaia statics, incl. the default route (= the
    # LPM catch-all): resolve the next-hop through the connected subnets
    # (recursive-static resolution) so they still yield zone mappings.
    # Scope guard: this pass only touches routes that (a) failed the
    # interface JOIN above and (b) carry a next_hop - PA/Forti/ASA routes
    # store an interface/nameif and resolve in pass 1 unchanged.
    conn_map: dict[int, list] = {}
    for did, zone, iface, ips_json in iface_rows:
        try:
            ips = json.loads(ips_json) if isinstance(ips_json, str) else (ips_json or [])
        except Exception:
            continue
        for ip_cidr in ips:
            try:
                net = ipaddress.ip_network(str(ip_cidr), strict=False)
            except (ValueError, TypeError):
                continue
            conn_map.setdefault(did, []).append((net, zone, iface))
    unresolved = conn.execute(text("""
        SELECT r.device_id, r.prefix, r.prefix_len, r.ip_from, r.ip_to, r.next_hop
          FROM fw_routes r
          LEFT JOIN fw_interfaces i
            ON i.device_id = r.device_id
           AND (i.interface_name = r.interface_name
                OR i.zone_name = r.interface_name
                OR i.import_zone_name = r.interface_name)
         WHERE r.ip_from IS NOT NULL AND r.ip_to IS NOT NULL
           AND i.id IS NULL
           AND r.next_hop IS NOT NULL AND r.next_hop <> ''
    """)).fetchall()
    for did, cidr, plen, ip_from, ip_to, nh in unresolved:
        try:
            nh_ip = ipaddress.ip_address(str(nh))
        except ValueError:
            continue
        for net, zone, iface in conn_map.get(did, []):
            if nh_ip not in net:
                continue
            try:
                conn.execute(text("""
                    INSERT INTO fw_zone_mappings
                        (device_id, cidr, prefix_len, ip_from, ip_to, zone_name, interface_name, description)
                    VALUES (:did, :cidr, :pl, :ifr, :ito, :zone, :iface, 'via next-hop')
                    ON DUPLICATE KEY UPDATE zone_name = zone_name
                """), {
                    "did": did, "cidr": cidr, "pl": plen,
                    "ifr": ip_from, "ito": ip_to, "zone": zone, "iface": iface,
                })
                inserted += 1
            except Exception:
                pass
            break

    return inserted


def _bad_default_route_hint(conn, device_ids: list[int]) -> str | None:
    """A default route mis-stored as ``0.0.0.0/32`` (or ``::/128``) instead of ``/0`` has a DEAD LPM
    catch-all, so a destination with no more-specific route can't resolve a zone (it stays 'any').
    Return an operator hint if any of ``device_ids`` (the net-scope layers) carries one, else None.

    Deliberately NOT auto-corrected - surfaced so the operator fixes the source route (which also
    fixes the *pushed* route, not just the derive) or confirms it's intended."""
    if not device_ids:
        return None
    try:
        rows = conn.execute(text(
            "SELECT DISTINCT prefix FROM fw_routes "
            "WHERE device_id IN :ids AND prefix IN ('0.0.0.0/32', '::/128') "
            "AND next_hop IS NOT NULL AND next_hop <> ''"
        ).bindparams(bindparam("ids", expanding=True)), {"ids": device_ids}).fetchall()
    except Exception:
        return None
    if not rows:
        return None
    pfx = ", ".join(sorted({str(r[0]) for r in rows}))
    return (f"Default route stored as {pfx} instead of /0 - its catch-all is dead, so destinations "
            f"without a more-specific route can't resolve a zone (they stay 'any'). Fix it to "
            f"0.0.0.0/0 in Network → Routes, then re-derive.")


def _clear_and_reenrich_zones(conn):
    """Clear all zones from display tables and re-apply from current fw_zone_mappings."""
    for tbl, col in _PIPELINE_ZONE_TABLES:
        # api_import zones in consolidated_1 come from fw_imported_rules and can't be
        # restored by enrichment alone - preserve them during clear.
        if tbl == "fw_rules_consolidated_1":
            conn.execute(text(f"UPDATE {tbl} SET {col} = NULL WHERE source_type != 'api_import'"))
        else:
            conn.execute(text(f"UPDATE {tbl} SET {col} = NULL"))
    _enrich_zones_in_display_tables(conn)


def _rebuild_ip_zone_cache(conn) -> int:
    """
    Collect all distinct (IP, device_host) pairs from pipeline tables, resolve
    zones via device-aware LPM against fw_zone_mappings, and store in
    fw_ip_zone_cache.  Device-specific mappings take priority over global ones.
    """
    # Load zone mappings with device context
    try:
        mrows = conn.execute(text(
            "SELECT m.cidr, m.prefix_len, m.zone_name, m.device_id,"
            " COALESCE(d.display_name, d.host_name) AS device_host"
            " FROM fw_zone_mappings m"
            " LEFT JOIN fw_devices d ON d.id = m.device_id"
            " WHERE m.zone_name IS NOT NULL AND m.zone_name != ''"
            " ORDER BY m.prefix_len DESC"
        )).fetchall()
    except Exception:
        mrows = []

    # Split into device-specific and global mappings (both sorted by prefix_len DESC)
    global_nets: list[tuple[ipaddress.IPv4Network, str]] = []
    device_nets: dict[str, list[tuple[ipaddress.IPv4Network, str]]] = {}
    for cidr, plen, zone, dev_id, dev_host in mrows:
        try:
            net = ipaddress.ip_network(cidr, strict=False)
            if dev_id and dev_host:
                device_nets.setdefault(dev_host, []).append((net, zone))
            else:
                global_nets.append((net, zone))
        except Exception:
            pass

    # Collect distinct (IP, device_host) pairs from pipeline tables
    all_pairs: set[tuple[str, str]] = set()

    # consolidated_1: direct columns
    for col in ("src_ip", "dst_ip", "dst_nat"):
        extra = " AND dst_ip != 'internet_public'" if col == "dst_ip" else ""
        try:
            for ip, dh in conn.execute(text(
                f"SELECT DISTINCT {col}, device_host FROM fw_rules_consolidated_1"
                f" WHERE {col} IS NOT NULL{extra} AND device_host IS NOT NULL"
            )).fetchall():
                if ip and dh:
                    all_pairs.add((ip, dh))
        except Exception:
            pass

    # Sub-tables: JOIN to parent for device_host
    _sub_queries: list[tuple[str, str, str]] = [
        # (sub_table, ip_col, parent_table)
        ("fw_rules_accumulated_sources", "src_ip", "fw_rules_accumulated"),
        ("fw_rules_accumulated_destinations", "dst_ip", "fw_rules_accumulated"),
        ("fw_rules_accumulated_destinations", "dst_nat", "fw_rules_accumulated"),
        ("fw_rules_filtered_sources", "src_ip", "fw_rules_filtered"),
        ("fw_rules_filtered_destinations", "dst_ip", "fw_rules_filtered"),
        ("fw_rules_filtered_destinations", "dst_nat", "fw_rules_filtered"),
        ("fw_rules_subnet_sources", "src_ip", "fw_rules_subnet"),
        ("fw_rules_subnet_destinations", "dst_ip", "fw_rules_subnet"),
        ("fw_rules_subnet_destinations", "dst_nat", "fw_rules_subnet"),
        ("fw_rules_consolidated_2_sources", "src_ip", "fw_rules_consolidated_2"),
        ("fw_rules_consolidated_3_sources", "src_ip", "fw_rules_consolidated_3"),
        ("fw_rules_consolidated_3_destinations", "dst_ip", "fw_rules_consolidated_3"),
        ("fw_rules_consolidated_3_destinations", "dst_nat", "fw_rules_consolidated_3"),
        ("fw_rules_consolidated_4_sources", "src_ip", "fw_rules_consolidated_4"),
        ("fw_rules_consolidated_4_destinations", "dst_ip", "fw_rules_consolidated_4"),
        ("fw_rules_consolidated_4_destinations", "dst_nat", "fw_rules_consolidated_4"),
        ("fw_rules_consolidated_5_sources", "src_ip", "fw_rules_consolidated_5"),
        ("fw_rules_consolidated_5_destinations", "dst_ip", "fw_rules_consolidated_5"),
        ("fw_rules_consolidated_5_destinations", "dst_nat", "fw_rules_consolidated_5"),
    ]
    for sub_tbl, ip_col, parent_tbl in _sub_queries:
        extra = f" AND t.{ip_col} != 'internet_public'" if ip_col == "dst_ip" else ""
        try:
            for ip, dh in conn.execute(text(
                f"SELECT DISTINCT t.{ip_col}, r.device_host FROM {sub_tbl} t"
                f" JOIN {parent_tbl} r ON r.id = t.rule_id"
                f" WHERE t.{ip_col} IS NOT NULL{extra} AND r.device_host IS NOT NULL"
            )).fetchall():
                if ip and dh:
                    all_pairs.add((ip, dh))
        except Exception:
            pass

    # Device-aware Python LPM: device-specific mappings first, then global
    def _lpm(ip_str: str, dev_host: str) -> str | None:
        for nets in (device_nets.get(dev_host, []), global_nets):
            try:
                if "/" in ip_str:
                    net = ipaddress.ip_network(ip_str, strict=False)
                    for mnet, zone in nets:
                        if net.subnet_of(mnet):
                            return zone
                else:
                    addr = ipaddress.ip_address(ip_str)
                    for mnet, zone in nets:
                        if addr in mnet:
                            return zone
            except Exception:
                pass
        return None

    resolved: list[tuple[str, str, str]] = []
    for ip, dh in all_pairs:
        z = _lpm(ip, dh)
        if z:
            resolved.append((ip, dh, z))

    # Bulk-write to cache
    conn.execute(text("DELETE FROM fw_ip_zone_cache"))
    for i in range(0, len(resolved), 500):
        chunk = resolved[i:i + 500]
        placeholders = ", ".join(f"(:ip{j}, :dh{j}, :z{j})" for j in range(len(chunk)))
        params: dict[str, str] = {}
        for j, (ip, dh, z) in enumerate(chunk):
            params[f"ip{j}"] = ip
            params[f"dh{j}"] = dh
            params[f"z{j}"] = z
        conn.execute(text(
            f"INSERT INTO fw_ip_zone_cache (ip, device_host, zone_name) VALUES {placeholders}"
        ), params)

    return len(resolved)


def _enrich_zones_in_display_tables(conn):
    """
    Propagate zones into all pipeline display tables.

    Priority for src_zone:
      1. iface_in → fw_interfaces (deterministic)
      2. IP → fw_ip_zone_cache (Python LPM pre-computed)

    Priority for dst_zone:
      1. IP → fw_ip_zone_cache (COALESCE dst_nat, dst_ip)
    """
    _zp(4, 5, "Building zone cache…")
    _rebuild_ip_zone_cache(conn)

    _zp(5, 5, "Updating display tables…")
    # ── 1. iface_in → zone (highest priority for src) ────────────────
    try:
        conn.execute(text("""
            UPDATE fw_rules_consolidated_1 r
            JOIN fw_devices d ON (d.display_name = r.device_host OR d.host_name = r.device_host)
            JOIN fw_interfaces iz ON iz.device_id = d.id AND iz.interface_name = r.iface_in
            SET r.src_zone = iz.zone_name
            WHERE r.src_zone IS NULL AND r.iface_in IS NOT NULL
        """))
        conn.execute(text("""
            UPDATE fw_rules_accumulated_sources s
            JOIN fw_rules_accumulated r ON r.id = s.rule_id
            JOIN fw_devices d ON (d.display_name = r.device_host OR d.host_name = r.device_host)
            JOIN fw_interfaces iz ON iz.device_id = d.id AND iz.interface_name = s.iface_in
            SET s.src_zone = iz.zone_name
            WHERE s.src_zone IS NULL AND s.iface_in IS NOT NULL
        """))
        conn.execute(text("""
            UPDATE fw_rules_filtered_sources s
            JOIN fw_rules_filtered r ON r.id = s.rule_id
            JOIN fw_devices d ON (d.display_name = r.device_host OR d.host_name = r.device_host)
            JOIN fw_interfaces iz ON iz.device_id = d.id AND iz.interface_name = s.iface_in
            SET s.src_zone = iz.zone_name
            WHERE s.src_zone IS NULL AND s.iface_in IS NOT NULL
        """))
        conn.execute(text("""
            UPDATE fw_rules_subnet_sources s
            JOIN fw_rules_subnet r ON r.id = s.rule_id
            JOIN fw_devices d ON (d.display_name = r.device_host OR d.host_name = r.device_host)
            JOIN fw_interfaces iz ON iz.device_id = d.id AND iz.interface_name = s.iface_in
            SET s.src_zone = iz.zone_name
            WHERE s.src_zone IS NULL AND s.iface_in IS NOT NULL
        """))
    except Exception:
        pass
    # ── 2. JOIN-update sources from cache (device-aware) ───────────────
    _src_tables: list[tuple[str, str]] = [
        ("fw_rules_accumulated_sources", "fw_rules_accumulated"),
        ("fw_rules_filtered_sources", "fw_rules_filtered"),
        ("fw_rules_subnet_sources", "fw_rules_subnet"),
        ("fw_rules_consolidated_2_sources", "fw_rules_consolidated_2"),
        ("fw_rules_consolidated_3_sources", "fw_rules_consolidated_3"),
        ("fw_rules_consolidated_4_sources", "fw_rules_consolidated_4"),
        ("fw_rules_consolidated_5_sources", "fw_rules_consolidated_5"),
    ]
    for sub_tbl, parent_tbl in _src_tables:
        try:
            conn.execute(text(f"""
                UPDATE {sub_tbl} t
                JOIN {parent_tbl} r ON r.id = t.rule_id
                JOIN fw_ip_zone_cache c ON c.ip = t.src_ip AND c.device_host = r.device_host
                SET t.src_zone = c.zone_name
                WHERE t.src_zone IS NULL AND t.src_ip IS NOT NULL
            """))
        except Exception:
            pass

    # ── 3. JOIN-update destinations from cache (device-aware) ────────────
    _dst_tables: list[tuple[str, str]] = [
        ("fw_rules_accumulated_destinations", "fw_rules_accumulated"),
        ("fw_rules_filtered_destinations", "fw_rules_filtered"),
        ("fw_rules_subnet_destinations", "fw_rules_subnet"),
        ("fw_rules_consolidated_3_destinations", "fw_rules_consolidated_3"),
        ("fw_rules_consolidated_4_destinations", "fw_rules_consolidated_4"),
        ("fw_rules_consolidated_5_destinations", "fw_rules_consolidated_5"),
    ]
    for sub_tbl, parent_tbl in _dst_tables:
        try:
            conn.execute(text(f"""
                UPDATE {sub_tbl} t
                JOIN {parent_tbl} r ON r.id = t.rule_id
                JOIN fw_ip_zone_cache c ON c.ip = COALESCE(t.dst_nat, t.dst_ip)
                                       AND c.device_host = r.device_host
                SET t.dst_zone = c.zone_name
                WHERE t.dst_zone IS NULL AND t.dst_ip IS NOT NULL AND t.dst_ip != 'internet_public'
            """))
        except Exception:
            pass

    # ── 4. consolidated_1: direct IP columns (device_host on same row) ───
    _pub_src = "NOT " + _PRIVATE.format(col="r.src_ip")
    _pub_dst = "NOT " + _PRIVATE.format(col="COALESCE(r.dst_nat, r.dst_ip)")
    try:
        conn.execute(text("""
            UPDATE fw_rules_consolidated_1 r
            JOIN fw_ip_zone_cache c ON c.ip = r.src_ip AND c.device_host = r.device_host
            SET r.src_zone = c.zone_name
            WHERE r.src_zone IS NULL AND r.src_ip IS NOT NULL
        """))
        conn.execute(text("""
            UPDATE fw_rules_consolidated_1 r
            JOIN fw_ip_zone_cache c ON c.ip = COALESCE(r.dst_nat, r.dst_ip)
                                   AND c.device_host = r.device_host
            SET r.dst_zone = c.zone_name
            WHERE r.dst_zone IS NULL AND r.dst_ip IS NOT NULL
        """))
        # Public IPs not resolved via cache → use default route zone, fall back to 'any'
        # Prefer device-specific 0.0.0.0/0 mapping, fall back to global
        conn.execute(text(f"""
            UPDATE fw_rules_consolidated_1 r
            LEFT JOIN fw_devices d ON (d.display_name = r.device_host OR d.host_name = r.device_host)
            LEFT JOIN fw_zone_mappings m ON m.cidr = '0.0.0.0/0'
                AND (m.device_id = d.id OR (m.device_id IS NULL
                     AND NOT EXISTS (SELECT 1 FROM fw_zone_mappings m3
                                     WHERE m3.cidr = '0.0.0.0/0' AND m3.device_id = d.id)))
            SET r.src_zone = COALESCE(m.zone_name, 'any')
            WHERE r.src_zone IS NULL AND r.src_ip IS NOT NULL AND ({_pub_src})
        """))
        conn.execute(text(f"""
            UPDATE fw_rules_consolidated_1 r
            LEFT JOIN fw_devices d ON (d.display_name = r.device_host OR d.host_name = r.device_host)
            LEFT JOIN fw_zone_mappings m ON m.cidr = '0.0.0.0/0'
                AND (m.device_id = d.id OR (m.device_id IS NULL
                     AND NOT EXISTS (SELECT 1 FROM fw_zone_mappings m3
                                     WHERE m3.cidr = '0.0.0.0/0' AND m3.device_id = d.id)))
            SET r.dst_zone = COALESCE(m.zone_name, 'any')
            WHERE r.dst_zone IS NULL AND r.dst_ip IS NOT NULL AND ({_pub_dst})
        """))
    except Exception:
        pass

    # ── 5. internet_public → default route zone (per device), fallback 'any' ─
    # Prefer device-specific 0.0.0.0/0 mapping, fall back to global
    for sub_tbl, parent_tbl in _dst_tables:
        try:
            conn.execute(text(f"""
                UPDATE {sub_tbl} t
                JOIN {parent_tbl} r ON r.id = t.rule_id
                LEFT JOIN fw_devices d ON (d.display_name = r.device_host OR d.host_name = r.device_host)
                LEFT JOIN fw_zone_mappings m ON m.cidr = '0.0.0.0/0'
                    AND (m.device_id = d.id OR (m.device_id IS NULL
                         AND NOT EXISTS (SELECT 1 FROM fw_zone_mappings m3
                                         WHERE m3.cidr = '0.0.0.0/0' AND m3.device_id = d.id)))
                SET t.dst_zone = COALESCE(m.zone_name, 'any')
                WHERE t.dst_ip = 'internet_public' AND t.dst_zone IS NULL
            """))
        except Exception:
            pass
    for sub_tbl, parent_tbl in _src_tables:
        try:
            conn.execute(text(f"""
                UPDATE {sub_tbl} t
                JOIN {parent_tbl} r ON r.id = t.rule_id
                LEFT JOIN fw_devices d ON (d.display_name = r.device_host OR d.host_name = r.device_host)
                LEFT JOIN fw_zone_mappings m ON m.cidr = '0.0.0.0/0'
                    AND (m.device_id = d.id OR (m.device_id IS NULL
                         AND NOT EXISTS (SELECT 1 FROM fw_zone_mappings m3
                                         WHERE m3.cidr = '0.0.0.0/0' AND m3.device_id = d.id)))
                SET t.src_zone = COALESCE(m.zone_name, 'any')
                WHERE t.src_ip = 'internet_public' AND t.src_zone IS NULL
            """))
        except Exception:
            pass

    _recompute_zone_status(conn)


def _recompute_zone_status(conn):
    """Count unzoned entries across all display tables and persist to pipeline config."""
    try:
        total = 0
        checks = [
            ("fw_rules_consolidated_1",            "src_zone", "src_ip"),
            ("fw_rules_consolidated_1",            "dst_zone", "dst_ip"),
            ("fw_rules_accumulated_sources",      "src_zone", "src_ip"),
            ("fw_rules_accumulated_destinations",  "dst_zone", "dst_ip"),
            ("fw_rules_subnet_sources",            "src_zone", "src_ip"),
            ("fw_rules_subnet_destinations",       "dst_zone", "dst_ip"),
            ("fw_rules_filtered_sources",          "src_zone", "src_ip"),
            ("fw_rules_filtered_destinations",     "dst_zone", "dst_ip"),
        ]
        for tbl, zone_col, ip_col in checks:
            # Exclude api_import rows in consolidated_1 - their zones come from import data
            extra = ""
            n = conn.execute(text(f"""
                SELECT COUNT(*) FROM {tbl}
                WHERE {zone_col} IS NULL
                  AND {ip_col} IS NOT NULL
                  AND {ip_col} != 'internet_public'
                  AND {ip_col} NOT LIKE 'zone:%'
                  {extra}
            """)).scalar() or 0
            total += int(n)
        conn.execute(text("""
            INSERT INTO fw_pipeline_config (job_name, enabled, params)
            VALUES ('_zone_status', 1, :p)
            ON DUPLICATE KEY UPDATE params = :p
        """), {"p": json.dumps({"unzoned_count": total})})
    except Exception:
        pass


# LPM zone lookup subquery: resolves an IP to its best-matching zone name.
# Use with .format(ip=<column>, dh=<device_host column or quoted param>).
_ZONE_LPM_SQL = (
    "(SELECT m.zone_name FROM fw_zone_mappings m"
    " LEFT JOIN fw_devices md ON md.id = m.device_id"
    " WHERE INET_ATON(SUBSTRING_INDEX({ip},'/',1))"
    "   BETWEEN INET_ATON(SUBSTRING_INDEX(m.cidr,'/',1))"
    "       AND (INET_ATON(SUBSTRING_INDEX(m.cidr,'/',1)) + POW(2, 32 - m.prefix_len) - 1)"
    "   AND m.zone_name IS NOT NULL AND m.zone_name != ''"
    "   AND (m.device_id IS NULL OR md.host_name = {dh} OR md.display_name = {dh})"
    " ORDER BY CASE WHEN m.device_id IS NOT NULL"
    "   AND (md.host_name = {dh} OR md.display_name = {dh}) THEN 0 ELSE 1 END,"
    "   m.prefix_len DESC LIMIT 1)"
)


def _ip_obj_name(ip_val: str, zone: str | None = None) -> tuple[str, str]:
    """Return (auto_name, obj_type) for an IP/CIDR string, with optional zone suffix."""
    suffix = f"-{zone}" if zone else ""
    if "/" in ip_val:
        base, prefix = ip_val.split("/", 1)
        if prefix == "32":
            return f"h-{base}{suffix}", "host"
        return f"n-{base}-{prefix}{suffix}", "network"
    return f"h-{ip_val}{suffix}", "host"


def _upsert_object_tables(conn, device_id: int, objects: list[dict]) -> None:
    """Materialize imported ADDRESS/SERVICE objects into the unified
    fw_address_objects / fw_service_objects tables (source='import') so the
    /rules Objects view (which reads those tables) shows them.

    ``objects``: the collector shape - a list of {obj_type, name, value} where
    value is the parsed object dict. Groups (address_group/service_group) are
    skipped (they stay in fw_imported_objects, read directly by the display).
    Shared by the normal device import and the Panorama scope import so a
    scope-device is first-class (its objects show like any firewall's).

    Re-import is a REPLACE for source='import' rows: objects that vanished
    from the source are deleted, not left behind. Upsert-only leaves stale
    rows that keep flowing into renders and pushes long after the object is
    gone from the box (QA finding: FortiOS 'RLOGIN'/'RSH' were deleted on the
    device but still rendered, with a port syntax a later parser fix had
    already corrected everywhere else). User-created rows (source != 'import')
    are untouched.
    """
    seen_addr = {o.get("name") for o in objects
                 if o.get("obj_type") == "address" and o.get("name")}
    seen_svc = {o.get("name") for o in objects
                if o.get("obj_type") == "service" and o.get("name")}
    for table, seen in (("fw_address_objects", seen_addr),
                        ("fw_service_objects", seen_svc)):
        try:
            if seen:
                ph = ", ".join(f":n{i}" for i in range(len(seen)))
                params = {f"n{i}": n for i, n in enumerate(seen)}
                params["did"] = device_id
                conn.execute(text(
                    f"DELETE FROM {table} WHERE device_id = :did "
                    f"AND source = 'import' AND name NOT IN ({ph})"), params)
            else:
                conn.execute(text(
                    f"DELETE FROM {table} WHERE device_id = :did "
                    "AND source = 'import'"), {"did": device_id})
        except Exception:
            pass

    for obj in objects:
        val = obj.get("value")
        if not isinstance(val, dict):
            continue
        try:
            if obj["obj_type"] == "address" and val.get("value"):
                ip_val = val["value"]
                if val.get("type") == "ip-netmask":
                    ot = "network" if "/" in ip_val and not ip_val.endswith("/32") else "host"
                elif val.get("type") == "fqdn":
                    ot = "fqdn"
                else:
                    ot = "host"
                conn.execute(text("""
                    INSERT INTO fw_address_objects
                      (device_id, name, value, obj_type, description, source)
                    VALUES (:did, :name, :val, :type, :desc, 'import')
                    ON DUPLICATE KEY UPDATE
                      name = IF(source = 'auto', :name, name),
                      description = COALESCE(NULLIF(:desc, ''), description),
                      source = 'import'
                """), {
                    "did": device_id, "name": obj["name"],
                    "val": ip_val, "type": ot,
                    "desc": val.get("description", ""),
                })
            elif obj["obj_type"] == "service" and val.get("protocol") and val.get("port"):
                conn.execute(text("""
                    INSERT INTO fw_service_objects
                      (device_id, name, proto, port, description, source)
                    VALUES (:did, :name, :proto, :port, :desc, 'import')
                    ON DUPLICATE KEY UPDATE
                      name = IF(source = 'auto', :name, name),
                      description = COALESCE(NULLIF(:desc, ''), description),
                      source = 'import'
                """), {
                    "did": device_id, "name": obj["name"],
                    "proto": val["protocol"], "port": val["port"],
                    "desc": val.get("description", ""),
                })
        except Exception:
            pass


def _auto_generate_objects(conn):
    """Create address and service objects from the active display table.

    Uses the highest enabled pipeline module (endpoint_pairs > subnet >
    filtered > accumulated) so objects match what the user actually sees.
    Only inserts new objects - existing ones (including user-renamed) are
    not touched thanks to INSERT IGNORE on the UNIQUE keys.
    """
    # Determine active display table from pipeline config
    cfg = {}
    try:
        rows = conn.execute(text(
            "SELECT job_name, enabled FROM fw_pipeline_config"
        )).fetchall()
        cfg = {r[0]: bool(r[1]) for r in rows}
    except Exception:
        pass

    acc_on = cfg.get("52_accumulate", False)

    # Pick highest enabled module - fall back to fw_rules_consolidated_1 (the
    # always-on raw view) when no advanced module is on so objects still
    # materialize after a fresh ingest.
    src_tbl = None
    dst_tbl = None
    has_dst_sub = False
    use_c1 = False
    if cfg.get("56_endpoint_pairs", False) and acc_on:
        base_tbl = "fw_rules_endpoint_pairs"
        src_tbl = "fw_rules_endpoint_pairs_sources"
        # endpoint_pairs: dst_ip on main table, ports as comma-string
    elif cfg.get("53_subnet", False) and acc_on:
        base_tbl = "fw_rules_subnet"
        src_tbl = "fw_rules_subnet_sources"
        has_dst_sub = True
    elif cfg.get("55_quality_filter", False):
        base_tbl = "fw_rules_filtered"
        src_tbl = "fw_rules_filtered_sources"
        has_dst_sub = True
    elif acc_on:
        base_tbl = "fw_rules_accumulated"
        src_tbl = "fw_rules_accumulated_sources"
        has_dst_sub = True
    else:
        base_tbl = "fw_rules_consolidated_1"
        use_c1 = True  # src_ip/dst_ip and proto/dst_port live on the main row

    if has_dst_sub:
        dst_tbl = base_tbl + "_destinations"

    # Get devices with data
    devices = conn.execute(text(f"""
        SELECT DISTINCT d.id, r.device_host
        FROM {base_tbl} r
        JOIN fw_devices d ON d.host_name = r.device_host OR d.display_name = r.device_host
    """)).fetchall()

    # Devices that only have NAT rules (no entries in the active rule-pipeline
    # table) still need their auto-objects rebuilt so the NAT-pass below has a
    # clean slate.
    nat_dev_ids: set[int] = set()
    try:
        rows = conn.execute(text(
            "SELECT DISTINCT device_id FROM fw_nat_rules"
        )).fetchall()
        nat_dev_ids = {int(r[0]) for r in rows if r[0] is not None}
    except Exception:
        pass

    all_dev_ids = {int(d) for d, _ in devices} | nat_dev_ids

    # Clear previous auto-generated objects (stale entries from prior runs)
    for did in all_dev_ids:
        conn.execute(text(
            "DELETE FROM fw_address_objects WHERE device_id = :did AND source = 'auto'"
        ), {"did": did})
        conn.execute(text(
            "DELETE FROM fw_service_objects WHERE device_id = :did AND source = 'auto'"
        ), {"did": did})

    # Pre-load source-imported object values per device so auto-generation
    # can suppress redundant rows when the source already has a named object
    # with the same value. Driver-side _build_addr_lookup then resolves rule
    # literals to the imported name automatically - no auto-shadow needed.
    # Bare IPv4 host addresses are canonicalized to "/32" form on both sides
    # so "10.1.2.3" (auto) and "10.1.2.3/32" (imported) match.
    def _canon_addr(v: str) -> str:
        if not v:
            return ""
        if "." in v and "/" not in v and "-" not in v and ":" not in v:
            return f"{v}/32"
        return v

    imported_addrs: dict[int, set[str]] = {}
    imported_svcs: dict[int, set[tuple[str, str]]] = {}
    if all_dev_ids:
        try:
            rows = conn.execute(text(f"""
                SELECT device_id, obj_type, value FROM fw_imported_objects
                WHERE device_id IN ({",".join(str(int(d)) for d in all_dev_ids)})
                  AND obj_type IN ('address', 'service')
            """)).fetchall()
            for did, otype, val_json in rows:
                try:
                    val = json.loads(val_json) if isinstance(val_json, str) else (val_json or {})
                except Exception:
                    continue
                if not isinstance(val, dict):
                    continue
                if otype == "address":
                    v = val.get("value")
                    if isinstance(v, str) and v:
                        imported_addrs.setdefault(int(did), set()).add(_canon_addr(v))
                elif otype == "service":
                    proto = (val.get("protocol") or "").lower()
                    port = val.get("port")
                    if proto and port is not None:
                        imported_svcs.setdefault(int(did), set()).add((proto, str(port)))
        except Exception:
            pass

    _SKIP = {"internet_public", "any", ""}
    # Bare IPv4 or CIDR; used by NAT pass and group-member pass to
    # distinguish raw literals from named refs (objects / nested groups).
    _IP_LIKE = re.compile(r"^\d{1,3}(\.\d{1,3}){3}(/\d{1,2})?$")
    _INS_ADDR = text("""
        INSERT IGNORE INTO fw_address_objects
          (device_id, name, value, obj_type, source)
        VALUES (:did, :name, :val, :type, 'auto')
    """)
    _INS_SVC = text("""
        INSERT IGNORE INTO fw_service_objects
          (device_id, name, proto, port, source)
        VALUES (:did, :name, :proto, :port, 'auto')
    """)

    for device_id, device_host in devices:
        # ── Address objects: sources ────────────────────────────────────
        if use_c1:
            zone_sub = _ZONE_LPM_SQL.format(ip="r.src_ip", dh="r.device_host")
            src_sql = f"""
                SELECT DISTINCT r.src_ip, {zone_sub} AS zone_name
                FROM {base_tbl} r
                WHERE r.device_host = :dh AND r.src_ip IS NOT NULL
                  AND r.src_ip NOT LIKE 'zone:%%'
            """
        else:
            zone_sub = _ZONE_LPM_SQL.format(ip="t.src_ip", dh="r.device_host")
            src_sql = f"""
                SELECT DISTINCT t.src_ip, {zone_sub} AS zone_name
                FROM {src_tbl} t
                JOIN {base_tbl} r ON r.id = t.rule_id
                WHERE r.device_host = :dh AND t.src_ip IS NOT NULL
                  AND t.src_ip NOT LIKE 'zone:%%'
            """
        try:
            src_rows = conn.execute(text(src_sql), {"dh": device_host}).fetchall()
            imp_addr_set = imported_addrs.get(device_id, set())
            for ip_val, zone_name in src_rows:
                if not ip_val or ip_val in _SKIP:
                    continue
                if _canon_addr(ip_val) in imp_addr_set:
                    continue
                name, obj_type = _ip_obj_name(ip_val, zone_name)
                try:
                    conn.execute(_INS_ADDR, {"did": device_id, "name": name, "val": ip_val, "type": obj_type})
                except Exception:
                    pass
        except Exception:
            pass

        # ── Address objects: destinations ───────────────────────────────
        if dst_tbl:
            zone_sub = _ZONE_LPM_SQL.format(ip="t.dst_ip", dh="r.device_host")
            dst_sql = f"""
                SELECT DISTINCT t.dst_ip, {zone_sub} AS zone_name
                FROM {dst_tbl} t
                JOIN {base_tbl} r ON r.id = t.rule_id
                WHERE r.device_host = :dh AND t.dst_ip IS NOT NULL
                  AND t.dst_ip NOT LIKE 'zone:%%'
            """
        else:
            # endpoint_pairs / consolidated_1: dst_ip is on the main table
            zone_sub = _ZONE_LPM_SQL.format(ip="r.dst_ip", dh="r.device_host")
            dst_sql = f"""
                SELECT DISTINCT r.dst_ip, {zone_sub} AS zone_name
                FROM {base_tbl} r
                WHERE r.device_host = :dh AND r.dst_ip IS NOT NULL
                  AND r.dst_ip NOT LIKE 'zone:%%'
            """
        try:
            dst_rows = conn.execute(text(dst_sql), {"dh": device_host}).fetchall()
            imp_addr_set = imported_addrs.get(device_id, set())
            for ip_val, zone_name in dst_rows:
                if not ip_val or ip_val in _SKIP:
                    continue
                if _canon_addr(ip_val) in imp_addr_set:
                    continue
                name, obj_type = _ip_obj_name(ip_val, zone_name)
                try:
                    conn.execute(_INS_ADDR, {"did": device_id, "name": name, "val": ip_val, "type": obj_type})
                except Exception:
                    pass
        except Exception:
            pass

        # ── Service objects ─────────────────────────────────────────────
        imp_svc_set = imported_svcs.get(device_id, set())
        if base_tbl == "fw_rules_endpoint_pairs":
            # endpoint_pairs stores ports as comma-separated "proto/port" in `ports` column
            try:
                port_rows = conn.execute(text(f"""
                    SELECT DISTINCT ports FROM {base_tbl}
                    WHERE device_host = :dh AND ports IS NOT NULL AND ports != ''
                """), {"dh": device_host}).fetchall()
                for (ports_csv,) in port_rows:
                    for entry in ports_csv.split(","):
                        entry = entry.strip()
                        if "/" in entry:
                            proto, port_str = entry.split("/", 1)
                            if (proto.lower(), port_str) in imp_svc_set:
                                continue
                            try:
                                conn.execute(_INS_SVC, {
                                    "did": device_id, "name": f"{port_str}-{proto}",
                                    "proto": proto, "port": port_str,
                                })
                            except Exception:
                                pass
            except Exception:
                pass
        else:
            # accumulated/subnet/filtered: proto + dst_port on main table
            try:
                port_rows = conn.execute(text(f"""
                    SELECT DISTINCT proto, dst_port FROM {base_tbl}
                    WHERE device_host = :dh AND proto IS NOT NULL AND dst_port IS NOT NULL
                """), {"dh": device_host}).fetchall()
                for proto, port in port_rows:
                    port_str = str(port)
                    if ((proto or "").lower(), port_str) in imp_svc_set:
                        continue
                    try:
                        conn.execute(_INS_SVC, {
                            "did": device_id, "name": f"{port_str}-{proto}",
                            "proto": proto, "port": port_str,
                        })
                    except Exception:
                        pass
            except Exception:
                pass

    # ── NAT-rule addresses + services ───────────────────────────────────
    # fw_nat_rules carries IPs in JSON arrays (orig_src, orig_dst), scalars
    # (trans_src, trans_dst), and services in orig_service. Auto-build
    # objects so the deploy driver can rewrite IPs → object names when
    # emitting NAT, matching the style the rule renderer uses.
    import json as _j_nat

    for nat_device_id in sorted(nat_dev_ids):
        try:
            nat_rows = conn.execute(text("""
                SELECT orig_src, orig_dst, orig_service, trans_src, trans_dst
                FROM fw_nat_rules WHERE device_id = :did
            """), {"did": nat_device_id}).fetchall()
        except Exception:
            continue

        for orig_src, orig_dst, orig_service, trans_src, trans_dst in nat_rows:
            addrs: list[str] = []
            for js in (orig_src, orig_dst):
                if not js:
                    continue
                try:
                    vals = _j_nat.loads(js) if isinstance(js, (str, bytes)) else js
                except Exception:
                    vals = None
                if isinstance(vals, list):
                    addrs.extend(str(v) for v in vals if v)
            # trans_src may be "iface|ip" (interface-address) or comma-list
            if trans_src:
                ts = trans_src.split("|", 1)[1] if "|" in trans_src else trans_src
                addrs.extend(s.strip() for s in ts.split(",") if s.strip())
            if trans_dst:
                addrs.append(trans_dst)

            imp_addr_set = imported_addrs.get(nat_device_id, set())
            imp_svc_set = imported_svcs.get(nat_device_id, set())
            for ip_val in addrs:
                if not ip_val or ip_val in _SKIP:
                    continue
                if not _IP_LIKE.match(ip_val):
                    continue  # zone names, group refs, "any" - skip
                if _canon_addr(ip_val) in imp_addr_set:
                    continue
                name, obj_type = _ip_obj_name(ip_val, None)
                try:
                    conn.execute(_INS_ADDR, {
                        "did": nat_device_id, "name": name,
                        "val": ip_val, "type": obj_type,
                    })
                except Exception:
                    pass

            # orig_service: JSON array of "proto/port" strings
            if orig_service:
                try:
                    svcs = _j_nat.loads(orig_service) if isinstance(orig_service, (str, bytes)) else orig_service
                except Exception:
                    svcs = None
                if isinstance(svcs, list):
                    for svc in svcs:
                        if not svc or svc == "any" or "/" not in str(svc):
                            continue
                        proto, port_str = str(svc).split("/", 1)
                        if (proto.lower(), port_str) in imp_svc_set:
                            continue
                        try:
                            conn.execute(_INS_SVC, {
                                "did": nat_device_id,
                                "name": f"{port_str}-{proto.lower()}",
                                "proto": proto.lower(),
                                "port": port_str,
                            })
                        except Exception:
                            pass

    # ── Group members: address-groups ───────────────────────────────────
    # Mirror the rule-pass: materialize auto-objects for raw IP literals
    # in group members so _build_addr_lookup can rewrite them to object
    # names at push time. Suppress against fw_imported_objects values to
    # avoid shadowing imported names. Service-groups are skipped - their
    # members are object/group names by convention, not proto/port literals.
    try:
        rows = conn.execute(text("""
            SELECT o.device_id, o.value
            FROM fw_imported_objects o
            JOIN (
                SELECT device_id, MAX(import_ts) AS mt
                FROM fw_imported_objects
                WHERE obj_type = 'address_group'
                GROUP BY device_id
            ) m ON m.device_id = o.device_id AND o.import_ts = m.mt
            WHERE o.obj_type = 'address_group' AND o.value IS NOT NULL
        """)).fetchall()
        for did, val_json in rows:
            try:
                val = _j_nat.loads(val_json) if isinstance(val_json, (str, bytes)) else (val_json or {})
            except Exception:
                continue
            if not isinstance(val, dict):
                continue
            members = val.get("members") or []
            imp_addr_set = imported_addrs.get(int(did), set())
            for m in members:
                if not m or m in _SKIP:
                    continue
                if not _IP_LIKE.match(str(m)):
                    continue  # named ref (object / nested group) - skip
                if _canon_addr(m) in imp_addr_set:
                    continue  # imported object with same value exists
                name, obj_type = _ip_obj_name(m, None)
                try:
                    conn.execute(_INS_ADDR, {
                        "did": int(did), "name": name,
                        "val": m, "type": obj_type,
                    })
                except Exception:
                    pass
    except Exception:
        pass


def _materialize_internet_public(conn) -> None:
    """Materialize the Gateshift `internet_public` literal as concrete address-objects
    + a static address-group, per source device that references it. Idempotent:
    DELETE WHERE source='synthetic' across all devices, then INSERT only for
    those that need it.

    Result lives in fw_imported_objects (consumed by deploy_generate) and
    fw_address_objects (so the ip-ranges show in the Objects sub-tab).
    """
    ranges = (
        ("internet_public_r1", "1.0.0.0-9.255.255.255"),
        ("internet_public_r2", "11.0.0.0-172.15.255.255"),
        ("internet_public_r3", "172.32.0.0-192.167.255.255"),
        ("internet_public_r4", "192.169.0.0-223.255.255.255"),
    )
    desc = "auto: internet_public (non-RFC1918)"

    # Always clean stale synthetic markers - re-running the pipeline must produce
    # the same result regardless of prior state.
    try:
        conn.execute(text(
            "DELETE FROM fw_imported_objects WHERE source = 'synthetic'"
        ))
    except Exception:
        pass
    try:
        conn.execute(text(
            "DELETE FROM fw_address_objects WHERE source = 'synthetic'"
        ))
    except Exception:
        pass

    # Find devices whose accumulated rules reference `internet_public`. The
    # literal is introduced at the accumulate pipeline step (52); downstream
    # tables (subnet/filtered/endpoint_pairs) inherit it. Scanning accumulated
    # therefore covers all displayable views.
    try:
        device_rows = conn.execute(text("""
            SELECT DISTINCT d.id
            FROM fw_devices d
            JOIN fw_rules_accumulated r
                 ON r.device_host = d.host_name OR r.device_host = d.display_name
            LEFT JOIN fw_rules_accumulated_sources s
                 ON s.rule_id = r.id AND s.src_ip = 'internet_public'
            LEFT JOIN fw_rules_accumulated_destinations dst
                 ON dst.rule_id = r.id AND dst.dst_ip = 'internet_public'
            WHERE s.src_ip IS NOT NULL OR dst.dst_ip IS NOT NULL
        """)).fetchall()
    except Exception:
        return
    device_ids = sorted({row[0] for row in device_rows})
    if not device_ids:
        return

    for did in device_ids:
        # Align synthetic with the device's latest import_ts so it groups
        # naturally in queries that sort by it. Falls back to NOW() when the
        # device has no imports yet.
        ts = conn.execute(text(
            "SELECT MAX(import_ts) FROM fw_imported_objects "
            "WHERE device_id = :did AND source = 'import'"
        ), {"did": did}).scalar()

        for name, rng in ranges:
            val = json.dumps({"type": "ip-range", "value": rng, "description": desc})
            try:
                conn.execute(text("""
                    INSERT INTO fw_imported_objects
                      (device_id, import_ts, obj_type, name, value, source)
                    VALUES (:did, COALESCE(:ts, NOW()), 'address', :name, :val, 'synthetic')
                """), {"did": did, "ts": ts, "name": name, "val": val})
            except Exception:
                pass
            try:
                conn.execute(text("""
                    INSERT INTO fw_address_objects
                      (device_id, name, value, obj_type, description, source)
                    VALUES (:did, :name, :val, 'ip-range', :desc, 'synthetic')
                """), {"did": did, "name": name, "val": rng, "desc": desc})
            except Exception:
                pass

        members = [n for n, _ in ranges]
        group_val = json.dumps({"type": "static", "members": members, "description": desc})
        try:
            conn.execute(text("""
                INSERT INTO fw_imported_objects
                  (device_id, import_ts, obj_type, name, value, source)
                VALUES (:did, COALESCE(:ts, NOW()), 'address_group', 'internet_public', :val, 'synthetic')
            """), {"did": did, "ts": ts, "val": group_val})
        except Exception:
            pass


# ─── Slice 6: cascade-rename helpers ──────────────────────────────────
# Direct-edit + cascade replaces the pre-Slice-6 target_*_name overlay.
# When the user renames a zone / interface / VR, the rename cascades in a
# single transaction through every dependent table so subsequent reads
# (deploy, UI, pipeline) see the new name verbatim. import_*_name on the
# parent row preserves the source-of-truth from the collector - used for
# re-import wipe-confirm + collector matching.
#
# Why these are scoped per-device (or per-host for consolidated tables):
# fw_devices(id) is the natural rename namespace. Consolidated rule
# tables / fw_flows key by `device_host` (display_name OR
# host_name) instead of device_id - that's how the pipeline maps logs
# back to devices. Joining via fw_devices keeps device-scoped renames
# from leaking across boundaries.

_CONSOLIDATED_ZONE_TABLES = (
    "fw_rules_consolidated",
    "fw_rules_consolidated_3",
    "fw_rules_consolidated_4",
    "fw_rules_filtered",
    "fw_rules_endpoint_pairs",
    "fw_rules_accumulated",
)


def _re_backfill_import_zone_names(conn):
    """Reset import_zone_name where it was wrongly set to zone_name but the
    original PA zone name still exists un-propagated in traffic_logs.

    Only runs when there's actual stale data: the original PA zone name must
    still be present in traffic_logs for this device. After propagation has
    run once, the original names are gone from traffic_logs and this becomes
    a no-op on future restarts.
    """
    devices = conn.execute(text(
        "SELECT DISTINCT iz.device_id FROM fw_interfaces iz "
        "JOIN fw_imported_objects io ON io.device_id = iz.device_id AND io.obj_type = 'zone' "
        "WHERE iz.import_zone_name IS NOT NULL AND iz.import_zone_name = iz.zone_name"
    )).fetchall()
    for (did,) in devices:
        host = conn.execute(text(
            "SELECT COALESCE(display_name, host_name) FROM fw_devices WHERE id = :id"
        ), {"id": did}).scalar()
        if not host:
            continue
        # Collect zone names currently in traffic logs for this device
        log_zone_rows = conn.execute(text(
            "SELECT DISTINCT src_zone FROM fw_flows "
            "WHERE device_host = :h AND source_type = 'api_import' "
            "AND src_zone IS NOT NULL AND src_zone != '' "
            "UNION "
            "SELECT DISTINCT dst_zone FROM fw_flows "
            "WHERE device_host = :h AND source_type = 'api_import' "
            "AND dst_zone IS NOT NULL AND dst_zone != ''"
        ), {"h": host}).fetchall()
        log_zones = {r[0] for r in log_zone_rows}

        # Build original interface→zone from stored zone objects
        iface_to_orig: dict[str, str] = {}
        zone_objs = conn.execute(text(
            "SELECT name, value FROM fw_imported_objects "
            "WHERE device_id = :did AND obj_type = 'zone'"
        ), {"did": did}).fetchall()
        for zone_name, val_json in zone_objs:
            try:
                val = json.loads(val_json) if isinstance(val_json, str) else val_json
                for iface in val.get("interfaces", []):
                    iface_to_orig[iface] = zone_name
            except (json.JSONDecodeError, TypeError, AttributeError):
                pass
        if not iface_to_orig:
            continue

        # Only reset if the original PA zone name still exists in traffic_logs
        # (meaning propagation hasn't happened yet for this zone)
        iz_rows = conn.execute(text(
            "SELECT id, interface_name, zone_name, import_zone_name "
            "FROM fw_interfaces WHERE device_id = :did "
            "AND import_zone_name IS NOT NULL AND import_zone_name = zone_name"
        ), {"did": did}).fetchall()
        for iz_id, iface_name, zone, imp_zone in iz_rows:
            orig = iface_to_orig.get(iface_name)
            if orig and orig != imp_zone and orig in log_zones:
                conn.execute(text(
                    "UPDATE fw_interfaces SET import_zone_name = NULL WHERE id = :id"
                ), {"id": iz_id})


def _propagate_zone_renames(conn):
    """After backfill, propagate current zone names to traffic_logs and imported_rules
    for any interface where zone_name != import_zone_name.

    Shared zone splits (same import_zone_name mapped to different zone_names by
    different interfaces) are skipped - traffic logs can't distinguish which entries
    belong to which interface. Those interfaces just get import_zone_name = zone_name
    so future individual renames work correctly.
    """
    rows = conn.execute(text(
        "SELECT iz.id, iz.device_id, iz.zone_name, iz.import_zone_name "
        "FROM fw_interfaces iz "
        "WHERE iz.import_zone_name IS NOT NULL "
        "AND iz.zone_name IS NOT NULL "
        "AND iz.import_zone_name != iz.zone_name"
    )).fetchall()

    # Detect shared-zone splits: same (device_id, import_zone_name) → different zone_names
    from collections import defaultdict
    groups: dict[tuple[int, str], set[str]] = defaultdict(set)
    for iz_id, did, zone_name, imp_zone in rows:
        groups[(did, imp_zone)].add(zone_name)
    split_keys = {k for k, v in groups.items() if len(v) > 1}

    # Propagate non-split renames
    propagated: set[tuple[int, str]] = set()
    for iz_id, did, zone_name, imp_zone in rows:
        key = (did, imp_zone)
        if key in split_keys or key in propagated:
            continue
        propagated.add(key)
        host = conn.execute(text(
            "SELECT COALESCE(display_name, host_name) FROM fw_devices WHERE id = :id"
        ), {"id": did}).scalar()
        if not host:
            continue
        conn.execute(text(
            "UPDATE fw_flows SET src_zone = :new "
            "WHERE src_zone = :old AND source_type = 'api_import' AND device_host = :h"
        ), {"new": zone_name, "old": imp_zone, "h": host})
        conn.execute(text(
            "UPDATE fw_flows SET dst_zone = :new "
            "WHERE dst_zone = :old AND source_type = 'api_import' AND device_host = :h"
        ), {"new": zone_name, "old": imp_zone, "h": host})
        conn.execute(text(
            "UPDATE fw_imported_rules SET src_zones = REPLACE(src_zones, :old_j, :new_j) "
            "WHERE device_id = :did"
        ), {"old_j": f'"{imp_zone}"', "new_j": f'"{zone_name}"', "did": did})
        conn.execute(text(
            "UPDATE fw_imported_rules SET dst_zones = REPLACE(dst_zones, :old_j, :new_j) "
            "WHERE device_id = :did"
        ), {"old_j": f'"{imp_zone}"', "new_j": f'"{zone_name}"', "did": did})

    # Update import_zone_name to match zone_name for all rows (propagated or split)
    for iz_id, did, zone_name, imp_zone in rows:
        conn.execute(text(
            "UPDATE fw_interfaces SET import_zone_name = :new WHERE id = :id"
        ), {"new": zone_name, "id": iz_id})


def _backfill_import_zone_names(conn):
    """One-time backfill for import_zone_name on existing fw_interfaces rows.

    For each device, recovers the original zone names (as stored in traffic_logs
    and imported_rules) using fw_imported_objects zone→interface mappings as the
    authoritative source. Falls back to zone_name when no mapping is available.
    """
    needs = conn.execute(text(
        "SELECT COUNT(*) FROM fw_interfaces "
        "WHERE import_zone_name IS NULL AND zone_name IS NOT NULL"
    )).scalar()
    if not needs:
        return

    devices = conn.execute(text(
        "SELECT DISTINCT device_id FROM fw_interfaces "
        "WHERE import_zone_name IS NULL AND zone_name IS NOT NULL"
    )).fetchall()

    for (did,) in devices:
        iz_rows = conn.execute(text(
            "SELECT id, interface_name, zone_name FROM fw_interfaces "
            "WHERE device_id = :did AND zone_name IS NOT NULL AND import_zone_name IS NULL"
        ), {"did": did}).fetchall()
        if not iz_rows:
            continue

        # Build interface→original_zone map from stored zone objects
        iface_to_orig: dict[str, str] = {}
        zone_objs = conn.execute(text(
            "SELECT name, value FROM fw_imported_objects "
            "WHERE device_id = :did AND obj_type = 'zone'"
        ), {"did": did}).fetchall()
        for zone_name, val_json in zone_objs:
            try:
                val = json.loads(val_json) if isinstance(val_json, str) else val_json
                for iface in val.get("interfaces", []):
                    iface_to_orig[iface] = zone_name
            except (json.JSONDecodeError, TypeError, AttributeError):
                pass

        for iz_id, iface_name, zone in iz_rows:
            orig = iface_to_orig.get(iface_name, zone)
            conn.execute(text(
                "UPDATE fw_interfaces SET import_zone_name = :z WHERE id = :id"
            ), {"z": orig, "id": iz_id})


