def _name_cell_html(name: str, table: str, rule_id: int) -> str:
    _html = html_mod
    displayed = _html.escape(name) if name else '<span class="text-gray-600">-</span>'
    return (
        f'<div id="name-cell-{rule_id}" class="flex items-center gap-1">'
        f'<span class="font-mono text-xs text-gray-300">{displayed}</span>'
        f'<button class="name-edit-btn hidden text-gray-600 hover:text-gray-300 transition-colors ml-0.5 flex-shrink-0"'
        f' data-tbl="{_html.escape(table)}" data-rid="{rule_id}" data-name="{_html.escape(name or "")}"'
        f' onclick="editName(this.dataset.tbl,+this.dataset.rid,this.dataset.name)">'
        f'<svg class="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">'
        f'<path stroke-linecap="round" stroke-linejoin="round" stroke-width="2"'
        f' d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z"/>'
        f'</svg></button>'
        f'</div>'
    )


@app.post("/rules/toggle-disabled", response_class=JSONResponse)
async def rule_toggle_disabled(request: Request):
    body = await request.json()
    try:
        rule_id = int(body["rule_id"])
    except (KeyError, ValueError, TypeError):
        return JSONResponse({"error": "invalid rule_id"}, status_code=400)
    engine = get_engine()
    with engine.begin() as conn:
        row = conn.execute(text(
            "SELECT r.rule_name, _dev.id AS device_id "
            "FROM fw_rules_consolidated_1 r "
            "JOIN fw_devices _dev ON (_dev.display_name = r.device_host OR _dev.host_name = r.device_host) "
            "WHERE r.id = :id"
        ), {"id": rule_id}).fetchone()
        if not row:
            return JSONResponse({"error": "not found"}, status_code=404)
        rule_name, device_id = row[0], row[1]
        max_ts = conn.execute(text(
            "SELECT MAX(import_ts) FROM fw_imported_rules WHERE device_id = :did"
        ), {"did": device_id}).scalar()
        conn.execute(text("""
            UPDATE fw_imported_rules
            SET disabled = 1 - disabled
            WHERE device_id = :did
              AND rule_name = :name
              AND import_ts = :ts
        """), {"did": device_id, "name": rule_name, "ts": max_ts})
    return JSONResponse({"ok": True})


@app.post("/rules/name", response_class=HTMLResponse)
async def rule_set_name(request: Request):
    body    = await request.json()
    table   = body.get("table", "")
    try:
        rule_id = int(body["rule_id"])
    except (KeyError, ValueError, TypeError):
        return HTMLResponse("invalid rule_id", status_code=400)
    name    = body.get("name", "").strip()
    if table not in set(MODULE_TABLES.values()) | {"fw_rules_consolidated_1"}:
        return HTMLResponse("invalid table", status_code=400)
    engine = get_engine()
    with engine.begin() as conn:
        conn.execute(
            text(f"UPDATE {table} SET rule_name = :name WHERE id = :rid"),
            {"name": name or None, "rid": rule_id},
        )
    return HTMLResponse(_name_cell_html(name, table, rule_id))


# ── Rule sequencing ──────────────────────────────────────────────────────────

@app.post("/rules/reorder")
async def rules_reorder(request: Request):
    body      = await request.json()
    try:
        rule_id = int(body["rule_id"])
    except (KeyError, ValueError, TypeError):
        return JSONResponse({"ok": False, "moved": False}, status_code=400)
    direction = body.get("direction", "")
    if direction not in ("up", "down"):
        return JSONResponse({"error": "invalid direction"}, status_code=400)

    engine = get_engine()
    with engine.begin() as conn:
        row = conn.execute(text(
            "SELECT `sequence`, device_host, generated_at FROM fw_rules_filtered WHERE id = :rid"
        ), {"rid": rule_id}).fetchone()
        if not row or row[0] is None:
            return JSONResponse({"ok": False, "moved": False})

        seq, dh, ga = row
        if direction == "up":
            neighbor = conn.execute(text("""
                SELECT id, `sequence` FROM fw_rules_filtered
                WHERE generated_at = :ga AND device_host = :dh AND `sequence` < :seq
                ORDER BY `sequence` DESC LIMIT 1
            """), {"ga": ga, "dh": dh, "seq": seq}).fetchone()
        else:
            neighbor = conn.execute(text("""
                SELECT id, `sequence` FROM fw_rules_filtered
                WHERE generated_at = :ga AND device_host = :dh AND `sequence` > :seq
                ORDER BY `sequence` ASC LIMIT 1
            """), {"ga": ga, "dh": dh, "seq": seq}).fetchone()

        if not neighbor:
            return JSONResponse({"ok": True, "moved": False})

        nid, nseq = neighbor
        conn.execute(text("UPDATE fw_rules_filtered SET `sequence` = :s WHERE id = :r"),
                     {"s": nseq, "r": rule_id})
        conn.execute(text("UPDATE fw_rules_filtered SET `sequence` = :s WHERE id = :r"),
                     {"s": seq, "r": nid})

    return JSONResponse({"ok": True, "moved": True})


# ── Device Registry ───────────────────────────────────────────────────────────

PLATFORM_LABELS = {
    "panw":       "Palo Alto Networks",
    "opnsense":   "OPNsense",
    "fortigate":  "FortiGate",
    "checkpoint": "Check Point",
    "firepower":  "Cisco Firepower",
    "asa":        "Cisco ASA",
}


@app.get("/devices", response_class=HTMLResponse)
def devices_page(request: Request, collected: str = "", collect_error: str = "", collect_warning: str = "",
                 imported: str = "", import_error: str = "", import_warning: str = "", no_data: str = "",
                 discover_empty: str = ""):
    engine = get_engine()
    with engine.connect() as conn:
        _ensure_devices_table(conn)
        has_logs = get_has_logs(conn)
        try:
            rows = conn.execute(text(
                "SELECT id, host_name, display_name, platform, role, mgmt_ip, mgmt_port, notes,"
                " (api_key IS NOT NULL AND api_key != '') AS has_api,"
                " gaia_user, config, device_kind "
                # Scope-devices (device_kind='scope') are internal materializations of a
                # Panorama-source's shared / device-group / template scopes - they belong to
                # the Panorama view, not the flat device list.
                "FROM fw_devices WHERE device_kind IS NULL OR device_kind <> 'scope' "
                "ORDER BY display_name, host_name"
            )).mappings().all()
            devices = [dict(r) for r in rows]
        except Exception:
            devices = []

        # Managed-device recognition for DIRECT registrations, two detection paths:
        #   (1) device-side - the import persisted config.managed_by (a PA firewall
        #       reveals its Panorama, a FortiGate its FMG); works with NO manager
        #       registered - exactly when the PA partial-import pitfall matters most.
        #   (2) manager-side - the device's mgmt_ip/host matches a registered manager's
        #       persisted managed_device_ips (Panorama/FMG import) - covers devices
        #       imported before this feature or boxes that hide their pointer.
        # Surfaced as d["managed_hint"] = {kind, mgr(label/ip), registered(bool)}.
        _mgr_ip_maps = []   # [(manager-label, kind, {ip: name})]
        for d in devices:
            if d.get("device_kind") == "manager-source":
                try:
                    _mdi = (json.loads(d.get("config") or "{}") or {}).get("managed_device_ips") or {}
                except Exception:
                    _mdi = {}
                if _mdi:
                    _kind = "panorama" if d.get("platform") == "panw" else "fortimanager"
                    _mgr_ip_maps.append((d.get("display_name") or d.get("host_name")
                                         or d.get("mgmt_ip"), _kind, _mdi))
        for d in devices:
            if d.get("device_kind") == "manager-source":
                continue
            _hint = None
            try:
                _mb = (json.loads(d.get("config") or "{}") or {}).get("managed_by") or {}
            except Exception:
                _mb = {}
            if _mb.get("ip"):
                _hint = {"kind": _mb.get("kind"), "mgr": _mb["ip"], "registered": False}
                # is that manager registered? (match its ip against manager rows)
                for _md in devices:
                    if (_md.get("device_kind") == "manager-source"
                            and _mb["ip"] in (_md.get("mgmt_ip"), _md.get("host_name"))):
                        _hint["mgr"] = (_md.get("display_name") or _md.get("host_name")
                                        or _md.get("mgmt_ip"))
                        _hint["registered"] = True
            # Manager-side match runs when device-side found nothing OR could
            # not resolve its manager to a registered row (NAT: the box knows
            # its manager by a private IP, Gateshift by the public one - then
            # the IP never matches, but the NAME does: managed_device_ips
            # values carry the manager's device names, live-verified d907778
            # scenario). A name/IP hit upgrades the hint to registered.
            if _hint is None or not _hint.get("registered"):
                _own = {v for v in (d.get("mgmt_ip"), d.get("host_name"),
                                    d.get("display_name")) if v}
                for _lbl, _kind, _mdi in _mgr_ip_maps:
                    if _hint is not None and _hint.get("kind") not in (None, _kind):
                        continue
                    if _own & (set(_mdi) | {n for n in _mdi.values() if n}):
                        _hint = {"kind": _kind, "mgr": _lbl, "registered": True}
                        break
            d["managed_hint"] = _hint

        # Parse CP per-device import config so the template can render
        # the import button. Gateway-as-device wizard pins package in
        # config.cp.policy_package; legacy rows used config.import.*.
        for d in devices:
            if d.get("platform") == "checkpoint":
                try:
                    cfg = json.loads(d.get("config") or "{}")
                    cp_cfg = cfg.get("cp") or {}
                    imp    = cfg.get("import") or {}
                    d["cp_import_pkg"]   = cp_cfg.get("policy_package") or imp.get("policy_package")
                    d["cp_import_layer"] = imp.get("access_layer")
                    d["cp_is_legacy"]    = not bool(cp_cfg.get("gateway_uid"))
                    d["cp_mgmt_ip"]      = (cp_cfg.get("mgmt") or {}).get("ip")
                except Exception:
                    d["cp_import_pkg"]   = None
                    d["cp_import_layer"] = None
                    d["cp_is_legacy"]    = True
                    d["cp_mgmt_ip"]      = None
            elif d.get("platform") == "fortigate":
                try:
                    fg = (json.loads(d.get("config") or "{}").get("fortigate") or {})
                    _nm = (fg.get("nat_mode") or "").lower()
                except Exception:
                    _nm = ""
                # Explicit pin (central/policy) vs unset - unset means the edit
                # form lazily probes the box to pre-select (no page-load tax).
                d["nat_mode"] = _nm if _nm in ("central", "policy") else ""
                d["nat_mode_pinned"] = bool(d["nat_mode"])
            elif d.get("platform") == "firepower":
                try:
                    ftd_cfg = (json.loads(d.get("config") or "{}").get("ftd") or {})
                    d["ftd_username"] = ftd_cfg.get("username") or "admin"
                except Exception:
                    d["ftd_username"] = "admin"
            elif d.get("platform") == "panw":
                try:
                    pw = (json.loads(d.get("config") or "{}").get("panw") or {})
                    _rm = (pw.get("routing_mode") or "").lower()
                except Exception:
                    _rm = ""
                # legacy/advanced = explicit pin; 'auto'/unset = resolved at
                # generate time (live probe of advance-routing, or Panorama-pin note).
                d["routing_mode"] = _rm if _rm in ("legacy", "advanced") else "auto"
                d["routing_mode_pinned"] = d["routing_mode"] in ("legacy", "advanced")

        # Per-device last-import timestamp. API devices read across imported
        # rules/objects/drops - a fresh lab box may legitimately have zero
        # policies but still hold imported objects (addresses, services) plus
        # network-collector data, so any non-empty imported table counts as
        # "imported". Syslog devices read from fw_flows. Shared with the
        # /rules entry guard via _device_last_import_ts (single source).
        for d in devices:
            d["last_import_ts"] = _device_last_import_ts(
                conn, d["id"], d.get("platform"), d.get("has_api"), d.get("host_name"))

        # Manager-source: the default scope to land on when its hostname is clicked. Panorama
        # DGs / shared hold BOTH objects AND rules, so land on a POLICY scope (root→policy). But
        # CheckPoint / FMG split objects (policy = domain/ADOM, no rules) from rules (rulebase =
        # package) - landing on a policy scope there shows an empty rulebase, so prefer a RULEBASE
        # (package) first. The picked scope pre-selects the header switcher.
        for d in devices:
            if d.get("device_kind") == "manager-source":
                if (d.get("platform") or "") in ("checkpoint", "fortigate"):
                    _order = ("(s.scope_role='rulebase') DESC, (s.scope_role='policy') DESC, "
                              "(s.scope_role='root') DESC")
                else:
                    _order = "(s.scope_role='root') DESC, (s.scope_role='policy') DESC"
                _ps = conn.execute(text(
                    "SELECT COALESCE(sd.display_name, sd.host_name) AS nm FROM fw_scopes s "
                    "JOIN fw_devices sd ON sd.id = s.scope_device_id "
                    "WHERE s.manager_device_id = :m "
                    f"ORDER BY {_order}, s.position, s.id LIMIT 1"), {"m": d["id"]}).fetchone()
                d["pano_default_scope"] = _ps[0] if _ps else None

        # Capability flags for the gating banner. Mirrors the eligibility logic
        # in /rules: target-capable = role∈{target,both} ∧ platform∈DRIVERS ∧ api_key set.
        has_source_capable = any(
            (d.get("role") or "both") in ("source", "both") for d in devices
        )
        has_target_capable = any(
            (d.get("role") or "both") in ("target", "both")
            and d.get("platform") in DEPLOY_DRIVERS
            and d.get("has_api")
            for d in devices
        )

    from deploy.manager_backends import manager_ui_available
    return templates.TemplateResponse(request, "devices.html", {
        "manager_ui":         manager_ui_available(),
        "devices":            devices,
        "platform_labels":    PLATFORM_LABELS,
        "has_logs":           has_logs,
        "collected":          collected,
        "collect_error":      collect_error,
        "collect_warning":    collect_warning,
        "imported":           imported,
        "import_error":       import_error,
        "import_warning":     import_warning,
        "no_data":            no_data,
        "discover_empty":     discover_empty if discover_empty in ("nolog", "nodev") else "",
        "has_source_capable": has_source_capable,
        "has_target_capable": has_target_capable,
    })


@app.post("/devices/add")
async def devices_add(request: Request):
    form         = await request.form()
    platform     = (form.get("platform") or "").strip() or None
    mgmt_ip      = (form.get("mgmt_ip") or "").strip() or None
    try:
        mgmt_port = int(form.get("mgmt_port") or 443)
    except (ValueError, TypeError):
        mgmt_port = 443
    api_key      = (form.get("api_key") or "").strip() or None
    gaia_user    = (form.get("gaia_user") or "").strip() or None
    gaia_pw      = (form.get("gaia_password") or "").strip() or None
    notes        = (form.get("notes") or "").strip() or None
    role         = (form.get("role") or "both").strip().lower()

    if platform not in (list(PLATFORM_LABELS) + [None]):
        platform = None
    if role not in ("source", "target", "both"):
        role = "both"

    # Manager-managed target (Panorama / FortiManager) - an ENTERPRISE feature.
    # The EE module registers a per-platform config builder (deploy.manager_backends);
    # the CE ships no manager-UI logic. build_manager_config returns None in the CE
    # (or when the form's manager toggle is off).
    from deploy.manager_backends import build_manager_config
    config_json = None
    _built = build_manager_config(platform, form)
    if _built:
        config_json, mgmt_ip, api_key = _built

    # Cisco FTD (FDM): OAuth password grant - no static API keys. The admin
    # PASSWORD rides in api_key (the platform's secret column); the username
    # is pinned in config.ftd.username (default 'admin').
    if platform == "firepower":
        ftd_user = (form.get("ftd_username") or "").strip() or "admin"
        config_json = json.dumps({"ftd": {"username": ftd_user}})
        role = "source"   # source-only platform (ASA precedent)

    # Hostname is auto-detected from logs or API import.
    # Use mgmt_ip as placeholder until the real hostname is known.
    host_name = mgmt_ip
    if not host_name:
        return RedirectResponse("/devices", status_code=303)

    engine = get_engine()
    with engine.begin() as conn:
        _ensure_devices_table(conn)
        # Re-Add of an existing host updates connection fields but preserves
        # role: Edit is the only path that changes role. Likewise display_name
        # is never touched here (no form field carries it).
        conn.execute(text("""
            INSERT INTO fw_devices (host_name, platform, role, mgmt_ip, mgmt_port,
                                    api_key, gaia_user, gaia_password, notes, config)
            VALUES (:hn, :pl, :role, :ip, :port, :key, :gu, :gp, :notes, :config)
            ON DUPLICATE KEY UPDATE
                platform=:pl, mgmt_ip=:ip,
                mgmt_port=:port, api_key=:key,
                gaia_user=:gu, gaia_password=:gp, notes=:notes,
                config=COALESCE(:config, config)
        """), {"hn": host_name, "pl": platform, "role": role,
               "ip": mgmt_ip, "port": mgmt_port,
               "key": secrets_util.protect(api_key),
               "gu": gaia_user, "gp": secrets_util.protect(gaia_pw),
               "notes": notes, "config": config_json})

    return RedirectResponse("/devices", status_code=303)


@app.post("/devices/edit/{device_id}")
async def devices_edit(device_id: int, request: Request):
    form         = await request.form()
    # Platform is identity-pinned at create-time and immutable thereafter.
    # The edit form renders it as static text (no form field); ignore any
    # value posted via direct curl etc. - never touch fw_devices.platform.
    mgmt_ip      = (form.get("mgmt_ip") or "").strip() or None
    try:
        mgmt_port = int(form.get("mgmt_port") or 443)
    except (ValueError, TypeError):
        mgmt_port = 443
    api_key_raw  = (form.get("api_key") or "").strip()
    gaia_user    = (form.get("gaia_user") or "").strip() or None
    gaia_pw_raw  = (form.get("gaia_password") or "").strip()
    notes        = (form.get("notes") or "").strip() or None
    role         = (form.get("role") or "both").strip().lower()
    nat_mode     = (form.get("nat_mode") or "").strip().lower()  # Forti only
    routing_mode = (form.get("routing_mode") or "").strip().lower()  # PA only

    # If the user is (re)setting the Gaia password and left the user blank,
    # default to "admin" (CP's stock account). Mirrors /devices/add/cp/save.
    if gaia_pw_raw and not gaia_user:
        gaia_user = "admin"

    if role not in ("source", "target", "both"):
        role = "both"

    # Build SET fragments for secrets that follow "blank = keep" semantics.
    # api_key + gaia_password are write-only (passwords); the form sends an
    # empty value when the user didn't touch the field, and we must not
    # clobber the stored value to NULL in that case.
    secret_sets = []
    secret_params: dict[str, str] = {}
    if api_key_raw:
        secret_sets.append("api_key=:key")
        secret_params["key"] = secrets_util.protect(api_key_raw)
    if gaia_pw_raw:
        secret_sets.append("gaia_password=:gp")
        secret_params["gp"] = secrets_util.protect(gaia_pw_raw)

    engine = get_engine()
    with engine.begin() as conn:
        # CP gateway-as-device rows pin identity in (mgmt_ip, gateway_uid,
        # policy_package). mgmt_ip = Gateway-IP and is identity, not a
        # mutable endpoint - refuse to overwrite it on edit. Legacy CP and
        # PANW rows keep the original behavior.
        existing = conn.execute(text(
            "SELECT platform, mgmt_ip, mgmt_port, config FROM fw_devices WHERE id=:id"
        ), {"id": device_id}).mappings().fetchone()
        ip_to_write   = mgmt_ip
        port_to_write = mgmt_port
        if existing and existing["platform"] == "checkpoint":
            try:
                cfg = json.loads(existing["config"] or "{}")
            except Exception:
                cfg = {}
            if (cfg.get("cp") or {}).get("gateway_uid"):
                ip_to_write   = existing["mgmt_ip"]
                port_to_write = existing["mgmt_port"]
            # Fail-fast Gaia probe on credential change - same contract as
            # the add wizard (a wrong password otherwise resurfaces later as
            # cryptic collect failures). Probe target = the gateway IP.
            if gaia_pw_raw:
                _ghost = ip_to_write or mgmt_ip or existing["mgmt_ip"]
                try:
                    _gr = requests.post(f"https://{_ghost}:443/gaia_api/login",
                                        json={"user": gaia_user,
                                              "password": gaia_pw_raw},
                                        verify=False, timeout=(6, 20))
                    if not (_gr.status_code == 200
                            and (_gr.json() or {}).get("sid")):
                        return RedirectResponse(
                            "/devices?import_error=" + urllib.parse.quote(
                                f"Gaia login failed on {_ghost} "
                                f"(HTTP {_gr.status_code}) - credentials NOT "
                                "saved; check password / Gaia REST API"),
                            status_code=303)
                    try:
                        requests.post(f"https://{_ghost}:443/gaia_api/logout",
                                      headers={"X-chkp-sid": _gr.json()["sid"]},
                                      verify=False, timeout=(6, 10))
                    except Exception:
                        pass
                except requests.exceptions.RequestException as exc:
                    return RedirectResponse(
                        "/devices?import_error=" + urllib.parse.quote(
                            f"Gaia API on {_ghost} not reachable "
                            f"({exc.__class__.__name__}) - credentials NOT "
                            "saved; enable the Gaia REST API first"),
                        status_code=303)

        # FortiGate NAT rendering mode (Stufe B): persist into
        # config.fortigate.nat_mode {auto|central|policy}, preserving other config.
        config_set, config_param = "", {}
        if (existing and existing["platform"] == "fortigate"
                and nat_mode in ("auto", "central", "policy")):
            try:
                fcfg = json.loads(existing["config"] or "{}")
            except Exception:
                fcfg = {}
            fcfg.setdefault("fortigate", {})["nat_mode"] = nat_mode
            config_set = ", config=:cfg"
            config_param["cfg"] = json.dumps(fcfg)
        elif (existing and existing["platform"] == "panw"
                and routing_mode in ("auto", "legacy", "advanced")):
            # PAN-OS routing render mode: persist into config.panw.routing_mode
            # {auto|legacy|advanced}, preserving other config (e.g. config.panorama).
            try:
                pcfg = json.loads(existing["config"] or "{}")
            except Exception:
                pcfg = {}
            pcfg.setdefault("panw", {})["routing_mode"] = routing_mode
            config_set = ", config=:cfg"
            config_param["cfg"] = json.dumps(pcfg)
        elif existing and existing["platform"] == "firepower":
            # FDM admin username: persist into config.ftd.username (blank =
            # keep 'admin' default), preserving other config keys.
            role = "source"   # source-only platform - role is not editable
            ftd_user = (form.get("ftd_username") or "").strip() or "admin"
            try:
                tcfg = json.loads(existing["config"] or "{}")
            except Exception:
                tcfg = {}
            tcfg.setdefault("ftd", {})["username"] = ftd_user
            config_set = ", config=:cfg"
            config_param["cfg"] = json.dumps(tcfg)

        # display_name is intentionally not in the SET list - the form has no
        # field for it, so writing :dn would clobber any pre-existing value
        # (set elsewhere e.g. via auto-detected hostname) to NULL on every save.
        sql = (
            "UPDATE fw_devices SET role=:role, "
            "mgmt_ip=:ip, mgmt_port=:port, gaia_user=:gu, notes=:notes"
        )
        if secret_sets:
            sql += ", " + ", ".join(secret_sets)
        sql += config_set
        sql += " WHERE id=:id"
        params = {"role": role, "ip": ip_to_write, "port": port_to_write,
                  "gu": gaia_user, "notes": notes, "id": device_id,
                  **secret_params, **config_param}
        conn.execute(text(sql), params)
    return RedirectResponse("/devices", status_code=303)


def _iface_ref_summary(d: dict) -> str:
    """Human-readable referrer summary from refmodel.deletability - shared by the
    interface delete-guard and the skip-guard so both name the same blockers."""
    parts: dict[str, int] = {}
    for r in d.get("blockers", []):
        parts[r.referrer_kind] = parts.get(r.referrer_kind, 0) + 1
    summary = ", ".join(f"{n} {k}" for k, n in sorted(parts.items()))
    if d.get("sole_used_zone"):
        extra = f"sole member of in-use zone {d['sole_used_zone']!r}"
        summary = f"{summary}; {extra}" if summary else extra
    return summary


def _sync_zone_external(conn, device_id, *zone_names):
    """fw_zones.is_external is DERIVED since the WAN marker moved to the
    Interfaces tab (interface role='wan'): a zone is external iff at least
    one bound interface carries role 'wan'. Keeps the two readers - the
    syslog NAT inference (27_infer_nat_rules) and the PA NAT to-zone
    fallback - working unchanged; the zone-level toggle UI stays hidden."""
    if not device_id:
        return
    for zn in {z for z in zone_names if z and z != "default"}:
        conn.execute(text(
            "UPDATE fw_zones SET is_external = EXISTS("
            "  SELECT 1 FROM fw_interfaces "
            "  WHERE device_id = :d AND zone_name = :z AND role = 'wan') "
            "WHERE device_id = :d AND name = :z"
        ), {"d": device_id, "z": zn})


@app.post("/interfaces/{iface_id}/update", response_class=JSONResponse)
async def interface_update(iface_id: int, request: Request):
    """Update zone_name and/or ip_addresses for a single interface."""
    body = await request.json()
    engine = get_engine()
    with engine.begin() as conn:
        # Read import_zone_name, current zone_name, device_id before updating
        old_row = conn.execute(text(
            "SELECT import_zone_name, zone_name, device_id, interface_name, "
            "       import_interface_name FROM fw_interfaces WHERE id = :id"
        ), {"id": iface_id}).fetchone()
        import_zone = old_row[0] if old_row else None
        old_zone_name = old_row[1] if old_row else None
        device_id = old_row[2] if old_row else None
        old_iface_name = old_row[3] if old_row else None
        import_iface_name = old_row[4] if old_row else None

        sets, params = [], {"id": iface_id}
        zone_name_val = None
        new_iface_name = None
        if "interface_name" in body:
            new_iface_name = (body["interface_name"] or "").strip()
            if not new_iface_name:
                return JSONResponse({"error": "Interface name cannot be empty"}, status_code=400)
            sets.append("interface_name = :iface_name")
            params["iface_name"] = new_iface_name
        if "zone_name" in body:
            zone_name_val = (body["zone_name"] or "").strip() or None
            sets.append("zone_name = :zone")
            params["zone"] = zone_name_val
        if "vr_name" in body:
            vrn = (body["vr_name"] or "").strip() or "default"
            sets.append("vr_name = :vrn")
            params["vrn"] = vrn
        if "description" in body:
            desc_raw = body["description"]
            desc_val = (desc_raw or "").strip() if isinstance(desc_raw, str) else None
            sets.append("description = :desc")
            params["desc"] = desc_val or None
        if "role" in body:
            role_raw = (body["role"] or "").strip().lower() if isinstance(body["role"], str) else None
            if role_raw and role_raw not in ("lan", "wan", "dmz", "undefined"):
                return JSONResponse(
                    {"error": f"Invalid role {role_raw!r} - expected lan/wan/dmz/undefined"},
                    status_code=400,
                )
            sets.append("role = :role")
            params["role"] = role_raw or None
        # Interface type is user-reclassifiable (migration: a source tunnel can
        # become a VLAN/L3 on the target). The renderer + push pre-flight both
        # read fw_interfaces.iface_type, so this is the single source of truth -
        # change it and the tunnel-out-of-scope block lifts, the renderer emits
        # the new type. VLAN parent is set via parent_iface_name (resolved
        # through the iface-override at push, like any other iface name).
        if "iface_type" in body:
            it_raw = (body["iface_type"] or "").strip().lower() or None
            if it_raw and it_raw not in ("physical", "vlan", "bond", "loopback", "tunnel"):
                return JSONResponse(
                    {"error": f"invalid iface_type {it_raw!r}"}, status_code=400,
                )
            sets.append("iface_type = :itype")
            params["itype"] = it_raw
        if "parent_iface_name" in body:
            par_raw = (body["parent_iface_name"] or "").strip() or None
            sets.append("parent_iface_name = :parent")
            params["parent"] = par_raw
        if "vlan_tag" in body:
            vt_raw = body["vlan_tag"]
            if vt_raw in (None, "", 0):
                vt_val: int | None = None
            else:
                try:
                    vt_val = int(vt_raw)
                except (TypeError, ValueError):
                    return JSONResponse(
                        {"error": f"Invalid VLAN tag {vt_raw!r} - must be 1..4094"},
                        status_code=400,
                    )
                if vt_val < 1 or vt_val > 4094:
                    return JSONResponse(
                        {"error": f"VLAN tag {vt_val} out of range (1..4094)"},
                        status_code=400,
                    )
            sets.append("vlan_tag = :vtag")
            params["vtag"] = vt_val
        if "enabled" in body:
            sets.append("enabled = :en")
            params["en"] = 1 if bool(body["enabled"]) else 0
        # deploy_skip - exclude this source interface from the push. Only legal
        # when nothing references it (a skipped interface that is referenced would
        # leave dangling refs at push), so setting it runs the same reference
        # guard as delete. Clearing it (skip=0) is always allowed.
        if "deploy_skip" in body:
            skip_val = 1 if bool(body["deploy_skip"]) else 0
            if skip_val and device_id and old_iface_name:
                host = conn.execute(text(
                    "SELECT host_name FROM fw_devices WHERE id = :id"
                ), {"id": device_id}).scalar()
                d = refmodel.deletability(conn, device_id, "interface",
                                          old_iface_name, device_host=host)
                if not d["removable"]:
                    return JSONResponse(
                        {"error": f"Interface {old_iface_name!r} is referenced "
                                  f"({_iface_ref_summary(d)}) - can't skip; remap or "
                                  f"remove those references first."},
                        status_code=409,
                    )
            sets.append("deploy_skip = :dskip")
            params["dskip"] = skip_val
        # Bond/AE member list - JSON array of physical-iface names. None or
        # empty list both wipe the column back to NULL so an empty bond
        # surfaces correctly in the renderer's empty-bond DroppedField.
        if "member_iface_names" in body:
            raw_members = body["member_iface_names"]
            if raw_members in (None, ""):
                members_list: list[str] = []
            elif isinstance(raw_members, list):
                members_list = [str(m).strip() for m in raw_members if str(m).strip()]
            else:
                return JSONResponse(
                    {"error": "member_iface_names must be a list of iface names"},
                    status_code=400,
                )
            # Reject self-membership and duplicates so the renderer can trust
            # the JSON without re-validating.
            seen_m: set[str] = set()
            for m in members_list:
                if m in seen_m:
                    return JSONResponse(
                        {"error": f"duplicate member {m!r}"}, status_code=400,
                    )
                seen_m.add(m)
            sets.append("member_iface_names = :members")
            params["members"] = json.dumps(members_list) if members_list else None
        if "ip_addresses" in body:
            ips = body["ip_addresses"] if isinstance(body["ip_addresses"], list) else []
            # Validate each IP/CIDR
            for ip_str in ips:
                try:
                    ipaddress.ip_network(ip_str, strict=False)
                except (ValueError, TypeError):
                    return JSONResponse({"error": f"Invalid IP/CIDR: {ip_str}"}, status_code=400)
            sets.append("ip_addresses = :ips")
            params["ips"] = json.dumps(ips)
        else:
            ips = None
        # dhcp_enabled is exclusive with static IPs - switching DHCP on also
        # clears the iface's IP list and its connected routes downstream.
        if "dhcp_enabled" in body:
            dhcp_val = bool(body["dhcp_enabled"])
            sets.append("dhcp_enabled = :dhcp")
            params["dhcp"] = 1 if dhcp_val else 0
            if dhcp_val:
                sets.append("ip_addresses = NULL")
                ips = []   # trigger the auto-route cleanup branch below
        # Vendor-specific properties via interface_schemas - JSON_MERGE_PATCH
        # so partial updates don't wipe other slots. None values delete the
        # slot via the same JSON-merge semantic.
        if "properties" in body and isinstance(body["properties"], dict):
            from interface_schemas import schema_for, coerce_value, field_keys
            tgt_row = conn.execute(text(
                "SELECT platform FROM fw_devices WHERE id = ("
                "  SELECT device_id FROM fw_interfaces WHERE id = :id"
                ")"
            ), {"id": iface_id}).fetchone()
            platform = (tgt_row[0] if tgt_row else "") or ""
            valid_keys = field_keys(platform)
            schema = schema_for(platform)
            field_by_key = {f["key"]: f for f in (schema.get("fields") or [])}
            clean: dict = {}
            for k, v in body["properties"].items():
                if k not in valid_keys:
                    continue
                field = field_by_key.get(k) or {}
                coerced = coerce_value(field, v)
                clean[k] = coerced  # None drops the slot via JSON_MERGE_PATCH
            if clean:
                sets.append(
                    "properties = JSON_MERGE_PATCH("
                    "  COALESCE(properties, JSON_OBJECT()), :props_patch)"
                )
                params["props_patch"] = json.dumps(clean)
        if sets:
            conn.execute(text(f"UPDATE fw_interfaces SET {', '.join(sets)} WHERE id = :id"), params)

        # WAN marker / zone binding changed → re-derive is_external on the
        # affected zone(s) (old + new when the binding moved).
        if "role" in body or "zone_name" in body:
            _cur_zone = zone_name_val if "zone_name" in body else old_zone_name
            _sync_zone_external(conn, device_id, _cur_zone, old_zone_name)

        # Propagate zone rename to imported rules and traffic logs.
        # Uses import_zone_name (the name currently stored in traffic_logs/imported_rules)
        # so renames work even after multiple successive edits.
        if (zone_name_val and import_zone and zone_name_val != import_zone and device_id):
            host_row = conn.execute(text(
                "SELECT COALESCE(display_name, host_name) FROM fw_devices WHERE id = :id"
            ), {"id": device_id}).scalar()
            if host_row:
                conn.execute(text(
                    "UPDATE fw_flows SET src_zone = :new "
                    "WHERE src_zone = :old AND source_type = 'api_import' AND device_host = :h"
                ), {"new": zone_name_val, "old": import_zone, "h": host_row})
                conn.execute(text(
                    "UPDATE fw_flows SET dst_zone = :new "
                    "WHERE dst_zone = :old AND source_type = 'api_import' AND device_host = :h"
                ), {"new": zone_name_val, "old": import_zone, "h": host_row})
                conn.execute(text(
                    "UPDATE fw_imported_rules SET src_zones = REPLACE(src_zones, :old_j, :new_j) "
                    "WHERE device_id = :did"
                ), {"old_j": f'"{import_zone}"', "new_j": f'"{zone_name_val}"', "did": device_id})
                conn.execute(text(
                    "UPDATE fw_imported_rules SET dst_zones = REPLACE(dst_zones, :old_j, :new_j) "
                    "WHERE device_id = :did"
                ), {"old_j": f'"{import_zone}"', "new_j": f'"{zone_name_val}"', "did": device_id})
            # Update import_zone_name on this interface AND sibling interfaces
            # that still share the same zone_name (not yet individually renamed).
            # Siblings already renamed to a different zone_name are excluded so
            # their import_zone_name stays correct for their own zone.
            conn.execute(text(
                "UPDATE fw_interfaces SET import_zone_name = :new "
                "WHERE device_id = :did AND import_zone_name = :old "
                "AND (zone_name = :old_zone OR id = :id)"
            ), {"new": zone_name_val, "old": import_zone, "did": device_id,
                "old_zone": old_zone_name, "id": iface_id})

        # Upsert zone color into fw_zones when zone name or color is provided
        zone_color_val = (body.get("zone_color") or "").strip() or None
        if zone_name_val == "default":
            zone_name_val = None      # no-zone sentinel - never seed a zone row
        if zone_name_val and zone_color_val and device_id:
            conn.execute(text("""
                INSERT INTO fw_zones (device_id, name, color) VALUES (:did, :n, :c)
                ON DUPLICATE KEY UPDATE color = :c
            """), {"did": device_id, "n": zone_name_val, "c": zone_color_val})
        elif zone_name_val and device_id:
            conn.execute(text("""
                INSERT IGNORE INTO fw_zones (device_id, name, color) VALUES (:did, :n, 'blue')
            """), {"did": device_id, "n": zone_name_val})

        # Cascade the interface rename through every referrer via the engine:
        # routes, VLAN-parent + bond-member links, NAT/PBF interface refs (the
        # old helper only touched fw_routes → parent/member/NAT/PBF dangled).
        if new_iface_name and old_iface_name and new_iface_name != old_iface_name and device_id:
            refmodel.cascade_rename(conn, device_id, "interface",
                                    old_iface_name, new_iface_name)
            # Persist the rename intent so it survives the full re-import (IF-1).
            # Keyed on the immutable import_interface_name. Only for imported
            # interfaces (manual extras have no import name + aren't re-imported).
            # Renaming back to the source name clears the override.
            if import_iface_name:
                if new_iface_name == import_iface_name:
                    conn.execute(text(
                        "DELETE FROM fw_interface_overrides "
                        "WHERE device_id = :d AND import_interface_name = :imp"
                    ), {"d": device_id, "imp": import_iface_name})
                else:
                    conn.execute(text("""
                        INSERT INTO fw_interface_overrides
                            (device_id, import_interface_name, interface_name)
                        VALUES (:d, :imp, :new)
                        ON DUPLICATE KEY UPDATE interface_name = VALUES(interface_name)
                    """), {"d": device_id, "imp": import_iface_name, "new": new_iface_name})

            # Sub-interface follow-up: every vendor dialect derives the child
            # name from the parent ('<parent>.<tag>' - PA ethernet1/2.110,
            # Gaia eth1.110, Forti conventionally port4.110). A parent rebind
            # therefore auto-renames each child that still follows the
            # '<old-parent>.<suffix>' pattern (manually named children are
            # left alone), with the full referrer cascade + re-import-safe
            # override per child.
            kids = conn.execute(text(
                "SELECT interface_name, import_interface_name, vlan_tag "
                "FROM fw_interfaces WHERE device_id = :d "
                "AND parent_iface_name IN (:new, :old)"
            ), {"d": device_id, "new": new_iface_name,
                "old": old_iface_name}).fetchall()
            for kid_name, kid_import, kid_vtag in kids:
                if not kid_name:
                    continue
                if kid_name.startswith(old_iface_name + "."):
                    # dotted parent-derived name (PA/CP/Cisco sources)
                    kid_new = new_iface_name + kid_name[len(old_iface_name):]
                elif kid_vtag and kid_import and kid_name == kid_import:
                    # free-form source name (Forti gs-vl110) still untouched -
                    # lift it onto the target's dotted convention
                    kid_new = f"{new_iface_name}.{kid_vtag}"
                else:
                    continue      # manually named child - leave it alone
                if kid_new == kid_name:
                    continue
                conn.execute(text(
                    "UPDATE fw_interfaces SET interface_name = :new "
                    "WHERE device_id = :d AND interface_name = :old"
                ), {"new": kid_new, "d": device_id, "old": kid_name})
                refmodel.cascade_rename(conn, device_id, "interface",
                                        kid_name, kid_new)
                if kid_import:
                    if kid_new == kid_import:
                        conn.execute(text(
                            "DELETE FROM fw_interface_overrides "
                            "WHERE device_id = :d AND import_interface_name = :imp"
                        ), {"d": device_id, "imp": kid_import})
                    else:
                        conn.execute(text("""
                            INSERT INTO fw_interface_overrides
                                (device_id, import_interface_name, interface_name)
                            VALUES (:d, :imp, :new)
                            ON DUPLICATE KEY UPDATE interface_name = VALUES(interface_name)
                        """), {"d": device_id, "imp": kid_import, "new": kid_new})

        # Auto-create connected routes from interface IPs
        if ips is not None:
            row = conn.execute(text(
                "SELECT device_id, interface_name FROM fw_interfaces WHERE id = :id"
            ), {"id": iface_id}).fetchone()
            if row:
                did, iface_name = row[0], row[1]
                # Remove old auto-generated routes for this interface
                conn.execute(text(
                    "DELETE FROM fw_routes WHERE device_id = :did AND interface_name = :iface"
                ), {"did": did, "iface": iface_name})
                # Create connected route for each IP/CIDR
                for ip_str in ips:
                    try:
                        net = ipaddress.ip_network(ip_str, strict=False)
                        conn.execute(text("""
                            INSERT IGNORE INTO fw_routes
                                (device_id, prefix, prefix_len, ip_from, ip_to, interface_name, vr_name)
                            VALUES (:did, :prefix, :plen, :ip_from, :ip_to, :iface, 'default')
                        """), {
                            "did": did, "prefix": str(net), "plen": net.prefixlen,
                            "ip_from": int(net.network_address), "ip_to": int(net.broadcast_address),
                            "iface": iface_name,
                        })
                    except (ValueError, TypeError):
                        pass
        set_needs_generate(conn, True, strand="network")
    return JSONResponse({"ok": True})


@app.post("/interfaces/add", response_class=JSONResponse)
async def interface_add(request: Request):
    """Insert a fw_interfaces row. Accepts optional ip_addresses (list or
    comma-separated string) and zone_name so the inline Add-row can
    create a fully-defined interface in one call. Each IP/CIDR also
    seeds a connected route - same auto-route behavior as
    /interfaces/<id>/update.

    Returns 409 on collision (interface name already exists on this
    device, or one of the supplied IPs is already assigned to another
    interface on the same device). The frontend surfaces the message
    inline so the user can correct the input without losing the row.
    """
    body = await request.json()
    device_id = body.get("device_id")
    name = (body.get("interface_name") or "").strip()
    if not device_id or not name:
        return JSONResponse({"error": "device_id and interface_name required"}, status_code=400)
    # Composite (SW-C): on a Panorama DG the network strand lives in the template
    # (the Network tab reads from it) → land the new interface there, not on the DG.
    with get_engine().connect() as _nc:
        device_id = _pano_net_device_id(_nc, device_id)

    # Normalize IPs - accept list or "ip1, ip2" string. Validate each
    # before touching the DB so a partial-failure can't leave the row
    # half-inserted.
    raw_ips = body.get("ip_addresses")
    if isinstance(raw_ips, str):
        ips = [p.strip() for p in raw_ips.split(",") if p.strip()]
    elif isinstance(raw_ips, list):
        ips = [str(p).strip() for p in raw_ips if str(p).strip()]
    else:
        ips = []
    for ip_str in ips:
        try:
            ipaddress.ip_network(ip_str, strict=False)
        except (ValueError, TypeError):
            return JSONResponse({"error": f"Invalid IP/CIDR: {ip_str}"}, status_code=400)
    zone_name = (body.get("zone_name") or "").strip() or None
    description = (body.get("description") or "").strip() or None
    dhcp_enabled = bool(body.get("dhcp_enabled"))
    # User-supplied type/parent/vlan_tag - UI Add-row sends these directly.
    # When absent (older clients) fall back to parse_iface_name below.
    body_type = (body.get("iface_type") or "").strip().lower() or None
    if body_type and body_type not in ("physical", "vlan", "bond", "loopback", "tunnel"):
        return JSONResponse(
            {"error": f"invalid iface_type {body_type!r}"}, status_code=400,
        )
    body_parent = (body.get("parent_iface_name") or "").strip() or None
    body_vtag_raw = body.get("vlan_tag")
    body_vtag: int | None = None
    if body_vtag_raw not in (None, ""):
        try:
            body_vtag = int(body_vtag_raw)
        except (TypeError, ValueError):
            return JSONResponse(
                {"error": f"invalid vlan_tag {body_vtag_raw!r}"}, status_code=400,
            )
        if body_vtag < 1 or body_vtag > 4094:
            return JSONResponse(
                {"error": "vlan_tag out of range (1..4094)"}, status_code=400,
            )
    if body_type == "vlan" and (not body_parent or body_vtag is None):
        return JSONResponse(
            {"error": "VLAN sub-interface needs both parent_iface_name and vlan_tag"},
            status_code=400,
        )
    if dhcp_enabled and ips:
        return JSONResponse(
            {"error": "DHCP and a static IP can't both be set on the same interface."},
            status_code=400,
        )

    engine = get_engine()
    with engine.begin() as conn:
        # Name collision - UNIQUE (device_id, interface_name) would
        # silently swallow the INSERT IGNORE otherwise, leaving the user
        # to wonder why their new row never appeared.
        existing_name = conn.execute(text(
            "SELECT id FROM fw_interfaces WHERE device_id = :did "
            "AND interface_name = :name LIMIT 1"
        ), {"did": device_id, "name": name}).fetchone()
        if existing_name:
            return JSONResponse(
                {"error": f"Interface '{name}' already exists on this device."},
                status_code=409,
            )

        # IP overlap - flag any incoming network that intersects an
        # existing iface's ip_addresses on the same device. Compare in
        # the integer range space; ip-version-mixing is impossible here
        # because both sides go through ip_network(strict=False).
        if ips:
            existing = conn.execute(text(
                "SELECT interface_name, ip_addresses FROM fw_interfaces "
                "WHERE device_id = :did AND ip_addresses IS NOT NULL "
                "AND ip_addresses <> '[]'"
            ), {"did": device_id}).fetchall()
            new_nets = [ipaddress.ip_network(s, strict=False) for s in ips]
            for ex_iname, ex_ips_json in existing:
                try:
                    ex_ips = json.loads(ex_ips_json) if isinstance(ex_ips_json, str) else (ex_ips_json or [])
                except Exception:
                    continue
                for ex_ip_str in ex_ips:
                    try:
                        ex_net = ipaddress.ip_network(ex_ip_str, strict=False)
                    except (ValueError, TypeError):
                        continue
                    for nn in new_nets:
                        if nn.version != ex_net.version:
                            continue
                        if nn.overlaps(ex_net):
                            return JSONResponse({
                                "error": (f"IP {nn} overlaps with {ex_net} on "
                                          f"interface '{ex_iname}'.")
                            }, status_code=409)

        # Name-parser provides defaults; explicit body fields win.
        classified, parent, vtag = parse_iface_name(name)
        if body_type:
            classified = body_type
        if body_parent:
            parent = body_parent
        if body_vtag is not None:
            vtag = body_vtag
        conn.execute(text("""
            INSERT INTO fw_interfaces
                (device_id, interface_name, iface_type, parent_iface_name, vlan_tag,
                 ip_addresses, zone_name, description, dhcp_enabled, origin)
            VALUES (:did, :name, :itype, :parent, :vtag, :ips, :zone, :desc, :dhcp,
                    'manual')
        """), {
            "did": device_id, "name": name,
            "itype": classified, "parent": parent, "vtag": vtag,
            "ips": json.dumps(ips) if ips else None,
            "zone": zone_name,
            "desc": description,
            "dhcp": 1 if dhcp_enabled else 0,
        })
        # Seed the zone entry if a name was given and no row exists yet
        # (mirrors the update endpoint so the new zone shows up in pickers).
        # 'default' = no-zone sentinel, never a real zone.
        if zone_name and zone_name != "default":
            conn.execute(text("""
                INSERT IGNORE INTO fw_zones (device_id, name, color) VALUES (:did, :n, 'blue')
            """), {"did": device_id, "n": zone_name})
        # Seed connected routes per IP, same as the update path.
        for ip_str in ips:
            try:
                net = ipaddress.ip_network(ip_str, strict=False)
                conn.execute(text("""
                    INSERT IGNORE INTO fw_routes
                        (device_id, prefix, prefix_len, ip_from, ip_to, interface_name, vr_name)
                    VALUES (:did, :prefix, :plen, :ip_from, :ip_to, :iface, 'default')
                """), {
                    "did": device_id, "prefix": str(net), "plen": net.prefixlen,
                    "ip_from": int(net.network_address), "ip_to": int(net.broadcast_address),
                    "iface": name,
                })
            except (ValueError, TypeError):
                pass
        set_needs_generate(conn, True, strand="network")
    return JSONResponse({"ok": True})


@app.post("/interfaces/{iface_id}/delete", response_class=JSONResponse)
async def interface_delete(iface_id: int, request: Request, net_did: int = 0):
    target_device_id = None
    try:
        body = await request.json()
        target_device_id = body.get("target_device_id")
    except Exception:
        pass
    engine = get_engine()
    with engine.begin() as conn:
        row = conn.execute(text(
            "SELECT device_id, interface_name FROM fw_interfaces WHERE id = :id"
        ), {"id": iface_id}).fetchone()
        if row:
            did, iname = row[0], row[1]
            if _pano_inherited_write_block(did, net_did):   # P3: inherited = read-only here
                return JSONResponse({"error": "This interface is inherited from a member template "
                                     "(read-only in the effective view). Switch the network scope "
                                     "to that template to delete it."}, status_code=409)
            # Any interface - source-imported or manual - may be deleted; it's
            # the user's config to shape. A deleted SOURCE interface comes back
            # on the next re-import (atomic replace), so delete is point-in-time
            # (skip is the in-place, push-only exclude). The reference-aware
            # guard below still blocks a delete that would dangle a referrer.
            # Reference-aware guard (REF-4/18): an interface is removable only
            # when nothing references it. The interface's own connected routes
            # cascade with it (cleared below); every other referrer - PBF
            # ingress/egress, NAT extintf, bond-member / VLAN-parent, and a rule
            # via the interface's sole zone - blocks the delete so we never leave
            # a dangling reference behind.
            host = conn.execute(text(
                "SELECT host_name FROM fw_devices WHERE id = :id"
            ), {"id": did}).scalar()
            d = refmodel.deletability(conn, did, "interface", iname, device_host=host)
            if not d["removable"]:
                return JSONResponse(
                    {"error": f"Interface {iname!r} is referenced "
                              f"({_iface_ref_summary(d)}) - remap or remove those "
                              f"references first."},
                    status_code=409,
                )
            conn.execute(text(
                "DELETE FROM fw_routes WHERE device_id = :did AND interface_name = :iface"
            ), {"did": did, "iface": iname})
            if target_device_id:
                _prune_target_discover(conn, int(target_device_id),
                                       "interfaces", iname)
        conn.execute(text("DELETE FROM fw_interfaces WHERE id = :id"), {"id": iface_id})
        set_needs_generate(conn, True, strand="network")
    return JSONResponse({"ok": True})


def _route_network(prefix_str: str):
    """``ipaddress.ip_network`` for a route prefix, normalizing a bare all-zeros address to the real
    DEFAULT route. A user typing ``0.0.0.0`` (default-route intent, no ``/0``) - or an explicit
    ``0.0.0.0/32`` - is widened by ``ip_network`` to a nonsensical /32 host route to 0.0.0.0, which
    then kills the zone-derive LPM catch-all downstream. There is no valid host route to the
    all-zeros address, so collapse it to ``/0`` (``::/0`` for v6). Raises ValueError like
    ``ip_network`` on a genuinely bad prefix."""
    net = ipaddress.ip_network(prefix_str, strict=False)
    if net.prefixlen == net.max_prefixlen and int(net.network_address) == 0:
        net = ipaddress.ip_network("::/0" if net.version == 6 else "0.0.0.0/0")
    return net


@app.post("/routes/add", response_class=JSONResponse)
async def route_add(request: Request):
    body = await request.json()
    device_id = body.get("device_id")
    prefix_str = (body.get("prefix") or "").strip()
    iface_raw = body.get("interface_name")
    iface = (iface_raw or "").strip() if isinstance(iface_raw, str) else ""
    vr = (body.get("vr_name") or "default").strip()
    nh_raw = body.get("next_hop")
    next_hop = (nh_raw or "").strip() or None if isinstance(nh_raw, str) else None
    route_type = (body.get("route_type") or "static").strip().lower()
    if route_type not in ("static", "blackhole"):
        return JSONResponse(
            {"error": f"invalid route_type {route_type!r} - expected static or blackhole"},
            status_code=400,
        )
    if not device_id or not prefix_str:
        return JSONResponse({"error": "device_id and prefix required"}, status_code=400)
    # Composite (SW-C): a Panorama DG's routes live in its template.
    with get_engine().connect() as _nc:
        device_id = _pano_net_device_id(_nc, device_id)
    if route_type == "static" and not iface:
        return JSONResponse({"error": "interface_name required for static routes"}, status_code=400)
    if route_type == "blackhole":
        # Discard routes don't carry iface / next-hop - null them so the
        # row matches what /update would write and the renderer's blackhole
        # branch fires unambiguously.
        iface = ""
        next_hop = None
    try:
        net = _route_network(prefix_str)
    except ValueError:
        return JSONResponse({"error": f"Invalid prefix: {prefix_str}"}, status_code=400)
    if next_hop:
        try:
            ipaddress.ip_address(next_hop)
        except ValueError:
            return JSONResponse({"error": f"Invalid next hop IP: {next_hop}"}, status_code=400)
    metric_raw = body.get("metric")
    metric_val: int | None = None
    if metric_raw not in (None, ""):
        try:
            metric_val = int(metric_raw)
        except (TypeError, ValueError):
            return JSONResponse({"error": f"invalid metric: {metric_raw!r}"}, status_code=400)
        if metric_val < 0 or metric_val > 65535:
            return JSONResponse({"error": "metric out of range (0..65535)"}, status_code=400)
    engine = get_engine()
    with engine.begin() as conn:
        conn.execute(text("""
            INSERT IGNORE INTO fw_routes
                (device_id, prefix, prefix_len, ip_from, ip_to, interface_name,
                 next_hop, vr_name, metric, route_type)
            VALUES (:did, :prefix, :plen, :ip_from, :ip_to, :iface, :nh, :vr,
                    :metric, :rtype)
        """), {
            "did": device_id, "prefix": str(net), "plen": net.prefixlen,
            "ip_from": int(net.network_address), "ip_to": int(net.broadcast_address),
            "iface": iface or None, "nh": next_hop, "vr": vr,
            "metric": metric_val, "rtype": route_type,
        })
        set_needs_generate(conn, True, strand="network")
    return JSONResponse({"ok": True})


@app.post("/routes/{route_id}/update", response_class=JSONResponse)
async def route_update(route_id: int, request: Request):
    body = await request.json()
    engine = get_engine()
    sets, params = [], {"id": route_id}
    if "prefix" in body:
        raw = (body.get("prefix") or "").strip()
        if not raw:
            return JSONResponse({"error": "prefix cannot be empty"}, status_code=400)
        try:
            net = _route_network(raw)
        except ValueError:
            return JSONResponse({"error": f"invalid prefix: {raw}"}, status_code=400)
        sets.append("prefix = :prefix")
        sets.append("prefix_len = :plen")
        sets.append("ip_from = :ip_from")
        sets.append("ip_to = :ip_to")
        params["prefix"] = str(net)
        params["plen"] = net.prefixlen
        params["ip_from"] = int(net.network_address)
        params["ip_to"] = int(net.broadcast_address)
    if "next_hop" in body:
        nh_val = (body.get("next_hop") or "").strip() or None
        if nh_val:
            try:
                ipaddress.ip_address(nh_val)
            except ValueError:
                return JSONResponse({"error": f"Invalid next hop IP: {nh_val}"}, status_code=400)
        sets.append("next_hop = :nh")
        params["nh"] = nh_val
    if "interface_name" in body:
        iface_val = (body.get("interface_name") or "").strip()
        if not iface_val:
            return JSONResponse({"error": "interface_name cannot be empty"}, status_code=400)
        sets.append("interface_name = :iname")
        params["iname"] = iface_val
    if "metric" in body:
        m_raw = body["metric"]
        if m_raw in (None, ""):
            sets.append("metric = NULL")
        else:
            try:
                m_val = int(m_raw)
            except (TypeError, ValueError):
                return JSONResponse({"error": f"invalid metric: {m_raw!r}"}, status_code=400)
            if m_val < 0 or m_val > 65535:
                return JSONResponse({"error": "metric out of range (0..65535)"}, status_code=400)
            sets.append("metric = :metric")
            params["metric"] = m_val
    if "route_type" in body:
        rt_raw = (body.get("route_type") or "").strip().lower()
        if rt_raw not in ("static", "blackhole"):
            return JSONResponse(
                {"error": f"invalid route_type {rt_raw!r} - expected static or blackhole"},
                status_code=400,
            )
        sets.append("route_type = :rtype")
        params["rtype"] = rt_raw
        # Blackhole routes don't carry a next-hop or interface - clear them
        # so the renderer sees an unambiguous discard row regardless of the
        # legacy values that the user might have set earlier.
        if rt_raw == "blackhole":
            sets.append("next_hop = NULL")
            sets.append("interface_name = NULL")
    if not sets:
        return JSONResponse({"error": "nothing to update"}, status_code=400)
    with engine.begin() as conn:
        conn.execute(text(f"UPDATE fw_routes SET {', '.join(sets)} WHERE id = :id"), params)
        if "prefix" in body:
            set_needs_generate(conn, True, strand="network")
    return JSONResponse({"ok": True})


@app.post("/routes/{route_id}/delete", response_class=JSONResponse)
async def route_delete(route_id: int, net_did: int = 0):
    engine = get_engine()
    with engine.begin() as conn:
        if net_did:   # P3: block deleting a route inherited from a member template (read-only here)
            _rd = conn.execute(text("SELECT device_id FROM fw_routes WHERE id = :id"),
                               {"id": route_id}).scalar()
            if _rd is not None and _pano_inherited_write_block(_rd, net_did):
                return JSONResponse({"error": "This route is inherited from a member template "
                                     "(read-only in the effective view). Switch the network scope "
                                     "to that template to delete it."}, status_code=409)
        conn.execute(text("DELETE FROM fw_routes WHERE id = :id"), {"id": route_id})
        set_needs_generate(conn, True, strand="network")
    return JSONResponse({"ok": True})


@app.post("/rules/bulk-delete", response_class=JSONResponse)
async def rules_bulk_delete(request: Request):
    """Remove the imported rows that produced the given content_hashes.

    The pipeline always reads from fw_imported_rules, so deleting at
    that tier guarantees the rules stay gone after the next Generate.
    We resolve content_hash → (device_host, rule_name) via
    fw_rules_consolidated_1 (the first stage already carries the hash
    next to the imported identity), then DELETE the corresponding
    imported rows by (device_id, rule_name).

    We also clear the rows from fw_rules_consolidated_1 so the user
    sees the removal immediately without waiting for Generate; the
    next pipeline run won't re-add them because the source is gone.

    Body: {rule_hashes: ["<hex40>", ...]}
    Returns: {ok, deleted}
    """
    body = await request.json()
    raw_hashes = body.get("rule_hashes") or []
    hash_bytes: list[bytes] = []
    for h in raw_hashes:
        if isinstance(h, str) and len(h) == 40:
            try:
                hash_bytes.append(bytes.fromhex(h))
            except ValueError:
                continue
    if not hash_bytes:
        return JSONResponse({"error": "no valid rule_hashes"}, status_code=400)

    engine = get_engine()
    deleted = 0
    with engine.begin() as conn:
        # device_host → device_id once, joined with the imported rows.
        # Pre-pipeline rules carry device_host (from collector); the JOIN
        # back to fw_devices is on host_name OR display_name.
        rows = conn.execute(text(
            "SELECT DISTINCT device_host, rule_name "
            "FROM fw_rules_consolidated_1 "
            "WHERE content_hash IN :hashes"
        ).bindparams(bindparam("hashes", expanding=True)),
            {"hashes": hash_bytes},
        ).fetchall()
        for device_host, rule_name in rows:
            if not device_host or not rule_name:
                continue
            dev_row = conn.execute(text(
                "SELECT id FROM fw_devices "
                "WHERE host_name = :h OR display_name = :h LIMIT 1"
            ), {"h": device_host}).fetchone()
            if not dev_row:
                continue
            did = int(dev_row[0])
            res = conn.execute(text(
                "DELETE FROM fw_imported_rules "
                "WHERE device_id = :did AND rule_name = :n"
            ), {"did": did, "n": rule_name})
            deleted += int(getattr(res, "rowcount", 0) or 0)

        # Prune consolidated_1 so the UI reflects the change before the
        # next Generate. Downstream stages get rebuilt by Generate.
        conn.execute(text(
            "DELETE FROM fw_rules_consolidated_1 WHERE content_hash IN :hashes"
        ).bindparams(bindparam("hashes", expanding=True)),
            {"hashes": hash_bytes},
        )
        set_needs_generate(conn, True, strand="policy")

    return JSONResponse({"ok": True, "deleted": deleted})


@app.post("/zones/add", response_class=JSONResponse)
async def zone_add(request: Request):
    body = await request.json()
    name = (body.get("name") or "").strip()
    color = body.get("color", "blue")
    device_id = body.get("device_id")
    if not name or not device_id:
        return JSONResponse({"error": "zone name and device_id required"}, status_code=400)
    # Composite (SW-C): a Panorama DG's zones live in its template.
    with get_engine().connect() as _nc:
        device_id = _pano_net_device_id(_nc, device_id)
    if color not in ZONE_PALETTE:
        color = "blue"
    engine = get_engine()
    with engine.begin() as conn:
        clash = conn.execute(text(
            "SELECT id FROM fw_zones WHERE device_id = :did AND name = :n"
        ), {"did": device_id, "n": name}).fetchone()
        if clash:
            return JSONResponse({"error": "zone with that name already exists"}, status_code=409)
        res = conn.execute(text(
            "INSERT INTO fw_zones (device_id, name, color) VALUES (:did, :n, :c)"
        ), {"did": device_id, "n": name, "c": color})
        new_id = res.lastrowid if hasattr(res, "lastrowid") else None
    return JSONResponse({"ok": True, "id": new_id})


@app.post("/zones/{zone_id}/delete", response_class=JSONResponse)
async def zone_delete(zone_id: int, net_did: int = 0, cascade: int = 0):
    engine = get_engine()
    with engine.begin() as conn:
        row = conn.execute(text(
            "SELECT device_id, name FROM fw_zones WHERE id = :id"
        ), {"id": zone_id}).fetchone()
        if not row:
            return JSONResponse({"error": "zone not found"}, status_code=404)
        device_id, name = row[0], row[1]
        if _pano_inherited_write_block(device_id, net_did):   # P3: inherited zone = read-only here
            return JSONResponse({"error": "This zone is inherited from a member template "
                                 "(read-only in the effective view). Switch the network scope "
                                 "to that template to delete it."}, status_code=409)
        # REF-1: block the delete if ANYTHING references this zone - interfaces,
        # rules, NAT or PBF (via the central reference engine; supersedes the old
        # interface-only check). Deleting a referenced zone would empty a rule's
        # zone field → silently widen to "any".
        refs = refmodel.find_referrers(conn, device_id, "zone", name)
        if refs and not cascade:
            counts: dict[str, int] = {}
            for r in refs:
                counts[r.referrer_kind] = counts.get(r.referrer_kind, 0) + 1
            summary = ", ".join(f"{c} {k}" for k, c in sorted(counts.items()))
            members = [r[0] for r in conn.execute(text(
                "SELECT interface_name FROM fw_interfaces "
                "WHERE device_id = :did AND zone_name = :zn"),
                {"did": device_id, "zn": name}).fetchall()]
            return JSONResponse(
                {"error": f"zone '{name}' is referenced by {summary} - "
                          "remove those references first",
                 "cascade_available": bool(members),
                 "member_interfaces": members},
                status_code=409,
            )
        if refs and cascade:
            # Cascade: repoint every RULE reference from the zone to its member
            # interfaces (per-rule multi-value overrides, source='manual'), then
            # release the interfaces from the zone. Rules only - a NAT/PBF
            # reference still blocks (their zone slots have no iface semantics).
            members = [r[0] for r in conn.execute(text(
                "SELECT interface_name FROM fw_interfaces "
                "WHERE device_id = :did AND zone_name = :zn"),
                {"did": device_id, "zn": name}).fetchall()]
            if not members:
                return JSONResponse(
                    {"error": f"zone '{name}' has no member interfaces - "
                              "nothing to repoint the rule references to"},
                    status_code=409)
            blockers = sorted({r.referrer_kind for r in refs
                               if r.referrer_kind not in ("access_rule", "interface")})
            if blockers:
                return JSONResponse(
                    {"error": f"zone '{name}' is also referenced by "
                              f"{', '.join(blockers)} - the cascade only covers "
                              "security rules; remove those references first"},
                    status_code=409)
            n_rules = 0
            rows = conn.execute(text(
                "SELECT r.content_hash, r.src_zone, r.dst_zone, o.src_zone, o.dst_zone "
                "FROM fw_rules_consolidated_1 r "
                "JOIN fw_devices d ON (d.display_name = r.device_host "
                "                      OR d.host_name = r.device_host) "
                "LEFT JOIN fw_rule_zone_overrides o ON o.rule_hash = r.content_hash "
                "WHERE d.id = :did"), {"did": device_id}).fetchall()
            for rh, imp_src, imp_dst, ov_src, ov_dst in rows:
                def _eff(ov, imp):
                    if ov:
                        return [z for z in ov.split("\n") if z]
                    return [imp] if imp else []
                cur_src, cur_dst = _eff(ov_src, imp_src), _eff(ov_dst, imp_dst)
                if name not in cur_src and name not in cur_dst:
                    continue
                def _sub(lst):
                    out: list[str] = []
                    for z in lst:
                        out.extend(members if z == name else [z])
                    return "\n".join(dict.fromkeys(out))
                conn.execute(text("""
                    INSERT INTO fw_rule_zone_overrides (rule_hash, src_zone, dst_zone, source)
                    VALUES (:rh, :src, :dst, 'manual')
                    ON DUPLICATE KEY UPDATE src_zone = VALUES(src_zone),
                                            dst_zone = VALUES(dst_zone),
                                            source = 'manual'
                """), {"rh": rh, "src": _sub(cur_src), "dst": _sub(cur_dst)})
                n_rules += 1
            conn.execute(text(
                "UPDATE fw_interfaces SET zone_name = NULL "
                "WHERE device_id = :did AND zone_name = :zn"),
                {"did": device_id, "zn": name})
            conn.execute(text("DELETE FROM fw_zones WHERE id = :id"), {"id": zone_id})
            set_needs_generate(conn, True)
            return JSONResponse({"ok": True, "cascaded_rules": n_rules,
                                 "member_interfaces": members})
        conn.execute(text("DELETE FROM fw_zones WHERE id = :id"), {"id": zone_id})
    return JSONResponse({"ok": True})


def _decode_zone_props(raw) -> dict:
    if isinstance(raw, str) and raw:
        try:
            return json.loads(raw) or {}
        except Exception:
            return {}
    if isinstance(raw, dict):
        return dict(raw)
    return {}


def _apply_props_patch(current: dict, patch: dict, platform: str | None) -> dict:
    """Merge a partial properties patch into ``current`` against the platform
    schema. Unknown keys are ignored; values that coerce to None drop the
    slot from the result. Returns the merged dict (not mutated)."""
    allowed = zone_field_keys(platform)
    schema_fields = {f["key"]: f for f in zone_schema_for(platform).get("fields") or []}
    out = dict(current)
    for key, raw in patch.items():
        if key not in allowed:
            continue
        coerced = zone_coerce_value(schema_fields[key], raw)
        if coerced is None:
            out.pop(key, None)
        else:
            out[key] = coerced
    return out


@app.get("/zones/{zone_id}", response_class=JSONResponse)
async def zone_get(zone_id: int):
    """Read a single zone with decoded properties + derived members list."""
    engine = get_engine()
    with engine.connect() as conn:
        row = conn.execute(text(
            "SELECT id, device_id, name, color, properties, import_zone_name, is_external "
            "FROM fw_zones WHERE id = :id"
        ), {"id": zone_id}).mappings().fetchone()
        if not row:
            return JSONResponse({"error": "zone not found"}, status_code=404)
        zone = dict(row)
        zone["properties"] = _decode_zone_props(zone.get("properties"))
        zone["members"] = [
            r[0] for r in conn.execute(text(
                "SELECT interface_name FROM fw_interfaces "
                "WHERE device_id = :did AND zone_name = :n ORDER BY interface_name"
            ), {"did": zone["device_id"], "n": zone["name"]}).fetchall()
        ]
    return JSONResponse(zone)


@app.patch("/zones/{zone_id}", response_class=JSONResponse)
async def zone_patch(zone_id: int, request: Request):
    """Partial update - name (cascade-rename), color, properties (schema-validated).

    Body fields: ``name``, ``color``, ``properties`` (dict), ``target_platform``.
    Returns 409 if a rename would collide with another zone on the same device.
    """
    body = await request.json()
    new_name  = body.get("name")
    new_color = body.get("color")
    new_props = body.get("properties")
    target_platform = (body.get("target_platform") or "").strip().lower() or None
    if new_color is not None and new_color not in ZONE_PALETTE:
        return JSONResponse({"error": "invalid color"}, status_code=400)
    engine = get_engine()
    with engine.begin() as conn:
        row = conn.execute(text(
            "SELECT device_id, name, properties, is_external FROM fw_zones WHERE id = :id"
        ), {"id": zone_id}).fetchone()
        if not row:
            return JSONResponse({"error": "zone not found"}, status_code=404)
        device_id, old_name, props_raw, old_is_external = row[0], row[1], row[2], row[3]

        if new_name is not None:
            n = str(new_name).strip()
            if not n:
                return JSONResponse({"error": "name cannot be empty"}, status_code=400)
            if n != old_name:
                clash = conn.execute(text(
                    "SELECT 1 FROM fw_zones WHERE device_id = :did AND name = :n AND id <> :id"
                ), {"did": device_id, "n": n, "id": zone_id}).fetchone()
                if clash:
                    return JSONResponse({"error": "zone with that name already exists"}, status_code=409)
                refmodel.cascade_rename(conn, device_id, "zone", old_name, n)
                conn.execute(text(
                    "UPDATE fw_zones SET name = :n WHERE id = :id"
                ), {"n": n, "id": zone_id})
                old_name = n

        if new_color is not None:
            conn.execute(text(
                "UPDATE fw_zones SET color = :c WHERE id = :id"
            ), {"c": new_color, "id": zone_id})

        # is_external - user-authoritative WAN flag (supersedes the seed default;
        # read by 27_infer_nat_rules to identify the external zone). nat-evidence P2.
        # A change re-shapes inferred NAT, so mark the pipeline stale (network
        # strand - same domain as interface/zone/route edits).
        if "is_external" in body:
            new_is_external = 1 if body.get("is_external") else 0
            if new_is_external != (old_is_external or 0):
                conn.execute(text(
                    "UPDATE fw_zones SET is_external = :x WHERE id = :id"
                ), {"x": new_is_external, "id": zone_id})
                set_needs_generate(conn, True, strand="network")

        if isinstance(new_props, dict):
            merged = _apply_props_patch(_decode_zone_props(props_raw), new_props, target_platform)
            conn.execute(text(
                "UPDATE fw_zones SET properties = :p WHERE id = :id"
            ), {"p": json.dumps(merged) if merged else None, "id": zone_id})
    return JSONResponse({"ok": True})


@app.post("/zones/bulk", response_class=JSONResponse)
async def zones_bulk(request: Request):
    """Bulk-apply property updates to a list of zones.

    Body: ``{"zone_ids": [int,...], "properties": {key: value}, "target_platform": str}``.
    Properties are schema-validated; unknown keys ignored, None-coerced
    values drop the slot. Each zone's existing properties are merged with
    the patch (per-key replace, not full overwrite).
    """
    body = await request.json()
    zone_ids = body.get("zone_ids") or []
    new_props = body.get("properties") or {}
    target_platform = (body.get("target_platform") or "").strip().lower() or None
    if not isinstance(zone_ids, list) or not zone_ids:
        return JSONResponse({"error": "zone_ids required"}, status_code=400)
    if not isinstance(new_props, dict) or not new_props:
        return JSONResponse({"error": "properties required"}, status_code=400)
    updated = 0
    engine = get_engine()
    with engine.begin() as conn:
        for zid in zone_ids:
            try:
                zid_int = int(zid)
            except (TypeError, ValueError):
                continue
            row = conn.execute(text(
                "SELECT properties FROM fw_zones WHERE id = :id"
            ), {"id": zid_int}).fetchone()
            if not row:
                continue
            merged = _apply_props_patch(_decode_zone_props(row[0]), new_props, target_platform)
            conn.execute(text(
                "UPDATE fw_zones SET properties = :p WHERE id = :id"
            ), {"p": json.dumps(merged) if merged else None, "id": zid_int})
            updated += 1
    return JSONResponse({"ok": True, "updated": updated})


# ─── NAT Rules (Phase C - UI-Editing) ──────────────────────────────
# Endpoints mirror the Zone-CRUD shape - same pattern of
# schema-validated properties, hash-aware identity (Phase A), and
# 409 on UNIQUE(device_id, name) conflicts. Hash-input fields
# (nat_type, zones, orig_*, trans_*) are NOT user-editable in V1 -
# changing them would mean a different rule identity (Phase A
# decision); use Delete+Add or Re-Import instead.

_NAT_PATCHABLE_COLS = ("name", "description", "disabled")


def _decode_nat_props(raw) -> dict:
    """JSON-decode the fw_nat_rules.properties cell; returns {} on
    None/empty/invalid."""
    if isinstance(raw, str) and raw:
        try:
            return json.loads(raw) or {}
        except Exception:
            return {}
    if isinstance(raw, dict):
        return dict(raw)
    return {}


def _apply_nat_props_patch(current: dict, patch: dict, platform: str | None) -> dict:
    """Merge a partial properties patch into ``current`` against the
    nat_schemas vocabulary. Unknown keys are dropped; values that
    coerce to None drop the slot from the result."""
    allowed = nat_field_keys(platform)
    fields_map = {f["key"]: f for f in nat_schema_for(platform).get("fields") or []}
    out = dict(current)
    for key, raw in patch.items():
        if key not in allowed:
            continue
        coerced = nat_coerce_value(fields_map[key], raw)
        if coerced is None:
            out.pop(key, None)
        else:
            out[key] = coerced
    return out


_NAT_FRAGMENT_MODES = ("editor", "enrichment")


@app.get("/nat-rules/list-fragment", response_class=HTMLResponse)
def nat_rules_list_fragment_early(request: Request, device: str = "",
                                   target: str = "", mode: str = "editor"):
    """HTMX list-fragment. Declared BEFORE /nat-rules/{rule_id} so FastAPI
    matches the literal-path route first (otherwise "list-fragment" gets
    routed into the int-parametric handler → 422).

    `mode` query-param selects between editor (Ruleset > NAT) and enrichment
    (Enrichment > NAT) rendering. Both modes share _load_nat_rules; enrichment
    additionally provides nat_schema + nat_catalogs for the schema-driven
    bulk-form. Body lives in nat_rules_list_fragment further below."""
    return nat_rules_list_fragment(request, device=device, target=target, mode=mode)


@app.get("/enrichment/tags/list-fragment", response_class=HTMLResponse)
def enrichment_tags_list_fragment(request: Request, device: str = "", target: str = ""):
    """Tag-Catalog list fragment for Enrichment > Tags Sub-Tab.

    Returns the source-device's fw_tags rows + the target-platform's
    tag_schemas SCHEMA so the template can render the schema-driven
    color/comments editor columns. Forti-target returns an empty
    schema → template shows a helpful "no tags concept" hint.
    """
    from tag_schemas import tag_schema_for
    engine = get_engine()
    with engine.connect() as conn:
        source_id = None
        if device:
            row = conn.execute(text(
                "SELECT id FROM fw_devices "
                "WHERE host_name = :h OR display_name = :h LIMIT 1"
            ), {"h": device}).fetchone()
            if row:
                source_id = int(row[0])
        tags = []
        if source_id:
            tag_rows = conn.execute(text(
                "SELECT id, name, properties, source FROM fw_tags "
                "WHERE device_id = :id ORDER BY name"
            ), {"id": source_id}).fetchall()
            for tid, tname, tprops, tsource in tag_rows:
                props = json.loads(tprops) if isinstance(tprops, str) and tprops else (tprops or {})
                tags.append({"id": tid, "name": tname, "properties": props, "source": tsource})
        target_platform = None
        if target:
            tp = conn.execute(text(
                "SELECT platform FROM fw_devices WHERE id = :id"
            ), {"id": target}).scalar()
            target_platform = tp or None
    return templates.TemplateResponse(request, "tags_fragment.html", {
        "tags":               tags,
        "tag_schema":         tag_schema_for(target_platform),
        "target_platform":    target_platform,
        "source_device_id":   source_id,
        "source_device_host": device or "",
        "target_id":          (target or ""),
    })


@app.post("/tags/add", response_class=JSONResponse)
async def tag_add(request: Request):
    """Add a new tag to fw_tags with source='manual'."""
    body = await request.json()
    name = (body.get("name") or "").strip()
    device_id = body.get("device_id")
    properties = body.get("properties") or {}
    if not name or not device_id:
        return JSONResponse({"error": "name and device_id required"}, status_code=400)
    engine = get_engine()
    try:
        with engine.begin() as conn:
            conn.execute(text("""
                INSERT INTO fw_tags (device_id, name, properties, source)
                VALUES (:did, :n, :p, 'manual')
            """), {"did": int(device_id), "n": name, "p": json.dumps(properties)})
    except Exception as e:
        return JSONResponse({"error": str(e)}, status_code=409)
    return JSONResponse({"ok": True})


@app.patch("/tags/{tag_id}", response_class=JSONResponse)
async def tag_patch(tag_id: int, request: Request):
    """Update a single property-field on a tag. Promotes source to 'manual'
    so the User-edit survives re-import."""
    body = await request.json()
    field = (body.get("field") or "").strip()
    value = body.get("value")
    if not field:
        return JSONResponse({"error": "field required"}, status_code=400)
    engine = get_engine()
    with engine.begin() as conn:
        row = conn.execute(text(
            "SELECT properties FROM fw_tags WHERE id = :id"
        ), {"id": tag_id}).fetchone()
        if not row:
            return JSONResponse({"error": "tag not found"}, status_code=404)
        props = json.loads(row[0]) if isinstance(row[0], str) and row[0] else (row[0] or {})
        if value in (None, ""):
            props.pop(field, None)
        else:
            props[field] = value
        conn.execute(text(
            "UPDATE fw_tags SET properties = :p, source = 'manual' WHERE id = :id"
        ), {"p": json.dumps(props), "id": tag_id})
    return JSONResponse({"ok": True})


@app.post("/tags/bulk-apply", response_class=JSONResponse)
async def tags_bulk_apply(request: Request):
    """Apply a tag-set + optional pa_group_tag to a list of rule_hashes.
    Writes to fw_rule_tag_overrides with source='manual'.

    Body: {
      rule_hashes: ["<hex-sha1>", ...],
      tags: ["web", "prod"],            // optional list (empty = no change)
      pa_group_tag: "web",              // optional; "__clear__" wipes
      target_platform: "panw"|"checkpoint",
      clear: true|false                 // true = wipe all tag-overrides
    }
    """
    body = await request.json()
    raw_hashes = body.get("rule_hashes") or []
    target_platform = (body.get("target_platform") or "").lower()
    do_clear = bool(body.get("clear"))
    tags_list = body.get("tags") or []
    group_tag = body.get("pa_group_tag")

    if not raw_hashes:
        return JSONResponse({"error": "no rule_hashes"}, status_code=400)

    hash_bytes_list: list[bytes] = []
    for h in raw_hashes:
        try:
            hash_bytes_list.append(bytes.fromhex(h))
        except ValueError:
            pass
    if not hash_bytes_list:
        return JSONResponse({"error": "no valid rule_hashes"}, status_code=400)

    engine = get_engine()
    written = 0
    with engine.begin() as conn:
        if do_clear:
            ph = ", ".join(f":h{i}" for i in range(len(hash_bytes_list)))
            params = {f"h{i}": h for i, h in enumerate(hash_bytes_list)}
            result = conn.execute(text(
                f"DELETE FROM fw_rule_tag_overrides WHERE rule_hash IN ({ph})"
            ), params)
            return JSONResponse({"ok": True, "cleared": result.rowcount})

        # Pick column based on target platform
        cols: dict = {}
        if target_platform == "panw":
            if tags_list:
                cols["pa_tags"] = json.dumps([t for t in tags_list if t])
            if group_tag == "__clear__":
                cols["pa_group_tag"] = None
            elif group_tag:
                cols["pa_group_tag"] = group_tag
        elif target_platform == "checkpoint":
            if tags_list:
                cols["cp_tags"] = json.dumps([t for t in tags_list if t])
        if not cols:
            return JSONResponse({"error": "no tag fields to apply"}, status_code=400)

        col_list = ", ".join(cols.keys())
        val_ph = ", ".join(f":{c}" for c in cols)
        upd = ", ".join(f"{c} = VALUES({c})" for c in cols)
        for h in hash_bytes_list:
            params = {c: v for c, v in cols.items()}
            params["h"] = h
            conn.execute(text(f"""
                INSERT INTO fw_rule_tag_overrides (rule_hash, {col_list}, source)
                VALUES (:h, {val_ph}, 'manual')
                ON DUPLICATE KEY UPDATE
                  {upd}, source = 'manual'
            """), params)
            written += 1
    return JSONResponse({"ok": True, "written": written})


@app.post("/tags/apply", response_class=JSONResponse)
async def tags_apply(request: Request):
    """Apply an action to a list of rule_hashes.

    Body: {
      rule_hashes: ["<hex-sha1>", ...],
      action: "add_tag"|"add_group_tag"|"remove_tag"|"remove_group_tag"|"remove_all_tags",
      tags: [...],                  # for add_tag / remove_tag (single-element ok)
      target_platform: "panw"|"checkpoint"
    }

    Semantics:
      add_tag         - merges each tag into existing pa_tags/cp_tags
                        (PA col by target, CP col by target). No-op for
                        already-present tags.
      add_group_tag   - sets pa_group_tag to tags[0] (PA only).
      remove_tag      - wipes the full pa_tags/cp_tags array (UI label:
                        "Remove all tags"). Preserves pa_group_tag.
      remove_group_tag- sets pa_group_tag = NULL.
      remove_all_tags - DELETEs the entire fw_rule_tag_overrides row
                        (UI label: "Remove all tags and group-tags").
    """
    body = await request.json()
    raw_hashes = body.get("rule_hashes") or []
    action = body.get("action") or ""
    tags_in = body.get("tags") or []
    target_platform = (body.get("target_platform") or "").lower()

    if action not in ("add_tag", "add_group_tag", "remove_tag",
                       "remove_group_tag", "remove_all_tags"):
        return JSONResponse({"error": f"unknown action: {action}"}, status_code=400)
    if not raw_hashes:
        return JSONResponse({"error": "no rule_hashes"}, status_code=400)

    hash_bytes_list: list[bytes] = []
    for h in raw_hashes:
        try:
            hash_bytes_list.append(bytes.fromhex(h))
        except ValueError:
            pass
    if not hash_bytes_list:
        return JSONResponse({"error": "no valid rule_hashes"}, status_code=400)

    # Which JSON column to touch based on target
    if target_platform == "panw":
        tag_col = "pa_tags"
    elif target_platform == "checkpoint":
        tag_col = "cp_tags"
    else:
        tag_col = None

    # Validate tag-presence for actions that need one. remove_tag
    # wipes the whole array, so no tag-selection required anymore.
    if action == "add_tag" and not tags_in:
        return JSONResponse({"error": "no tags supplied"}, status_code=400)
    if action == "add_group_tag":
        if target_platform != "panw":
            return JSONResponse({"error": "group-tag is PA-only"}, status_code=400)
        if not tags_in:
            return JSONResponse({"error": "no tag supplied"}, status_code=400)

    engine = get_engine()
    written = 0
    with engine.begin() as conn:
        if action == "remove_all_tags":
            ph = ", ".join(f":h{i}" for i in range(len(hash_bytes_list)))
            params = {f"h{i}": h for i, h in enumerate(hash_bytes_list)}
            result = conn.execute(text(
                f"DELETE FROM fw_rule_tag_overrides WHERE rule_hash IN ({ph})"
            ), params)
            return JSONResponse({"ok": True, "deleted": result.rowcount})

        # Auto-promote: any tag name selected for add-* lands in fw_tags
        # as source='manual' for every source-device the rule originated
        # from. Keeps Catalog in sync with what's actually applied and
        # protects against the import-wipe trap (re-import deletes
        # source='import' rows; manual survives).
        if action in ("add_tag", "add_group_tag") and tags_in:
            _promote_tag_names_to_catalog(conn, tags_in, hash_bytes_list)

        for h in hash_bytes_list:
            row = conn.execute(text(
                "SELECT pa_tags, pa_group_tag, cp_tags FROM fw_rule_tag_overrides "
                "WHERE rule_hash = :h"
            ), {"h": h}).fetchone()
            cur_pa_tags = json.loads(row[0]) if row and row[0] else []
            cur_pa_group = row[1] if row else None
            cur_cp_tags = json.loads(row[2]) if row and row[2] else []

            if action == "add_tag" and tag_col:
                cur = cur_pa_tags if tag_col == "pa_tags" else cur_cp_tags
                for t in tags_in:
                    if t and t not in cur:
                        cur.append(t)
                if tag_col == "pa_tags":
                    cur_pa_tags = cur
                else:
                    cur_cp_tags = cur
            elif action == "add_group_tag":
                cur_pa_group = tags_in[0]
            elif action == "remove_tag" and tag_col:
                # Wipe the whole array - UI label "Remove all tags".
                # Group-tag stays (separate remove_group_tag action).
                if tag_col == "pa_tags":
                    cur_pa_tags = []
                else:
                    cur_cp_tags = []
            elif action == "remove_group_tag":
                cur_pa_group = None

            # Upsert (skip writing empty rows - they'd just clutter without
            # adding info; if all cols are NULL/empty after the action, DELETE)
            empty = (not cur_pa_tags) and (not cur_pa_group) and (not cur_cp_tags)
            if empty:
                conn.execute(text(
                    "DELETE FROM fw_rule_tag_overrides WHERE rule_hash = :h"
                ), {"h": h})
                written += 1
                continue
            conn.execute(text("""
                INSERT INTO fw_rule_tag_overrides
                    (rule_hash, pa_tags, pa_group_tag, cp_tags, source)
                VALUES (:h, :pat, :pgt, :cpt, 'manual')
                ON DUPLICATE KEY UPDATE
                    pa_tags      = VALUES(pa_tags),
                    pa_group_tag = VALUES(pa_group_tag),
                    cp_tags      = VALUES(cp_tags),
                    source       = 'manual'
            """), {
                "h": h,
                "pat": json.dumps(cur_pa_tags) if cur_pa_tags else None,
                "pgt": cur_pa_group,
                "cpt": json.dumps(cur_cp_tags) if cur_cp_tags else None,
            })
            written += 1
    return JSONResponse({"ok": True, "written": written})


@app.post("/tags/{tag_id}/delete", response_class=JSONResponse)
async def tag_delete(tag_id: int):
    """Delete a tag from fw_tags. No FK-cascade to rule_tag_overrides -
    the override-row stays orphan but rules_query LEFT JOIN tolerates
    a missing catalog row."""
    engine = get_engine()
    with engine.begin() as conn:
        result = conn.execute(text(
            "DELETE FROM fw_tags WHERE id = :id"
        ), {"id": tag_id})
        if result.rowcount == 0:
            return JSONResponse({"error": "tag not found"}, status_code=404)
    return JSONResponse({"ok": True})


