@app.get("/nat-rules/{rule_id}", response_class=JSONResponse)
async def nat_rule_get(rule_id: int):
    """Read a single NAT-rule with decoded JSON-arrays + properties."""
    engine = get_engine()
    with engine.connect() as conn:
        row = conn.execute(text(
            "SELECT id, device_id, position, name, nat_type, disabled, "
            "       src_zones, dst_zones, interface_name, "
            "       orig_src, orig_dst, orig_service, "
            "       trans_src, trans_src_type, trans_dst, trans_dst_port, "
            "       description, properties, HEX(nat_hash) AS nat_hash "
            "FROM fw_nat_rules WHERE id = :id"
        ), {"id": rule_id}).mappings().fetchone()
        if not row:
            return JSONResponse({"error": "nat-rule not found"}, status_code=404)
        out = dict(row)
        for jc in ("src_zones", "dst_zones", "orig_src", "orig_dst", "orig_service"):
            raw = out.get(jc)
            try:
                out[jc] = json.loads(raw) if isinstance(raw, str) else (raw or [])
            except Exception:
                out[jc] = []
        out["properties"] = _decode_nat_props(out.get("properties"))
    return JSONResponse(out)


@app.patch("/nat-rules/{rule_id}", response_class=JSONResponse)
async def nat_rule_patch(rule_id: int, request: Request):
    """Partial update of name / description / disabled / properties.

    Hash-input fields (nat_type, zones, orig_*, trans_*) are silently
    ignored - those changes belong in Delete+Add or Re-Import per
    project_nat_full_scope_plan.

    409 on UNIQUE(device_id, name) violations.
    """
    body = await request.json()
    target_platform = (body.get("target_platform") or "").strip().lower() or None
    engine = get_engine()
    with engine.begin() as conn:
        row = conn.execute(text(
            "SELECT device_id, name, properties, nat_hash FROM fw_nat_rules WHERE id = :id"
        ), {"id": rule_id}).fetchone()
        if not row:
            return JSONResponse({"error": "nat-rule not found"}, status_code=404)
        device_id, old_name, props_raw, nat_hash = row[0], row[1], row[2], row[3]

        # src_zone / dst_zone - the per-rule zone OVERLAY (fw_nat_rule_overrides,
        # same slots the route-derive writes; nat_hash-keyed → survives
        # re-import). NOT a hash-input: the base row stays untouched. Single
        # value ('' clears the slot → rule reverts to its imported zones).
        # source='manual' so read-side override markers respect the choice.
        for _key, _col in (("src_zone", "src_zones"), ("dst_zone", "dst_zones")):
            if _key not in body:
                continue
            if not nat_hash:
                return JSONResponse({"error": "nat-rule has no nat_hash"}, status_code=409)
            _val = str(body[_key] or "").strip()
            _json = json.dumps([_val]) if _val else None
            conn.execute(text(f"""
                INSERT INTO fw_nat_rule_overrides (nat_hash, {_col}, source)
                VALUES (:nh, :v, 'manual')
                ON DUPLICATE KEY UPDATE {_col} = :v, source = 'manual'
            """), {"nh": nat_hash, "v": _json})

        # Name - rename is a simple UPDATE; name is excluded from nat_hash so
        # override bindings survive. UNIQUE(device_id, name) → 409.
        if "name" in body:
            n = str(body["name"] or "").strip()
            if not n:
                return JSONResponse({"error": "name cannot be empty"}, status_code=400)
            if n != old_name:
                clash = conn.execute(text(
                    "SELECT 1 FROM fw_nat_rules WHERE device_id = :did AND name = :n AND id <> :id"
                ), {"did": device_id, "n": n, "id": rule_id}).fetchone()
                if clash:
                    return JSONResponse({"error": "nat-rule with that name already exists"}, status_code=409)
                conn.execute(text(
                    "UPDATE fw_nat_rules SET name = :n WHERE id = :id"
                ), {"n": n, "id": rule_id})

        # description / disabled - straight UPDATE
        if "description" in body:
            conn.execute(text(
                "UPDATE fw_nat_rules SET description = :d WHERE id = :id"
            ), {"d": (body["description"] or "") or None, "id": rule_id})

        if "disabled" in body:
            val = body["disabled"]
            if isinstance(val, str):
                val = val.strip().lower() in ("1", "true", "yes", "on")
            conn.execute(text(
                "UPDATE fw_nat_rules SET disabled = :d WHERE id = :id"
            ), {"d": 1 if val else 0, "id": rule_id})

        # properties - schema-validated merge (Phase D fills the schema;
        # Phase C accepts any platform with empty whitelist → no-op)
        if isinstance(body.get("properties"), dict):
            merged = _apply_nat_props_patch(
                _decode_nat_props(props_raw),
                body["properties"],
                target_platform,
            )
            conn.execute(text(
                "UPDATE fw_nat_rules SET properties = :p WHERE id = :id"
            ), {"p": json.dumps(merged) if merged else None, "id": rule_id})
    return JSONResponse({"ok": True})


@app.post("/nat-rules/add", response_class=JSONResponse)
async def nat_rule_add(request: Request):
    """Create a NAT-rule. Required: device_id, name, nat_type.
    Optional everything else (with safe defaults). Returns the new id.
    409 on name-collision."""
    body = await request.json()
    device_id = body.get("device_id")
    name = (body.get("name") or "").strip()
    nat_type = (body.get("nat_type") or "").strip().lower()
    if not device_id or not name or nat_type not in ("snat", "dnat", "static"):
        return JSONResponse(
            {"error": "device_id, name, nat_type (snat|dnat|static) required"},
            status_code=400,
        )
    trans_src_type = (body.get("trans_src_type") or "none").strip().lower()
    if trans_src_type not in ("static-ip", "dynamic-ip", "dynamic-ip-and-port",
                              "interface-address", "none"):
        return JSONResponse({"error": "invalid trans_src_type"}, status_code=400)

    def _arr(v) -> list:
        if isinstance(v, list):
            return [str(x) for x in v if x]
        return []

    engine = get_engine()
    with engine.begin() as conn:
        clash = conn.execute(text(
            "SELECT id FROM fw_nat_rules WHERE device_id = :did AND name = :n"
        ), {"did": device_id, "n": name}).fetchone()
        if clash:
            return JSONResponse({"error": "nat-rule with that name already exists"}, status_code=409)
        next_pos = conn.execute(text(
            "SELECT COALESCE(MAX(position), -1) + 1 FROM fw_nat_rules WHERE device_id = :did"
        ), {"did": device_id}).scalar()
        res = conn.execute(text("""
            INSERT INTO fw_nat_rules
                (device_id, position, name, nat_type, disabled,
                 src_zones, dst_zones, interface_name,
                 orig_src, orig_dst, orig_service,
                 trans_src, trans_src_type, trans_dst, trans_dst_port,
                 description)
            VALUES
                (:did, :pos, :name, :type, :dis,
                 :sz, :dz, :iface,
                 :osrc, :odst, :osvc,
                 :tsrc, :tstype, :tdst, :tdport,
                 :desc)
        """), {
            "did": device_id, "pos": next_pos, "name": name, "type": nat_type,
            "dis": 1 if body.get("disabled") else 0,
            "sz":  json.dumps(sorted(_arr(body.get("src_zones")))),
            "dz":  json.dumps(sorted(_arr(body.get("dst_zones")))),
            "iface": (body.get("interface_name") or "").strip() or None,
            "osrc": json.dumps(sorted(_arr(body.get("orig_src")))),
            "odst": json.dumps(sorted(_arr(body.get("orig_dst")))),
            "osvc": json.dumps(sorted(_arr(body.get("orig_service")))),
            "tsrc":   (body.get("trans_src") or "").strip() or None,
            "tstype": trans_src_type,
            "tdst":   (body.get("trans_dst") or "").strip() or None,
            "tdport": (body.get("trans_dst_port") or "").strip() or None,
            "desc":   (body.get("description") or "").strip() or "",
        })
        new_id = res.lastrowid if hasattr(res, "lastrowid") else None
        # Hash-compute for the new row.
        if new_id:
            _write_nat_hash(conn, "n.id = :id", {"id": new_id})
    return JSONResponse({"ok": True, "id": new_id})


@app.post("/nat-rules/{rule_id}/delete", response_class=JSONResponse)
async def nat_rule_delete(rule_id: int):
    """Delete a NAT-rule + cascade its override-row via nat_hash JOIN."""
    engine = get_engine()
    with engine.begin() as conn:
        row = conn.execute(text(
            "SELECT id FROM fw_nat_rules WHERE id = :id"
        ), {"id": rule_id}).fetchone()
        if not row:
            return JSONResponse({"error": "nat-rule not found"}, status_code=404)
        # Drop the overlay first (FK-free, JOIN-keyed on nat_hash).
        conn.execute(text(
            "DELETE o FROM fw_nat_rule_overrides o "
            "INNER JOIN fw_nat_rules n ON n.nat_hash = o.nat_hash "
            "WHERE n.id = :id"
        ), {"id": rule_id})
        conn.execute(text("DELETE FROM fw_nat_rules WHERE id = :id"), {"id": rule_id})
    return JSONResponse({"ok": True})


@app.post("/nat-rules/bulk", response_class=JSONResponse)
async def nat_rules_bulk(request: Request):
    """Bulk apply a small set of toggleable fields to N NAT-rules.

    Body: ``{"rule_ids": [int,...], "disabled": bool?, "description": str?,
              "properties": dict?, "target_platform": str?}``.
    Hash-input fields are not accepted (Phase D / Delete+Add territory).
    """
    body = await request.json()
    rule_ids = body.get("rule_ids") or []
    if not isinstance(rule_ids, list) or not rule_ids:
        return JSONResponse({"error": "rule_ids required"}, status_code=400)
    target_platform = (body.get("target_platform") or "").strip().lower() or None
    patch_props = body.get("properties") if isinstance(body.get("properties"), dict) else None
    set_desc = body["description"] if "description" in body else None
    set_dis = None
    if "disabled" in body:
        v = body["disabled"]
        if isinstance(v, str):
            v = v.strip().lower() in ("1", "true", "yes", "on")
        set_dis = 1 if v else 0
    updated = 0
    engine = get_engine()
    with engine.begin() as conn:
        for rid in rule_ids:
            try:
                rid_int = int(rid)
            except (TypeError, ValueError):
                continue
            row = conn.execute(text(
                "SELECT properties FROM fw_nat_rules WHERE id = :id"
            ), {"id": rid_int}).fetchone()
            if not row:
                continue
            if set_desc is not None:
                conn.execute(text(
                    "UPDATE fw_nat_rules SET description = :d WHERE id = :id"
                ), {"d": (set_desc or None), "id": rid_int})
            if set_dis is not None:
                conn.execute(text(
                    "UPDATE fw_nat_rules SET disabled = :d WHERE id = :id"
                ), {"d": set_dis, "id": rid_int})
            if patch_props:
                merged = _apply_nat_props_patch(
                    _decode_nat_props(row[0]), patch_props, target_platform,
                )
                conn.execute(text(
                    "UPDATE fw_nat_rules SET properties = :p WHERE id = :id"
                ), {"p": json.dumps(merged) if merged else None, "id": rid_int})
            updated += 1
    return JSONResponse({"ok": True, "updated": updated})


def nat_rules_list_fragment(request: Request, device: str = "", target: str = "",
                             mode: str = "editor"):
    """HTMX-style re-render of the NAT-rules section so the UI can refresh
    in place after Add / Edit / Delete / Bulk without a full page reload.
    Called by the literal-path-priority shim declared earlier (so the
    parametric /nat-rules/{rule_id} route doesn't intercept the path).

    `mode` ∈ {"editor", "enrichment"} - editor renders the Ruleset > NAT
    flavour (Add-Row + State-Toggle + Delete); enrichment renders the
    Enrichment > NAT flavour (extra Zone + Trans-Type columns + vendor-
    properties bulk-form). Y2 unifies both into one template; until then
    each mode picks the right template explicitly."""
    if mode not in _NAT_FRAGMENT_MODES:
        mode = "editor"
    engine = get_engine()
    with engine.connect() as conn:
        source_id = None
        if device:
            row = conn.execute(text(
                "SELECT id FROM fw_devices "
                "WHERE host_name = :h OR display_name = :h LIMIT 1"
            ), {"h": device}).fetchone()
            if row:
                source_id = int(row[0])
        nat_rules = _load_nat_rules(conn, device_id=source_id) if source_id else []
        target_platform = None
        if target:
            tp = conn.execute(text(
                "SELECT platform FROM fw_devices WHERE id = :id"
            ), {"id": target}).scalar()
            target_platform = tp or None
        # Zone options for the per-rule src/dst zone dropdowns (enrichment
        # mode). 'default' is the no-zone sentinel, never a pickable zone.
        # Interface-based target (FortiGate): srcintf/dstintf accept ZONES
        # AND interfaces (FortiOS datasource system.zone + system.interface,
        # policies and central-SNAT alike; only a VIP extintf is
        # interface-only) - offer the union, zones first. Mirrors the
        # access-rule zone bar's "iface/zone" semantics (cp2fgt finding
        # 2026-09-01).
        zone_names: list[str] = []
        if source_id:
            zone_names = [r[0] for r in conn.execute(text(
                "SELECT name FROM fw_zones WHERE device_id = :d "
                "AND name <> 'default' ORDER BY name"), {"d": source_id})]
            if target_platform == "fortigate":
                zone_names += [r[0] for r in conn.execute(text(
                    "SELECT interface_name FROM fw_interfaces WHERE device_id = :d "
                    "ORDER BY interface_name"), {"d": source_id})
                    if r[0] not in zone_names]
    ctx = {
        "nat_rules":          nat_rules,
        "nat_schema":         nat_schema_for(target_platform),
        "target_platform":    target_platform,
        "source_device_id":   source_id,
        "source_device_host": device or "",
        "target_id":          (target or ""),
        "mode":               mode,
        "zone_names":         zone_names,
    }
    if mode == "enrichment":
        ctx["nat_catalogs"] = _nat_property_catalogs(
            {"id": int(target), "platform": target_platform} if target else None
        )
    # Both modes share nat_rules_fragment.html; template branches on the
    # `mode` context variable (Y2 + Y4 - nat_enrichment_fragment.html
    # retired).
    return templates.TemplateResponse(request, "nat_rules_fragment.html", ctx)


# ─── VRFs (Slice 5) ────────────────────────────────────────────────
@app.post("/vrfs/add", response_class=JSONResponse)
async def vrf_add(request: Request):
    body = await request.json()
    name = (body.get("name") or "").strip()
    device_id = body.get("device_id")
    if not name or not device_id:
        return JSONResponse({"error": "name and device_id required"}, status_code=400)
    # Composite (SW-C): a Panorama DG's VRFs live in its template.
    with get_engine().connect() as _nc:
        device_id = _pano_net_device_id(_nc, device_id)
    engine = get_engine()
    with engine.begin() as conn:
        conn.execute(text(
            "INSERT IGNORE INTO fw_vrfs (device_id, name) VALUES (:did, :n)"
        ), {"did": device_id, "n": name})
        set_needs_generate(conn, True, strand="network")
    return JSONResponse({"ok": True})


@app.post("/vrfs/{vrf_id}/update", response_class=JSONResponse)
async def vrf_update(vrf_id: int, request: Request):
    body = await request.json()
    engine = get_engine()
    with engine.begin() as conn:
        old = conn.execute(text(
            "SELECT name, device_id, import_vr_name FROM fw_vrfs WHERE id = :id"
        ), {"id": vrf_id}).fetchone()
        if not old:
            return JSONResponse({"error": "vrf not found"}, status_code=404)
        old_name, vrf_device_id, import_vr_name = old[0], old[1], old[2]
        sets, params = [], {"id": vrf_id}
        new_name = body.get("name")
        if new_name is not None:
            new_name = new_name.strip()
            if new_name and new_name != old_name:
                # Slice 6: default VR is the system sentinel - rename rejected.
                # Sentinel is the row whose import_vr_name='default' (immutable
                # collector-side identity, even if the user has renamed it).
                if (import_vr_name or "").strip().lower() == "default":
                    return JSONResponse(
                        {"error": "default VR is the system fallback and cannot be renamed"},
                        status_code=400,
                    )
                sets.append("name = :name")
                params["name"] = new_name
                refmodel.cascade_rename(conn, vrf_device_id, "vrf", old_name, new_name)
        if sets:
            conn.execute(text(f"UPDATE fw_vrfs SET {', '.join(sets)} WHERE id = :id"), params)
            set_needs_generate(conn, True, strand="network")
    return JSONResponse({"ok": True})


@app.post("/vrfs/{vrf_id}/delete", response_class=JSONResponse)
async def vrf_delete(vrf_id: int, net_did: int = 0):
    engine = get_engine()
    with engine.begin() as conn:
        old = conn.execute(text(
            "SELECT name, device_id FROM fw_vrfs WHERE id = :id"
        ), {"id": vrf_id}).fetchone()
        if not old:
            return JSONResponse({"ok": True})
        old_name, vrf_device_id = old[0], old[1]
        if _pano_inherited_write_block(vrf_device_id, net_did):   # P3: inherited VR = read-only here
            return JSONResponse({"error": "This virtual router is inherited from a member template "
                                 "(read-only in the effective view). Switch the network scope "
                                 "to that template to delete it."}, status_code=409)
        # Re-home interfaces/routes pointing here back to 'default' so they
        # don't dangle (orphan-prevention; mirrors the soft-reference policy).
        conn.execute(text(
            "UPDATE fw_interfaces SET vr_name = 'default' "
            "WHERE vr_name = :n AND device_id = :did"
        ), {"n": old_name, "did": vrf_device_id})
        # A route whose prefix already exists in 'default' would violate
        # uq_dev_prefix_vr(device_id, prefix, vr_name) on re-home (the same subnet
        # routed in both VRs - e.g. a connected prefix). The default copy wins, so
        # drop the VRF's duplicate instead of colliding the UPDATE (was a 500).
        conn.execute(text(
            "DELETE FROM fw_routes WHERE device_id = :did AND vr_name = :n "
            "AND prefix IN (SELECT p FROM (SELECT prefix AS p FROM fw_routes "
            "WHERE device_id = :did AND vr_name = 'default') d)"
        ), {"n": old_name, "did": vrf_device_id})
        conn.execute(text(
            "UPDATE fw_routes SET vr_name = 'default' "
            "WHERE vr_name = :n AND device_id = :did"
        ), {"n": old_name, "did": vrf_device_id})
        conn.execute(text("DELETE FROM fw_vrfs WHERE id = :id"), {"id": vrf_id})
        # Make sure 'default' exists for re-homed rows.
        conn.execute(text(
            "INSERT IGNORE INTO fw_vrfs (device_id, name) VALUES (:did, 'default')"
        ), {"did": vrf_device_id})
        set_needs_generate(conn, True, strand="network")
    return JSONResponse({"ok": True})


