@app.post("/enrichment/vpn/psk", response_class=JSONResponse)
async def enrichment_vpn_psk(request: Request):
    """Set / clear an operator-supplied per-tunnel PSK (VPN PSK secret store).
    Body: ``{device_id, vpn_hash, psk}``. A non-empty ``psk`` is ENCRYPTED at
    rest (Fernet) and upserted; an empty/absent ``psk`` clears it. The plaintext
    is never stored, never returned, never logged - it is injected server-side
    into the live push only (deploy_push). Setting requires GATESHIFT_SECRET_KEY;
    clearing always works."""
    try:
        body = await request.json()
    except Exception:
        body = {}
    try:
        did = int(body.get("device_id"))
    except (TypeError, ValueError):
        return JSONResponse({"error": "device_id required"}, status_code=400)
    h = (body.get("vpn_hash") or "").strip().lower()
    if len(h) != 40 or not all(c in "0123456789abcdef" for c in h):
        return JSONResponse({"error": "valid vpn_hash required"}, status_code=400)
    hb = bytes.fromhex(h)
    psk = body.get("psk")
    psk = psk if isinstance(psk, str) else ""
    engine = get_engine()

    # Empty → clear.
    if not psk.strip():
        with engine.begin() as conn:
            conn.execute(text(
                "DELETE FROM fw_vpn_tunnel_secrets WHERE device_id = :d AND vpn_hash = :h"
            ), {"d": did, "h": hb})
        return JSONResponse({"ok": True, "psk_set": False})

    if not secrets_util.is_configured():
        return JSONResponse(
            {"error": "secret storage not configured - set GATESHIFT_SECRET_KEY "
                      "in the environment to store PSKs"},
            status_code=400)
    try:
        enc = secrets_util.encrypt(psk)
    except Exception as e:
        return JSONResponse({"error": f"encryption failed: {e}"}, status_code=500)
    with engine.begin() as conn:
        conn.execute(text("""
            INSERT INTO fw_vpn_tunnel_secrets (device_id, vpn_hash, secret_enc)
            VALUES (:d, :h, :e)
            ON DUPLICATE KEY UPDATE secret_enc = VALUES(secret_enc)
        """), {"d": did, "h": hb, "e": enc})
    return JSONResponse({"ok": True, "psk_set": True})


@app.post("/enrichment/vpn/cert", response_class=JSONResponse)
async def enrichment_vpn_cert(request: Request):
    """Upload / clear an operator-supplied per-tunnel IDENTITY cert for cert-auth
    IKE (VPN cert upload, round 2). Body:
    ``{device_id, vpn_hash, cert_pem, key_pem, passphrase?, name?}``. The cert+key
    are validated (PEM parse + key↔cert match); the cert is stored as PEM, the
    PRIVATE KEY is encrypted at rest. Empty cert_pem+key_pem clears it. The key is
    never returned, never logged - it is decrypted server-side into the live
    cert-import push step only. Storing requires GATESHIFT_SECRET_KEY."""
    try:
        body = await request.json()
    except Exception:
        body = {}
    try:
        did = int(body.get("device_id"))
    except (TypeError, ValueError):
        return JSONResponse({"error": "device_id required"}, status_code=400)
    h = (body.get("vpn_hash") or "").strip().lower()
    if len(h) != 40 or not all(c in "0123456789abcdef" for c in h):
        return JSONResponse({"error": "valid vpn_hash required"}, status_code=400)
    hb = bytes.fromhex(h)
    cert_pem = body.get("cert_pem") if isinstance(body.get("cert_pem"), str) else ""
    key_pem = body.get("key_pem") if isinstance(body.get("key_pem"), str) else ""
    engine = get_engine()

    # Empty → clear.
    if not cert_pem.strip() and not key_pem.strip():
        with engine.begin() as conn:
            conn.execute(text(
                "DELETE FROM fw_vpn_tunnel_certs WHERE device_id = :d AND vpn_hash = :h"
            ), {"d": did, "h": hb})
        return JSONResponse({"ok": True, "cert_set": False})

    if not secrets_util.is_configured():
        return JSONResponse(
            {"error": "secret storage not configured - set GATESHIFT_SECRET_KEY "
                      "in the environment to store certificate keys"},
            status_code=400)
    try:
        norm_cert, norm_key = secrets_util.validate_cert_key(
            cert_pem, key_pem, (body.get("passphrase") or None))
    except ValueError as e:
        return JSONResponse({"error": str(e)}, status_code=400)
    except Exception:
        return JSONResponse({"error": "certificate validation failed"}, status_code=400)
    cert_name = secrets_util.default_cert_name(
        norm_cert, (body.get("name") or f"gateshift-vpn-{h[:8]}"))
    if body.get("name"):
        cert_name = secrets_util._safe_cert_name(body["name"])
    try:
        key_enc = secrets_util.encrypt(norm_key)
    except Exception as e:
        return JSONResponse({"error": f"encryption failed: {e}"}, status_code=500)
    with engine.begin() as conn:
        conn.execute(text("""
            INSERT INTO fw_vpn_tunnel_certs (device_id, vpn_hash, cert_name, cert_pem, key_enc)
            VALUES (:d, :h, :n, :c, :k)
            ON DUPLICATE KEY UPDATE cert_name = VALUES(cert_name),
              cert_pem = VALUES(cert_pem), key_enc = VALUES(key_enc)
        """), {"d": did, "h": hb, "n": cert_name, "c": norm_cert, "k": key_enc})
    return JSONResponse({"ok": True, "cert_set": True, "cert_name": cert_name})


_FORTI_UTM_SLOTS = (
    "av_profile",
    "webfilter_profile",
    "dnsfilter_profile",
    "ips_sensor",
    "application_list",
    "ssl_ssh_profile",
)


@app.post("/enrichment/forti-utm/apply", response_class=JSONResponse)
async def enrichment_forti_utm_apply(request: Request):
    """Apply FortiOS per-policy UTM-profile overrides to a selection.

    Body: ``{"rule_hashes": ["<hex-sha1>", ...],
             "slots": {"av_profile": "<name>"|null, ...},
             "clear": bool}``.

    Tri-state per slot:
      - slot omitted from ``slots`` → don't touch that column (keep)
      - value ``null`` (or empty string) → set column to NULL (none → push
        skips field, FortiOS default kicks in)
      - value ``<name>`` → set column to that profile name

    ``clear=true`` deletes the row entirely (all six UTM slots back to
    target-default). Catalog of valid names is fetched separately via
    ``/enrichment/utm-profiles/{target_id}``; this endpoint trusts the
    name as-given (FortiOS rejects unknown names at push time).
    """
    try:
        body = await request.json()
    except Exception:
        body = {}
    raw_hashes = body.get("rule_hashes") or []
    clear = bool(body.get("clear"))
    slots_in = body.get("slots") or {}

    hashes: list[str] = []
    for h in raw_hashes:
        if not isinstance(h, str):
            continue
        h = h.strip().lower()
        if len(h) == 40 and all(c in "0123456789abcdef" for c in h):
            hashes.append(h)
    if not hashes:
        return JSONResponse({"error": "rule_hashes is empty or invalid"},
                            status_code=400)

    # Normalize slots: only keep recognized keys; map "" → None.
    slots: dict[str, str | None] = {}
    if not clear:
        if not isinstance(slots_in, dict):
            return JSONResponse({"error": "slots must be an object"},
                                status_code=400)
        for k, v in slots_in.items():
            if k not in _FORTI_UTM_SLOTS:
                continue
            if v is None:
                slots[k] = None
            elif isinstance(v, str):
                vs = v.strip()
                slots[k] = vs or None
            else:
                return JSONResponse(
                    {"error": f"slot {k!r} must be string or null"},
                    status_code=400)
        if not slots:
            return JSONResponse({"error": "no slots provided"},
                                status_code=400)

    engine = get_engine()
    with engine.begin() as conn:
        if clear:
            placeholders = ", ".join(f":h{i}" for i in range(len(hashes)))
            params = {f"h{i}": bytes.fromhex(h) for i, h in enumerate(hashes)}
            res = conn.execute(text(
                f"DELETE FROM fw_rule_security_profile_overrides "
                f"WHERE rule_hash IN ({placeholders})"
            ), params)
            return JSONResponse({"cleared": res.rowcount, "slots": {}})

        # Dynamic INSERT … ON DUPLICATE KEY UPDATE: only INSERT + UPDATE the
        # columns the user actually picked. Columns not in `slots` retain
        # whatever was in the row before (or NULL for fresh rows).
        cols = list(slots.keys())
        col_list = ", ".join(cols)
        val_placeholders = ", ".join(f":{c}" for c in cols)
        update_clause = ", ".join(f"{c} = VALUES({c})" for c in cols)
        sql = text(f"""
            INSERT INTO fw_rule_security_profile_overrides
              (rule_hash, {col_list}, source)
            VALUES (:h, {val_placeholders}, 'manual')
            ON DUPLICATE KEY UPDATE
              {update_clause},
              source = 'manual'
        """)
        written = 0
        for h in hashes:
            params = {c: slots[c] for c in cols}
            params["h"] = bytes.fromhex(h)
            conn.execute(sql, params)
            written += 1
    return JSONResponse({"written": written, "slots": slots})


@app.post("/enrichment/track/apply", response_class=JSONResponse)
async def enrichment_track_apply(request: Request):
    """Apply a CP track setting to a selection of rules.

    Body: ``{"rule_hashes": ["<hex-sha1>", ...], "track_type": "<name>",
             "accounting": bool, "per_session": bool, "per_connection": bool}``.
    Empty/missing ``track_type`` clears the override (deletes the row).
    Manual overrides are written with ``source='manual'`` so any future
    auto-binder will not stomp them.
    """
    try:
        body = await request.json()
    except Exception:
        body = {}
    raw_hashes = body.get("rule_hashes") or []
    track_type = (body.get("track_type") or "").strip()
    accounting = 1 if body.get("accounting") else 0
    per_session = 1 if body.get("per_session") else 0
    per_connection = 1 if body.get("per_connection", True) else 0
    hashes: list[str] = []
    for h in raw_hashes:
        if not isinstance(h, str):
            continue
        h = h.strip().lower()
        if len(h) == 40 and all(c in "0123456789abcdef" for c in h):
            hashes.append(h)
    if not hashes:
        return JSONResponse({"error": "rule_hashes is empty or invalid"},
                            status_code=400)

    engine = get_engine()
    with engine.begin() as conn:
        if not track_type:
            placeholders = ", ".join(f":h{i}" for i in range(len(hashes)))
            params = {f"h{i}": bytes.fromhex(h) for i, h in enumerate(hashes)}
            res = conn.execute(text(
                f"DELETE FROM fw_rule_track_overrides WHERE rule_hash IN ({placeholders})"
            ), params)
            return JSONResponse({"cleared": res.rowcount, "track_type": None})

        written = 0
        for h in hashes:
            conn.execute(text("""
                INSERT INTO fw_rule_track_overrides
                  (rule_hash, track_type, accounting, per_session,
                   per_connection, source)
                VALUES (:h, :t, :ac, :ps, :pc, 'manual')
                ON DUPLICATE KEY UPDATE
                  track_type     = VALUES(track_type),
                  accounting     = VALUES(accounting),
                  per_session    = VALUES(per_session),
                  per_connection = VALUES(per_connection),
                  source         = 'manual'
            """), {"h": bytes.fromhex(h), "t": track_type,
                   "ac": accounting, "ps": per_session, "pc": per_connection})
            written += 1
    return JSONResponse({"written": written, "track_type": track_type,
                         "accounting": bool(accounting),
                         "per_session": bool(per_session),
                         "per_connection": bool(per_connection)})


@app.post("/enrichment/drift/cleanup", response_class=JSONResponse)
async def enrichment_drift_cleanup(request: Request):
    """Bulk-delete every override whose rule_hash no longer matches a rule
    in the current tail table. Pair with the drift-banner: the user sees a
    count, presses cleanup, all orphans go.

    Body: ``{"table": "fw_rules_<consolidated_1|accumulated|subnet|filtered>"}``.
    Defaults to consolidated_1 since that's the always-on table."""
    try:
        body = await request.json()
    except Exception:
        body = {}
    tail = (body.get("table") or "fw_rules_consolidated_1").strip()
    if tail not in ("fw_rules_consolidated_1", "fw_rules_accumulated",
                    "fw_rules_subnet", "fw_rules_filtered"):
        return JSONResponse({"error": "invalid table"}, status_code=400)

    deleted = {}
    engine = get_engine()
    with engine.begin() as conn:
        for kind, otbl in _OVERRIDE_TABLES.items():
            res = conn.execute(text(f"""
                DELETE o FROM {otbl} o
                WHERE NOT EXISTS (
                    SELECT 1 FROM {tail} t
                    WHERE t.content_hash = o.rule_hash
                      AND t.generated_at = (
                          SELECT MAX(generated_at) FROM {tail}
                      )
                )
            """))
            deleted[kind] = int(res.rowcount or 0)
    deleted["total"] = sum(deleted.values())
    return JSONResponse(deleted)


